[hidden], .conversation-shell[hidden] { display: none !important; }
.app-shell, .app-shell.inspector-closed {
  height: 100dvh;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  overflow: hidden;
  background: var(--app-color-background-surface);
}
:focus-visible { outline-color: var(--color-accent); }
.rail {
  display: flex;
  flex-direction: column;
  width: var(--sidebar-width);
  min-width: 0;
  min-height: 0;
  overflow: auto;
  background: var(--app-color-background-surface-under);
  border-right: 1px solid var(--color-border-subtle);
}
.brand { display: flex; align-items: center; gap: 8px; padding: 20px 16px 18px; }
.brand-mark { width: 28px; height: 28px; border-radius: 8px; background: var(--color-text); color: var(--app-color-background-surface); }
.brand small { color: var(--muted); }
.rail nav { padding: 0 8px; display: grid; gap: 2px; }
.nav-section { color: var(--muted); font-size: 11px; font-weight: 500; letter-spacing: .04em; padding: 4px 8px 6px; }
.nav-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: var(--row-height);
  padding: 0 8px;
  text-align: left;
  color: var(--color-text);
  background: none;
  border: 0;
  border-radius: var(--radius-md);
  font-size: 13px;
}
.nav-icon { color: inherit; }
.nav-item:hover { background: var(--color-background-secondary-ghost-hover); }
.nav-item.active { background: var(--color-background-nav-active); color: var(--color-text); font-weight: 500; }
.nav-item.active .nav-icon { color: inherit; }
.new-chat { margin: 16px 8px 8px; }
.rail-conversations, .conversation-nav { display: grid; gap: 4px; padding: 8px; }
.rail-conversations .nav-section, .conversation-nav .nav-section { padding-bottom: 4px; }
.rail-conversations button, .conversation-nav button { width: 100%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: left; }
.rail-status { margin-top: auto; padding: 16px 16px 8px; color: var(--muted); font-size: 11px; border: 0; }
.rail-status small { margin: 8px 0 0 13px; color: var(--muted); }
.status-dot.on { background: var(--color-accent); }
.profile-button { display: flex; align-items: center; gap: 8px; flex: none; margin: 8px; padding: 8px; border: 0; border-radius: var(--radius-md); background: none; color: var(--color-text); font-size: 13px; text-align: left; }
.profile-button:hover { background: var(--color-background-secondary-ghost-hover); }
.profile-avatar { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--color-text); color: var(--app-color-background-surface); font-size: 12px; font-weight: 500; }
.profile-button kbd { margin-left: auto; color: var(--muted); font: inherit; font-size: 11px; }
.conversation-shell { background: var(--app-color-background-surface); }
.topbar { height: var(--topbar-height); padding: 0 16px; background: var(--app-color-background-surface); border-bottom: 1px solid var(--color-border-subtle); }
.topbar-title { gap: 8px; }
.topbar h1 { font-size: 13px; line-height: 18px; margin: 0; font-weight: 500; }
.connection-indicator { font-size: 12px; color: var(--muted); }
.eyebrow { color: var(--muted); font-size: 10px; letter-spacing: .08em; font-weight: 500; }

/* Workspace pages occupy the main surface, without a third inspector column. */
.workspace-panel { display: flex; min-width: 0; min-height: 0; flex-direction: column; background: var(--app-color-background-surface); }
.inspector-header { min-height: 60px; height: auto; padding: 12px 24px; border-bottom-color: var(--color-border-subtle); }
.inspector-header h2 { font-size: 13px; font-weight: 500; }
.inspector-body { min-height: 0; overflow: auto; padding: 24px; scrollbar-color: var(--color-scrollbar) transparent; }
.workspace-tabs { display: flex; gap: 16px; border-bottom: 1px solid var(--color-border-subtle); margin-bottom: 20px; }
.workspace-tabs > button { border-bottom: 2px solid transparent; border-radius: 0; padding: 8px 0; font-size: 13px; color: var(--muted); }
.workspace-tabs > button.active { color: var(--color-text); border-color: var(--color-text); }
.quest-workspace { display: grid; grid-template-columns: 288px minmax(0, 1fr); gap: 24px; min-width: 0; }
.quest-list { min-width: 0; border-right: 1px solid var(--color-border-subtle); padding-right: 16px; }
.quest-detail { min-width: 0; max-width: var(--settings-content-max); }
.section-heading { font-weight: 500; letter-spacing: .04em; }
.list-row { border-radius: var(--radius-lg); padding: 8px 10px; border-bottom: 0; }
.list-row:hover, .list-row.selected { background: var(--color-background-secondary-ghost-hover); }
.button.primary { background: var(--color-text); border-color: var(--color-text); color: var(--app-color-background-surface); }
.field-label input, .field-label select, .search input, .connect-controls input, .config-form textarea { background: var(--app-color-background-control); color: var(--color-text); }
.error, .send-error { color: var(--color-status-error) !important; }
.warning { color: var(--color-status-warning) !important; }
.restore-warning { border-color: var(--color-border-warning); background: var(--color-background-warning); color: var(--color-status-warning); }

/* Settings have separate navigation and content scroll areas. */
.settings-view { display: grid; grid-template-columns: var(--settings-nav-width) minmax(0, 1fr); min-width: 0; min-height: 0; background: var(--app-color-background-surface); }
.settings-nav { width: var(--settings-nav-width); padding: 4px 8px 8px; display: flex; flex-direction: column; gap: 16px; overflow-y: auto; border-right: 1px solid var(--color-border-subtle); scrollbar-color: var(--color-scrollbar) transparent; }
.settings-search { padding: 12px 8px 0; }
.settings-search input { display: block; width: 100%; min-width: 0; border: 1px solid var(--color-border); border-radius: 8px; padding: 7px 8px; background: var(--color-background-control-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; }
.settings-search input::placeholder { color: var(--muted); }
.settings-nav-group { margin: 0; font-size: 14px; line-height: 21px; font-weight: 500; color: var(--muted); padding: 8px 8px 4px; }
.settings-nav-item { height: var(--settings-item-height); padding: 5px 8px; border: 0; border-radius: var(--settings-item-radius); font-size: 13px; line-height: 18.57px; font-weight: 400; display: flex; align-items: center; gap: 8px; width: 100%; text-align: start; color: var(--color-text); background: none; }
.settings-nav-item:hover { background: var(--color-background-control-subtle); }
.settings-nav-item.active { background: var(--color-background-nav-active); }
.settings-nav-icon { width: 16px; height: 16px; flex: none; }
.settings-content { width: 100%; max-width: var(--settings-content-max); min-width: 0; padding: 24px 32px; overflow-y: auto; scrollbar-color: var(--color-scrollbar) transparent; }
.settings-title { font-size: 28px; line-height: 33.6px; font-weight: 500; margin: 0 0 12px; }
.settings-content .inspector-header { min-height: 36px; height: auto; padding: 0 0 12px; border: 0; }
.settings-content .inspector-header .eyebrow, .settings-content .inspector-header h2 { display: none; }
.settings-content .inspector-header .icon-button { margin-left: auto; }
.settings-content .inspector-body { overflow: visible; padding: 0; }
.settings-row { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: var(--settings-row-padding); border-bottom: 1px solid var(--color-border-subtle); }
.settings-row-text { min-width: 0; }
.settings-row-label { font-size: 13px; line-height: 18px; font-weight: 500; }
.settings-row-desc { font-size: 12px; line-height: 16px; color: var(--muted); margin-top: 4px; }
.settings-row-control { flex: none; max-width: 60%; min-width: 0; font-size: 13px; line-height: 18px; padding: 4px 12px; border-radius: 8px; border: 1px solid var(--color-border); background: var(--color-background-control-subtle); display: inline-flex; align-items: center; gap: 6px; overflow-wrap: anywhere; }
.settings-content .field-label { display: grid; grid-template-columns: minmax(0, 1fr) minmax(160px, 48%); align-items: center; gap: 24px; padding: var(--settings-row-padding); margin: 0; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; font-weight: 500; }
.settings-content .field-label input, .settings-content .field-label select, .settings-content .field-label textarea { padding: 4px 12px; border-radius: 8px; font-size: 13px; line-height: 18px; font-weight: 400; background: var(--color-background-control-subtle); }
.settings-content .check-label { min-height: 42px; margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; }
.settings-content .check-label input { margin-left: auto; order: 1; accent-color: var(--color-accent); }

/* Compact windows retain every navigation destination and profile entry. */
@media (max-width: 760px) {
  .app-shell, .app-shell.inspector-closed { height: 100dvh; min-height: 0; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); overflow: hidden; }
  .rail { width: auto; position: relative; z-index: 3; display: grid; grid-template-columns: minmax(0, 1fr) auto; overflow: visible; border-right: 0; border-bottom: 1px solid var(--line); }
  .brand, .rail-status, .nav-section, .rail-conversations, .conversation-nav, .new-chat { display: none; }
  .rail nav { display: flex; overflow-x: auto; padding: 8px; gap: 4px; }
  .nav-item { flex: 0 0 auto; width: auto; font-size: 13px; }
  .profile-button { margin: 4px 8px 4px 0; padding: 4px; }
  .profile-button > span:not(.profile-avatar), .profile-button kbd { display: none; }
  .conversation-shell { min-height: 0; }
  .topbar { height: var(--topbar-height); padding: 0 16px; }
  .inspector-header { padding: 12px 16px; }
  .inspector-body { padding: 16px; }
  .settings-view { grid-template-columns: 176px minmax(0, 1fr); }
  .settings-nav { width: 176px; }
  .settings-content { padding: 24px 16px; }
  .settings-nav-item { font-size: 12px; }
  .settings-row { align-items: flex-start; flex-direction: column; gap: 8px; padding: 12px 0; }
  .settings-row-control { max-width: 100%; }
  .settings-content .field-label { grid-template-columns: minmax(0, 1fr); gap: 8px; padding: 12px 0; }
  .quest-workspace { grid-template-columns: minmax(0, 1fr); gap: 20px; }
  .quest-list { border-right: 0; border-bottom: 1px solid var(--color-border-subtle); padding: 0 0 16px; }
}
