        {view === "quests" && <div className="quest-workspace"><div className="quest-list"><div className="section-heading"><span>后台任务</span><span>{quests.length}{questsBefore ? "+" : ""}</span></div>{questLoadError && <p className="notice error" role="alert">任务列表加载失败：{questLoadError}</p>}{!quests.length ? <p className="notice">{connection ? "暂无后台任务" : "连接 Core 后显示任务"}</p> : <div className="list">{quests.map((quest) => <button className={selectedId === quest.id ? "list-row selected" : "list-row"} key={quest.id} onClick={() => { setSelectedId(quest.id); setView("quests"); }}><span><strong>{quest.title}</strong><small>{quest.id}</small></span><span className="state-label">{quest.status}</span></button>)}</div>}{questsBefore && <button className="text-button more" onClick={() => void loadMoreQuests()}>加载更多任务</button>}</div><div className="quest-detail">{selected && <><div className="detail"><span className="eyebrow">SELECTED QUEST</span><h3>{selected.title}</h3><p>{selected.goal}</p><dl><dt>状态</dt><dd>{selected.status}</dd><dt>版本</dt><dd>{selected.version}</dd><dt>任务 ID</dt><dd className="mono">{selected.id}</dd></dl></div><div className="section-heading"><span>计划</span></div><StateNotice state={visiblePlan} empty="暂无计划" />{plan && <div className="detail"><dl><dt>状态</dt><dd>{text(plan.status)}</dd><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>摘要</dt><dd className="mono break">{text(plan.digest)}</dd><dt>总 token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{text(plan.max_cost_microunits)}</dd></dl>{rows(plan.nodes).map((node, index) => <div className="plan-node" key={text(node.key, String(index))}><strong>{text(node.objective)}</strong><small>状态：{text(node.status)} · Token 预算：{text(node.budget_tokens)}</small><small>允许工具：{names(node.allowed_tools)}</small><small>成功标准：{names(node.success_criteria)}</small></div>)}<TechnicalDetails value={plan} />{plan.status === "proposed" && typeof plan.digest === "string" && <button className="button primary" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`批准计划？\n任务版本：${selected.version}\n计划版本：${text(plan.plan_revision)}\n摘要：${text(plan.digest)}\n请先检查任务节点、权限和预算。`)) void perform(`/api/quests/${encodeURIComponent(selected.id)}/plan/approve`, { digest: plan.digest, plan_revision: plan.plan_revision, expected_version: selected.version }); }}>批准此计划</button>}</div>}</>}{grantPanel}</div></div>}
        {(view === "teams" || view === "approvals" || view === "activity") && <label className="field-label">任务范围<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)}><option value="">{view === "activity" ? "全部任务" : "选择任务"}</option>{quests.map((quest) => <option key={quest.id} value={quest.id}>{quest.title}</option>)}</select></label>}
