        {view === "approvals" && panelItems.length > 0 && <><div className="list">{panelItems.map((item, index) => <div className="data-row" key={text(item.id, String(index))}><strong>{text(item.action_type)} · {text(item.status)}</strong><dl><dt>风险</dt><dd>{text(item.risk)}</dd><dt>范围</dt><dd className="break">{text(item.resource_scope)}</dd><dt>计划版本</dt><dd>{text(item.plan_revision)}</dd><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl>{item.status === "PENDING" && <div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={actionBusy || writesBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => { if (window.confirm(`${decision === "APPROVED" ? "批准" : "拒绝"}此操作？\n风险：${text(item.risk)}\n范围：${text(item.resource_scope)}\n计划版本：${text(item.plan_revision)}\n参数摘要：${text(item.parameter_digest)}`)) void perform(`/api/approvals/${encodeURIComponent(text(item.id))}/decision`, { decision, expected_digest: item.parameter_digest, expected_plan_revision: item.plan_revision }); }}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div>}</div>)}</div>{approvalCursor && <button className="text-button more" disabled={visiblePanel.loading} onClick={() => void loadPanelPage()}>加载更早的审批</button>}</>}
        {view === "memory" && panelItems.length > 0 && <><div className="list">{(panelItems as MemoryItem[]).map((item) => <div className="data-row" key={item.id}><strong>{item.statement}</strong><small>{text(item.layer)} · {text(item.kind)} · {text(item.status)} · {text(item.freshness, "新鲜度未知")}</small><dl><dt>来源</dt><dd className="break">{item.source_refs?.join(", ") || "未知"}</dd><dt>记录时间</dt><dd>{text(item.created_at)}</dd><dt>有效至</dt><dd>{text(item.valid_until, "未指定")}</dd><dt>可信度</dt><dd>{text(item.confidence, "未知")}</dd><dt>关联任务</dt><dd className="break">{Array.isArray(item.related_quest_ids) ? item.related_quest_ids.join(", ") || "无" : "未知"}</dd></dl>{item.conflicted === true && <p className="warning">存在冲突，请核对来源。</p>}{/^[a-f0-9]{32}$/i.test(item.id) && <button className="button" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`撤销这条记忆？\n${item.statement}`)) void perform(`/api/memory/${encodeURIComponent(item.id)}/revoke`); }}>撤销记忆</button>}</div>)}</div>{memoryCursor && <button className="text-button more" disabled={visiblePanel.loading} onClick={() => void loadPanelPage()}>加载更多记忆</button>}</>}
        {view === "settings" && <>
          <SettingInfo setting={setting} />
          {setting === "general" && <CoreOverview settings={Array.isArray(visiblePanel.value) ? visiblePanel.value[0] as Row : coreInfo} connected={!!connection} />}
          {setting === "environment" && <><div className="section-heading"><span>运行配置与预算</span></div><p className="notice">仅显示 Core 提供的非密钥配置；未知值保持未知。</p>{runtimeStatus && <div className="settings-facts"><SettingsRow label="运行状态"><span>{text(runtimeStatus.state)}</span></SettingsRow><SettingsRow label="进程代次"><span className="break">{text(runtimeStatus.generation)}</span></SettingsRow><SettingsRow label="重启次数"><span>{runtimeStatus.restartCount}</span></SettingsRow><SettingsRow label="最近错误"><span>{text(runtimeStatus.lastErrorCode, "无")}</span></SettingsRow></div>}{Array.isArray(visiblePanel.value) && <OperatorSettings key={text((visiblePanel.value[0] as Row)?.revision, "0")} settings={visiblePanel.value[0] as Row} budget={visiblePanel.value[1] as Row} blocked={writesBlocked || actionBusy} save={(value) => void perform("/api/settings", value)} />}</>}
          {setting === "storage" && <>{Array.isArray(visiblePanel.value) && <><div className="settings-facts"><SettingsRow label="Token 上限"><span>{text((visiblePanel.value[1] as Row)?.token_limit)}</span></SettingsRow><SettingsRow label="保守计入 Token"><span>{text((visiblePanel.value[1] as Row)?.charged_tokens)}</span></SettingsRow><SettingsRow label="已确认用量"><span>{text((visiblePanel.value[1] as Row)?.known_tokens)}</span></SettingsRow><SettingsRow label="未结算预留"><span>{text((visiblePanel.value[1] as Row)?.reserved_tokens)}</span></SettingsRow><SettingsRow label="迁移期上界"><span>{text((visiblePanel.value[1] as Row)?.opening_tokens)}</span></SettingsRow><SettingsRow label="占用并发槽"><span>{text((visiblePanel.value[1] as Row)?.active_reservations)}</span></SettingsRow><SettingsRow label="并发上限"><span>{text((visiblePanel.value[1] as Row)?.concurrency_limit)}</span></SettingsRow><SettingsRow label="费用上限"><span>{text((visiblePanel.value[1] as Row)?.cost_limit_microunits)}</span></SettingsRow><SettingsRow label="货币"><span>{text((visiblePanel.value[1] as Row)?.currency)}</span></SettingsRow></div>{rows((visiblePanel.value[1] as Row)?.recent_unsettled).length > 0 && <><div className="section-heading spaced"><span>未结算请求</span></div>{rows((visiblePanel.value[1] as Row)?.recent_unsettled).map((attempt, index) => <div className="plan-node" key={String(index)}><strong>{text(attempt.code)} · {text(attempt.purpose)}</strong><small>输入预留 {text(attempt.input_reserved)} · 输出预留 {text(attempt.output_reserved)}</small><small>隔离至：{timeText(attempt.recover_after)}</small></div>)}</>}<TechnicalDetails value={visiblePanel.value} /></>}{native && <><div className="section-heading spaced"><span>工作空间维护</span></div><p className="notice">备份和恢复会暂时停止 Core；恢复成功后写操作保持锁定，需人工核对。</p><label className="field-label">备份目录的绝对路径<input value={workspacePath} onChange={(event) => setWorkspacePath(event.target.value)} placeholder="例如 D:/Backup/FORGE" /></label><div className="button-row"><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("backup")}>备份</button><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("restore")}>恢复</button><button className="button" disabled={writesBlocked || actionBusy} onClick={() => void retryRuntime()}>重启 Core</button></div>{workspaceOperation && <p className={workspaceOperation.status === "unknown" || workspaceOperation.result?.ok === false ? "notice error" : "notice"} role="status">{workspaceOperation.status === "running" ? "正在备份或恢复，完成后可退出。" : workspaceOperation.status === "unknown" ? (workspaceOperation.acknowledged ? "未知结果已归档；这不表示操作成功，也不会解除恢复锁定。" : "维护结果未知，请人工核查；不要重复发起。") : workspaceOperation.result?.ok ? (workspaceOperation.operation === "restore" ? "恢复完成；写操作已锁定，请先人工核对。" : "备份完成。") : `维护未完成：${text(workspaceOperation.result?.code)}`}{workspaceOperation.operationId && <> 操作 ID：<code>{workspaceOperation.operationId}</code></>}</p>}{workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged && workspaceOperation.operationId && <><label className="field-label">人工核查说明<input value={reviewReason} onChange={(event) => setReviewReason(event.target.value)} /></label><button className="button" disabled={actionBusy || !reviewReason.trim() || runtimeStatus?.state !== "ready"} onClick={() => void acknowledgeUnknown()}>归档未知结果</button><p className="notice">仅归档，不表示成功，不解除恢复锁或预算限制。</p></>}</>}</>}
          {setting === "connections" && <><SettingsRow label="供应商" description="当前 Core 的模型连接。">{text(coreInfo.provider_id)}</SettingsRow><SettingsRow label="Router 模型" description="运行配置中的默认模型。">{text(coreInfo.router_model_id)}</SettingsRow>{<><div className="section-heading spaced"><span>供应商凭据</span></div>{native ? <div className="credential-form"><label className="field-label">供应商 ID<input value={providerId} onChange={(event) => setProviderId(event.target.value)} autoComplete="off" /></label><label className="field-label">凭据引用<input value={credentialRef} onChange={(event) => setCredentialRef(event.target.value)} autoComplete="off" /></label><label className="field-label">新凭据<input ref={credentialInput} type="password" autoComplete="new-password" /></label><div className="button-row"><button className="button primary" disabled={writesBlocked} onClick={() => void credential("set")}>保存</button><button className="button" onClick={() => void credential("exists")}>检查是否存在</button><button className="button" disabled={writesBlocked} onClick={() => void credential("delete")}>删除</button></div>{credentialStatus && <p className="notice" role="status">{credentialStatus}</p>}</div> : <p className="notice">浏览器开发模式不提供系统凭据库。请在桌面应用中管理凭据。</p>}</>}</>}
          {restoreFenced === true && <div className="restore-warning"><strong>恢复待复核，后台与写入已暂停</strong><p>{restoreStatus?.review_available === true ? "请先核对当前工作区与回滚目录，退出应用后按 README 的离线维护步骤提交复核；此界面不会自动解除锁定。" : "复核记录不可用或损坏，请人工检查；不要尝试自动解锁。"}</p><div className="settings-facts"><SettingsRow label="清单摘要"><span className="break">{text(restoreStatus?.manifest_sha256)}</span></SettingsRow><SettingsRow label="回滚目录"><span className="break">{text(restoreStatus?.rollback_directory)}</span></SettingsRow></div></div>}
        </>}
        {view === "approvals" && grantPanel}
        {actionError && <p className="notice error" role="alert">{actionError}</p>}
      </div>
    </WorkspaceFrame>}
  </div>;
}

import { useState, type ReactNode } from "react";

export type SettingId = "general" | "appearance" | "shortcuts" | "archived" |
  "quests" | "teams" | "memory" | "approvals" | "models" | "activity" |
  "connections" | "git" | "environment" | "plugins" | "computer" | "storage" | "import";

interface SettingItem { id: SettingId; label: string; accessibleLabel?: string }
interface SettingGroup { label: string; items: SettingItem[] }

export const settingGroups: SettingGroup[] = [
  { label: "个人", items: [
    { id: "general", label: "常规" },
    { id: "appearance", label: "外观" },
    { id: "shortcuts", label: "键盘快捷键" },
    { id: "archived", label: "已归档的聊天" },
  ] },
  { label: "工作区", items: [
    { id: "quests", label: "任务", accessibleLabel: "后台任务" },
    { id: "teams", label: "任务团队" },
    { id: "memory", label: "记忆中心" },
    { id: "approvals", label: "审批中心" },
    { id: "models", label: "模型库" },
    { id: "activity", label: "运行活动" },
  ] },
  { label: "集成", items: [
    { id: "connections", label: "连接" },
    { id: "git", label: "Git" },
    { id: "environment", label: "环境" },
    { id: "plugins", label: "插件" },
    { id: "computer", label: "电脑操控" },
  ] },
  { label: "数据", items: [
    { id: "storage", label: "存储" },
    { id: "import", label: "导入" },
  ] },
];

function SettingIcon({ id }: { id: SettingId }) {
  const paths: Record<SettingId, ReactNode> = {
    general: <><circle cx="12" cy="12" r="3" /><path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4m0-12.8L17 7M7 17l-1.4 1.4" /></>,
    appearance: <><circle cx="12" cy="12" r="8" /><path d="M12 4v16M12 4a8 8 0 0 1 0 16Z" /></>,
    shortcuts: <><rect x="3" y="6" width="18" height="12" rx="2" /><path d="M6 10h1m4 0h1m4 0h1M6 14h1m3 0h7" /></>,
    archived: <><path d="M4 8h16v12H4zM3 4h18v4H3zM9 12h6" /></>,
    quests: <><path d="M4 7h6l2 2h8v11H4zM4 7V4h6l2 3" /></>,
    teams: <><circle cx="9" cy="8" r="3" /><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2" /></>,
    memory: <><path d="m12 3 9 9-9 9-9-9z" /><circle cx="12" cy="12" r="2" /></>,
    approvals: <><path d="m12 3 8 3v6c0 4-3 7-8 9-5-2-8-5-8-9V6zM8 12l3 3 5-6" /></>,
    models: <><rect x="4" y="4" width="6" height="6" rx="1" /><rect x="14" y="4" width="6" height="6" rx="1" /><rect x="4" y="14" width="6" height="6" rx="1" /><rect x="14" y="14" width="6" height="6" rx="1" /></>,
    activity: <><circle cx="12" cy="12" r="9" /><path d="M12 7v5l4 2" /></>,
    connections: <><path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(1 0) scale(.92)" /></>,
    git: <><circle cx="7" cy="5" r="2" /><circle cx="7" cy="19" r="2" /><circle cx="18" cy="6" r="2" /><path d="M7 7v10m11-9c0 6-11 3-11 8" /></>,
    environment: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4M7 8l3 3-3 3m6 0h4" /></>,
    plugins: <><path d="M9 3v4H5v5h4v4h5v5h5v-5h2v-5h-7V7H9V3Z" /></>,
    computer: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4m2-12 2 6 1-3 3-1z" /></>,
    storage: <><ellipse cx="12" cy="5" rx="8" ry="3" /><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0" /></>,
    import: <><path d="M12 3v12m-4-4 4 4 4-4M4 14v6h16v-6" /></>,
  };
  return <svg className="settings-nav-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[id]}</svg>;
}

export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control">{children}</div>
  </div>;
}

export default function SettingsView({ selected, onSelect, children }: { selected: SettingId; onSelect: (id: SettingId) => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.accessibleLabel || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const current = settingGroups.flatMap((group) => group.items).find((item) => item.id === selected)!;
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-search"><input type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} /></div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onClick={() => onSelect(item.id)}><SettingIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <p className="notice">未找到匹配的设置</p>}
    </nav>
    <div className="settings-content"><h1 className="settings-title">{current.label}</h1>{children}</div>
  </section>;
}

