.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.app-shell { display: grid; grid-template-columns: var(--sidebar-width) minmax(0,1fr); grid-template-rows: 36px minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--app-color-background-surface); }

/* Full window application chrome, matching the supplied desktop reference. */
.desktop-chrome { grid-column: 1 / -1; height: 36px; display: flex; align-items: center; justify-content: space-between; padding: 0 12px 0 0; }
.desktop-chrome-leading { display: flex; align-items: center; gap: 6px; color: var(--muted); }
