import { invoke } from "@tauri-apps/api/core";
import { Children, isValidElement, useState, type ReactNode, type RefObject } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import AnimatedDetails from "./AnimatedDetails";
import { safeExternalUrl } from "./logic";
import { mergeTimeline, messageMetadata, type ChatMessage, type Outgoing, type TimelineEvent, type TimelineItem } from "./timeline";

type Row = Record<string, unknown>;
type Quest = { id: string; title: string; status: string; version: number };
const text = (value: unknown, fallback = "未知") => value == null || value === "" ? fallback : String(value);

function contentText(node: ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (isValidElement<{ children?: ReactNode }>(node)) return contentText(node.props.children);
  return Children.toArray(node).map(contentText).join("");
}

function MarkdownMessage({ content, native, onInspect }: { content: string; native: boolean; onInspect: () => void }) {
  const [status, setStatus] = useState("");
  const copy = async (value: string) => {
    onInspect();
    try { await navigator.clipboard.writeText(value); setStatus("已复制"); }
    catch { setStatus("无法复制，请手动选择代码。"); }
  };
  const link = (href: string | undefined, children: ReactNode) => {
    const safe = safeExternalUrl(href);
    if (!safe) return <span>{children}</span>;
    if (native) return <button type="button" className="markdown-link" onClick={() => { void invoke("open_external", { url: safe }).catch(() => setStatus("无法在系统浏览器中打开链接。")); }}>{children}</button>;
    return <a href={safe} target="_blank" rel="noopener noreferrer">{children}</a>;
  };
  return <div className="markdown"><ReactMarkdown skipHtml remarkPlugins={[remarkGfm]} components={{
    a({ href, children }) {
      return link(href, children);
    },
    img({ src, alt }) { return <span className="image-placeholder">图片未自动加载{alt ? `：${alt}` : ""}{safeExternalUrl(src) && <> · {link(src, "打开图片链接")}</>}</span>; },
    pre({ children }) { const code = contentText(children); return <div className="code-block"><div className="code-toolbar"><span>代码</span><button type="button" onClick={() => void copy(code)}>复制</button></div><pre>{children}</pre></div>; },
  }}>{content}</ReactMarkdown>{status && <span className="copy-status" role="status">{status}</span>}</div>;
}

type DisplayItem = Exclude<TimelineItem, { type: "event" }> | { type: "group"; questId: string | null; events: TimelineEvent[] };
function eventTitle(event: TimelineEvent): string {
  const labels: Record<string, string> = { "quest.proposed": "创建了任务", "quest.status_changed": "任务状态已更新", "quest.plan_proposed": "提出了计划", "quest.plan_approved": "计划已批准", "team.proposed": "提出了团队", "team.approved": "团队已批准", "team.reassigned": "团队已调整", "team.revoked": "团队批准已撤销", "worker.proposed": "提出了 Worker", "worker.started": "Worker 已启动", "worker.blocked": "Worker 已阻塞", "worker.failed": "Worker 执行失败", "worker.result": "已记录 Worker 结果", "worker.retry": "Worker 正在重试", "worker.help_requested": "Worker 请求协助", "tool.intent_prepared": "已准备工具操作", "tool.receipt_recorded": "已记录工具回执", "tool.execution_uncertain": "工具结果未知", "approval.requested": "需要审批", "approval.decided": "审批已处理", "approval.revoked": "审批已撤销", "evidence.json_checked": "已检查 JSON 语法", "task.verified": "任务已验证" };
  if (event.kind === "context_archive") return "上下文已自动压缩";
  if (event.kind === "semantic_test") return event.status === "passed" ? "独立语义验证通过" : "独立语义验证";
  if (event.kind === "tool_receipt") {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
    const tools: Record<string, string> = { file_read: "已读取文件", file_write: "编辑了文件", file_revise: "编辑了文件", shell_inspect: "运行了命令", python_compile: "运行了命令", git_status: "运行了命令", numeric_ast: "运行了命令", browser_get: "已搜索网页" };
    return tools[text(detail.tool, "")] || "调用了一个工具";
  }
  if (event.status === "worker.proposed" || event.status === "worker.started") return "已创建聊天";
  return labels[text(event.status, "")] || event.title;
}

function ActivityIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="2" /><path d="m8 10 2 2-2 2m4 0h4" /></svg>;
}

function Chevron() {
  return <svg data-chevron viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg>;
}

function CommandCard({ detail, onInspect }: { detail: Row; onInspect: () => void }) {
  const [copyStatus, setCopyStatus] = useState("");
  const command = text(detail.command, "");
  // The current Core normally returns a receipt digest, not stdout. Never infer output from it.
  const output = [detail.stdout, detail.output, detail.stderr].filter((value): value is string => typeof value === "string").join("\n");
  const copy = async () => {
    onInspect();
    try { await navigator.clipboard.writeText(command); setCopyStatus("已复制"); }
    catch { setCopyStatus("无法复制，请手动选择代码。"); }
  };
  return <div className="command-card"><header>{detail.tool === "shell_inspect" ? "Shell" : text(detail.tool, "Shell")}</header>
    <div className="command-line"><div className="cmd">{command}</div><button type="button" className="copy-btn" aria-label="复制" onClick={() => void copy()}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.5" /><path d="M10.5 5.5v-2a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2" /></svg></button></div>
    {output ? <div className="out vertical-scroll-fade-mask"><code>{output}</code></div> : <p className="command-no-output">暂无输出</p>}
    {copyStatus && <span className="copy-status" role="status">{copyStatus}</span>}
  </div>;
}

function EventLine({ event, onQuest, onInspect }: { event: TimelineEvent; onQuest: (id: string) => void; onInspect: () => void }) {
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  return <AnimatedDetails onInspect={onInspect} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`} summary={<><ActivityIcon /><span className="event-label">{target || eventTitle(event)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></>}>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} onInspect={onInspect} />}
      {["file_write", "file_revise"].includes(text(detail.tool, "")) && typeof detail.path === "string" && <div className="resource-card"><span className="resource-icon" aria-hidden="true"><ActivityIcon /></span><span><strong>{detail.path}</strong><small>{eventTitle(event)}</small></span></div>}
      <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>{event.quest_id && <button className="text-button" onClick={() => onQuest(event.quest_id!)}>查看关联任务</button>}<dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数" } as Record<string, string>)[key] || key}</dt><dd>{text(value)}</dd></div>)}</dl><small>记录 ID：{event.event_id}</small>
    </div></AnimatedDetails>;
}

function EventGroup({ item, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; onQuest: (id: string) => void; onInspect: () => void }) {
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  return <AnimatedDetails className="event-group" onInspect={onInspect} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon /><span className="event-label">{summary}</span><Chevron /></>}>
    <div className="event-detail">{item.events.map((event) => <EventLine key={`${event.kind}:${event.event_id}`} event={event} onQuest={onQuest} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
    if (last?.type === "group" && last.questId === questId) last.events.push(item.value);
    else grouped.push({ type: "group", questId, events: [item.value] });
  }
  return grouped;
}

export default function ChatTimeline({ messages, events, outgoing, quests, approvals, native,
  connected, historyMore, historyBusy, timelineError, conversationError, approvalError,
  canRetry, scrollRef, onScroll, onInspect, onLoadOlder, onRetry, onQuest, onApproval, approvalsBlocked, onApprovalDecision }: {
