    settings: <><circle cx="12" cy="12" r="3.2" /><path d="m9.8 3-1.2 2.2H6l-1.5 2.6 1.3 2.3v3.8l-1.3 2.3L6 18.8h2.6l1.2 2.2h4.4l1.2-2.2H18l1.5-2.6-1.3-2.3v-3.8l1.3-2.3L18 5.2h-2.6L14.2 3z" /></>,
  };
  return <svg className="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.55" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

function ShellGlyph({ name }: { name: "back" | "forward" | "panel" | "search" | "bell" | "compose" | "folder" | "local" | "plus" | "chevron" }) {
  const paths: Record<typeof name, React.ReactNode> = {
    back: <path d="M19 12H5m6-6-6 6 6 6" />,
    forward: <path d="M5 12h14m-6-6 6 6-6 6" />,
    panel: <><rect x="3" y="4" width="18" height="16" rx="3" /><path d="M9 4v16" /></>,
    search: <><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></>,
    bell: <><path d="M6 10a6 6 0 0 1 12 0c0 5 2 5 2 7H4c0-2 2-2 2-7m4 10h4" /></>,
    compose: <><path d="M13 5H6a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2v-7M10 14l1-4 8-8 3 3-8 8z" /></>,
    folder: <><path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3M3 12h18" /></>,
    local: <><rect x="4" y="4" width="16" height="13" rx="2" /><path d="M2 20h20l-2-3H4z" /></>,
    plus: <path d="M12 5v14M5 12h14" />,
    chevron: <path d="m8 10 4 4 4-4" />,
  };
  return <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

function StateNotice({ state, empty = "暂无数据" }: { state: DataState; empty?: string }) {
  if (state.loading && state.value == null) return <p className="notice" role="status">正在加载…</p>;
  if (state.error) return <p className="notice error" role="alert">{state.error}</p>;
  if (state.value == null || (Array.isArray(state.value) && !state.value.length) ||
      (typeof state.value === "object" && state.value !== null && "items" in state.value && Array.isArray((state.value as Row).items) && !(state.value as {items: unknown[]}).items.length)) return <p className="notice">{empty}</p>;
  return null;
}

function TechnicalDetails({ value }: { value: unknown }) {
  return <details><summary>技术详情</summary><pre>{display(value)}</pre></details>;
}

function WorkspaceFrame({ settingsOpen, setting, onSetting, title, children }: {
  settingsOpen: boolean; setting: SettingId; onSetting: (id: SettingId) => void; title: string; children: React.ReactNode;
}) {
  return settingsOpen ? <SettingsView selected={setting} onSelect={onSetting}><aside className="settings-page" aria-label={title}>{children}</aside></SettingsView>
    : <aside className="workspace-panel" aria-label={title}>{children}</aside>;
}

function SettingInfo({ setting }: { setting: SettingId }) {
  const information: Partial<Record<SettingId, [string, string][]>> = {
    appearance: [["主题", "跟随当前应用外观"], ["文字", "使用系统 UI 字体"]],
    shortcuts: [["打开设置", "Ctrl + ,"], ["发送消息", "Enter"], ["换行", "Shift + Enter"]],
    archived: [["已归档的聊天", "当前工作空间使用一个长期对话，没有独立的聊天归档列表。"]],
    git: [["Git", "任务的 Git 活动可在运行活动中查看；当前 Core 未提供独立的 Git 配置。"]],
    plugins: [["插件", "当前 Core 未提供插件管理。"]],
    computer: [["电脑操控", "当前 Core 未提供电脑操控配置。"]],
    import: [["导入", "当前 Core 未提供导入接口。工作空间备份与恢复位于存储。"]],
  };
  return <>{information[setting]?.map(([label, value]) => <SettingsRow key={label} label={label}><span>{value}</span></SettingsRow>)}</>;
}

function CoreOverview({ settings, connected }: { settings: Row; connected: boolean }) {
  return <>
    <SettingsRow label="工作空间" description="当前长期对话与任务所在的工作空间。">{text(settings.workspace_root ?? settings.workspace_id)}</SettingsRow>
    <SettingsRow label="供应商" description="Core 当前使用的模型供应商。">{text(settings.provider_id)}</SettingsRow>
    <SettingsRow label="Router 模型" description="长期对话与任务协调使用的模型。">{text(settings.router_model_id)}</SettingsRow>
    <SettingsRow label="上下文上限" description="当前 Router 的上下文预算。">{text(settings.context_limit)}</SettingsRow>
    <SettingsRow label="运行状态" description="本地 Core 的连接状态。">{connected ? "Core 已连接" : "Core 未连接"}</SettingsRow>
  </>;
}

function ModelMeasurements({ value }: { value: unknown }) {
  if (!value || typeof value !== "object" || Array.isArray(value) || !Object.keys(value).length) return <p className="notice">能力评分：未知</p>;
  return <div className="measurement-list">{Object.entries(value as Row).map(([name, measurement]) => {
    const entry = measurement && typeof measurement === "object" ? measurement as Row : {};
    return <div key={name}><span>{MODEL_CAPABILITIES.find(([key]) => key === name)?.[1] || name}</span><span>{text(entry.value)} · {text(entry.source)} · {entry.n_samples == null ? (entry.source === "user_override" ? "未采样（0）" : "样本未知") : `样本 ${text(entry.n_samples)}`}{entry.confidence == null ? " · 置信度未知" : ` · 置信度 ${text(entry.confidence)}`}</span></div>;
  })}</div>;
}

function names(value: unknown): string {
  if (Array.isArray(value)) return value.length ? value.map((item) => text(item)).join("、") : "无";
  return text(value);
}

function OperatorSettings({ settings, budget, blocked, save }: { settings: Row; budget: Row; blocked: boolean; save: (value: unknown) => void }) {
  const saved = settings.config && typeof settings.config === "object" ? settings.config as Row : {};
  const provider = saved.provider && typeof saved.provider === "object" ? saved.provider as Row : {};
  const [form, setForm] = useState<OperatorForm>({
    providerEnabled: !!saved.provider, providerId: text(provider.id, ""), kind: text(provider.kind, "openai_compatible"),
    baseUrl: text(provider.base_url, ""), credentialRef: text(provider.credential_ref, ""),
    allowInsecureLoopback: provider.allow_insecure_loopback === true,
    supportsTools: provider.supports_tools === true, supportsJsonSchema: provider.supports_json_schema === true,
    routerModel: text(saved.router_model_id, ""), contextLimit: text(saved.router_context_limit ?? settings.context_limit, ""),
    tokenLimit: text(saved.model_token_limit ?? budget.token_limit, ""), concurrencyLimit: text(saved.model_concurrency_limit ?? budget.concurrency_limit, ""),
    hosts: Array.isArray(saved.network_hosts) ? saved.network_hosts.join("\n") : "",
  });
  const [error, setError] = useState("");
  const change = <K extends keyof OperatorForm>(key: K, value: OperatorForm[K]) => setForm((old) => ({ ...old, [key]: value }));
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    try {
      const config = operatorConfig(form);
      if (!Number.isInteger(settings.revision)) throw new Error("配置版本未知，请先刷新。");
      if (!window.confirm(`保存配置版本 ${settings.revision} 的修改？\n重启 Core 后生效；已有预算账本不会重置。\n请核对供应商、模型、预算和网络范围。`)) return;
      setError(""); save({ expected_revision: settings.revision, config });
    } catch (problem) { setError(errorMessage(problem)); }
  };
  return <form className="config-form" onSubmit={submit}>
    <p className="notice">配置版本 {text(settings.revision)} · {settings.restart_required === true ? "修改待重启生效" : "当前配置已生效或未设置"}</p>
    {Array.isArray(settings.environment_overrides) && settings.environment_overrides.length > 0 && <p className="warning">进程环境优先覆盖：{settings.environment_overrides.join("、")}</p>}
    <label className="check-label"><input type="checkbox" checked={form.providerEnabled} onChange={(event) => change("providerEnabled", event.target.checked)} />配置供应商</label>
    {form.providerEnabled && <><label className="field-label">供应商 ID<input value={form.providerId} onChange={(event) => change("providerId", event.target.value)} /></label><label className="field-label">协议<select value={form.kind} onChange={(event) => change("kind", event.target.value)}><option value="openai_compatible">OpenAI compatible</option><option value="deepseek">DeepSeek</option><option value="anthropic">Anthropic</option></select></label><label className="field-label">服务地址<input type="url" value={form.baseUrl} onChange={(event) => change("baseUrl", event.target.value)} placeholder="https://example.invalid/v1" /></label><label className="check-label"><input type="checkbox" checked={form.allowInsecureLoopback} onChange={(event) => change("allowInsecureLoopback", event.target.checked)} />允许本机 HTTP（仅 127.0.0.1 / ::1）</label><label className="field-label">凭据引用<input value={form.credentialRef} onChange={(event) => change("credentialRef", event.target.value)} placeholder="FORGE_PROVIDER_KEY_EXAMPLE" /></label><label className="check-label"><input type="checkbox" checked={form.supportsTools} onChange={(event) => change("supportsTools", event.target.checked)} />供应商支持工具调用</label><label className="check-label"><input type="checkbox" checked={form.supportsJsonSchema} onChange={(event) => change("supportsJsonSchema", event.target.checked)} />供应商支持结构化输出</label></>}
    <label className="field-label">Router 模型 ID<input value={form.routerModel} onChange={(event) => change("routerModel", event.target.value)} /></label>
    <label className="field-label">上下文上限<input type="number" min="2049" value={form.contextLimit} onChange={(event) => change("contextLimit", event.target.value)} /></label>
    <label className="field-label">模型 Token 上限<input type="number" min="0" value={form.tokenLimit} onChange={(event) => change("tokenLimit", event.target.value)} /></label>
    <label className="field-label">并发上限<input type="number" min="1" max="64" value={form.concurrencyLimit} onChange={(event) => change("concurrencyLimit", event.target.value)} /></label>
    <label className="field-label">允许的网络主机，每行一个<textarea value={form.hosts} onChange={(event) => change("hosts", event.target.value)} rows={3} placeholder="example.invalid" /></label>
    <p className="notice">网络范围不替代操作审批。此表单不接收凭据明文，费用历史与账本不会被重置。</p>
    {error && <p className="notice error" role="alert">{error}</p>}
    <button className="button primary" type="submit" disabled={blocked}>保存配置</button>
  </form>;
}

function GrantPanel({ quest, state, workspace, scope, setScope, blocked, submit }: {
  quest: Quest; state: DataState; workspace: string; scope: string; setScope: (value: string) => void;
  blocked: boolean; submit: (path: string, body: unknown) => void;
}) {
    finally { setActionBusy(false); }
  };

  const plan = visiblePlan.value as Row | null;
  const panelItems = (view === "memory" || view === "approvals") && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items) :
    view === "activity" && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items ?? (visiblePanel.value as Row).events) : rows(visiblePanel.value);
  const title = VIEW_NAMES[view];
  const selectSetting = (id: SettingId) => { setSetting(id); setView(SETTING_VIEWS[id] || "settings"); setActionError(""); };
  const decideApproval = (item: Row, decision: "APPROVED" | "REJECTED") => {
    if (window.confirm(`${decision === "APPROVED" ? "批准" : "拒绝"}此操作？\n风险：${text(item.risk)}\n范围：${text(item.resource_scope)}\n计划版本：${text(item.plan_revision)}\n参数摘要：${text(item.parameter_digest)}`)) void perform(`/api/approvals/${encodeURIComponent(text(item.id))}/decision`, { decision, expected_digest: item.parameter_digest, expected_plan_revision: item.plan_revision });
  };
  const grantPanel = (view === "quests" || view === "approvals") && selected && <GrantPanel quest={selected} state={visibleGrants} workspace={grantContext === `${questContextKey}|${view}` ? workspaceRoot : ""} scope={grantScope} setScope={setGrantScope} blocked={actionBusy || writesBlocked} submit={(path, body) => void perform(path, body)} />;

  return <div className={`app-shell${settingsOpen ? " settings-open" : ""}`}>
    <header className="desktop-chrome">
      <div className="desktop-chrome-leading" aria-hidden="true"><span><ShellGlyph name="back" /></span><span><ShellGlyph name="forward" /></span><span><ShellGlyph name="panel" /></span><div className="desktop-menu"><span>文件</span><span>编辑</span><span>视图</span><span>帮助</span></div></div>
      <div className="connection-indicator"><span className={connection ? "status-dot on" : "status-dot"} />{connection ? "Core 已连接" : "Core 未连接"}</div>
    </header>
    <aside className="rail" aria-label="主导航">
      <div className="primary-rail"><nav className="primary-nav">{NAV.map((item) => <button key={item.id} title={item.name} aria-label={item.name} className={!settingsOpen && (view === item.id || (item.id === "quests" && view === "activity")) ? "nav-item active" : "nav-item"} aria-current={!settingsOpen && (view === item.id || (item.id === "quests" && view === "activity")) ? "page" : undefined} onClick={() => { setSettingsOpen(false); setView(item.id); setActionError(""); }}><Icon name={item.id} /><span className="sr-only">{item.label}</span></button>)}</nav>
        <button className="profile-button" aria-label="设置" title="设置 (Ctrl+,)" onClick={openSettings}><Icon name="settings" /></button>
      </div>
      <div className="sidebar-panel">
        <div className="sidebar-heading"><strong>FORGE</strong><ShellGlyph name="chevron" /><span className="sidebar-heading-tools" aria-hidden="true"><ShellGlyph name="bell" /><ShellGlyph name="search" /></span></div>
        <button className="sidebar-new-chat" onClick={() => { setSettingsOpen(false); setView("chat"); requestAnimationFrame(() => document.querySelector<HTMLTextAreaElement>('textarea[aria-label="消息内容"]')?.focus()); }}><ShellGlyph name="compose" /><span>新聊天</span></button>
        <div className="sidebar-scroll"><div className="sidebar-section-title"><span>最近会话</span><ShellGlyph name="search" /></div><button className={view === "chat" && !settingsOpen ? "thread-row active" : "thread-row"} onClick={() => { setSettingsOpen(false); setView("chat"); }}>长期对话</button><div className="sidebar-section-title workspace-section">工作空间</div><div className="sidebar-workspace"><ShellGlyph name="folder" /><span>{connection?.workspace_id || "FORGE"}</span></div></div>
        <div className="sidebar-connection">{!connection && <div className="connect-banner" role="status"><div><strong>{native ? "正在连接本地 Core" : "连接开发 Core"}</strong><p>{native ? "等待桌面运行时提供安全会话。" : "输入本次 Core 启动密钥。密钥不会保存在浏览器中。"}</p>{connectionError && <p className="error">{connectionError}</p>}</div>{!native && <div className="connect-controls"><input ref={secretInput} type="password" autoComplete="off" aria-label="Core 启动密钥" placeholder="本次启动密钥" /><button className="button primary" onClick={() => void connectBrowser()}>连接</button></div>}</div>}</div>
      </div>
    </aside>
    <main className={`conversation-shell${messages.length || timelineEvents.length || outgoing.length ? "" : " home-state"}`} hidden={view !== "chat"}>
      <header className="topbar"><div className="topbar-title"><h1>长期对话</h1><small>{connection?.workspace_id || "工作空间"} · {messages.length} 条消息 · {timelineEvents.length} 条记录</small></div></header>
      {writesBlocked && <div className="maintenance-banner" role="status">{restoreFenced === true ? "恢复后写操作已锁定，请先人工核对。" : workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged ? "维护结果未知，请人工核查；写操作已暂停。" : runtimeStatus?.state === "maintenance" || workspaceOperation?.status === "running" ? "正在备份或恢复，完成后可退出；写操作已暂停。" : "正在核对工作空间恢复状态；写操作暂不可用。"}</div>}
      <ChatTimeline messages={messages} events={timelineEvents} outgoing={outgoing} quests={quests}
        approvals={pendingApprovals} native={native} connected={!!connection} historyMore={hasMore || timelineHasMore}
        historyBusy={historyBusy} timelineError={timelineError} conversationError={conversationError}
        approvalError={approvalLoadError} canRetry={!!connection && !sending && !writesBlocked} scrollRef={scrollRef}
        onScroll={() => { const element = scrollRef.current; if (!element || manualPause.current) return; followBottom.current = isNearBottom(element.scrollTop, element.clientHeight, element.scrollHeight); if (followBottom.current) setHasNew(false); }}
        onInspect={() => { manualPause.current = true; followBottom.current = false; setReadingPaused(true); }}
        onLoadOlder={() => void loadOlder()} onRetry={(item) => void sendPending(item, false)}
        onQuest={(id) => { setSelectedId(id); setView("quests"); }}
        onApproval={(id) => { setSelectedId(id); setSetting("approvals"); setSettingsOpen(true); setView("approvals"); }}
        approvalsBlocked={actionBusy || writesBlocked} onApprovalDecision={decideApproval} />
      {actionError && <p className="notice error action-error" role="alert">{actionError}</p>}
      {(hasNew || readingPaused) && <button className="new-messages" onClick={() => { manualPause.current = false; followBottom.current = true; setReadingPaused(false); setHasNew(false); if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }}>{hasNew ? "有新消息 · 回到最新 ↓" : "回到最新 ↓"}</button>}
      <footer className="composer-wrap"><div className="composer-context"><span><ShellGlyph name="folder" />{connection?.workspace_id || "工作空间"}</span><span><ShellGlyph name="local" />本地</span><span className="composer-context-model">{text(coreInfo.provider_id, "")}</span></div><div className="composer"><textarea value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => { if (shouldSubmitOnEnter({ key: event.key, shiftKey: event.shiftKey, isComposing: event.nativeEvent.isComposing, keyCode: event.nativeEvent.keyCode })) { event.preventDefault(); void send(); } }} placeholder="输入消息，或接着之前的任务…" aria-label="消息内容" /><div className="composer-bottom"><span className="composer-add" aria-hidden="true"><ShellGlyph name="plus" /></span><span>{connection ? "Core 已连接" : "等待 Core 连接"}</span><span className="composer-model" title="Enter 发送 · Shift + Enter 换行">{text(coreInfo.router_model_id, "FORGE")}<ShellGlyph name="chevron" /></span><button className="send-button" aria-label="发送消息" disabled={!connection || sending || writesBlocked || !draft.trim()} onClick={() => void send()}>↑</button></div></div>{sendError && <p className="send-error" role="alert">{sendError} 草稿已保留。请求 ID：<code>{pending?.requestId}</code></p>}</footer>
    </main>
    {view !== "chat" && <WorkspaceFrame settingsOpen={settingsOpen} setting={setting} onSetting={selectSetting} title={title}>
      <header className="inspector-header"><div><span className="eyebrow">WORKSPACE</span><h2>{title}</h2></div><button className="icon-button" aria-label="刷新当前视图" onClick={() => { void refreshConversation(); void refreshPanel(); }}>↻</button></header>
      <div className="inspector-body">
        {!settingsOpen && (view === "quests" || view === "activity") && <div className="workspace-tabs"><button className={view === "quests" ? "text-button active" : "text-button"} onClick={() => setView("quests")}>后台任务</button><button className={view === "activity" ? "text-button active" : "text-button"} onClick={() => setView("activity")}>运行活动</button></div>}
        {view === "quests" && <div className="quest-workspace"><div className="quest-list"><div className="section-heading"><span>后台任务</span><span>{quests.length}{questsBefore ? "+" : ""}</span></div>{questLoadError && <p className="notice error" role="alert">任务列表加载失败：{questLoadError}</p>}{!quests.length ? <p className="notice">{connection ? "暂无后台任务" : "连接 Core 后显示任务"}</p> : <div className="list">{quests.map((quest) => <button className={selectedId === quest.id ? "list-row selected" : "list-row"} key={quest.id} onClick={() => { setSelectedId(quest.id); setView("quests"); }}><span><strong>{quest.title}</strong><small>{quest.id}</small></span><span className="state-label">{quest.status}</span></button>)}</div>}{questsBefore && <button className="text-button more" onClick={() => void loadMoreQuests()}>加载更多任务</button>}</div><div className="quest-detail">{selected && <><div className="detail"><span className="eyebrow">SELECTED QUEST</span><h3>{selected.title}</h3><p>{selected.goal}</p><dl><dt>状态</dt><dd>{selected.status}</dd><dt>版本</dt><dd>{selected.version}</dd><dt>任务 ID</dt><dd className="mono">{selected.id}</dd></dl></div><div className="section-heading"><span>计划</span></div><StateNotice state={visiblePlan} empty="暂无计划" />{plan && <div className="detail"><dl><dt>状态</dt><dd>{text(plan.status)}</dd><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>摘要</dt><dd className="mono break">{text(plan.digest)}</dd><dt>总 token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{text(plan.max_cost_microunits)}</dd></dl>{rows(plan.nodes).map((node, index) => <div className="plan-node" key={text(node.key, String(index))}><strong>{text(node.objective)}</strong><small>状态：{text(node.status)} · Token 预算：{text(node.budget_tokens)}</small><small>允许工具：{names(node.allowed_tools)}</small><small>成功标准：{names(node.success_criteria)}</small></div>)}<TechnicalDetails value={plan} />{plan.status === "proposed" && typeof plan.digest === "string" && <button className="button primary" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`批准计划？\n任务版本：${selected.version}\n计划版本：${text(plan.plan_revision)}\n摘要：${text(plan.digest)}\n请先检查任务节点、权限和预算。`)) void perform(`/api/quests/${encodeURIComponent(selected.id)}/plan/approve`, { digest: plan.digest, plan_revision: plan.plan_revision, expected_version: selected.version }); }}>批准此计划</button>}</div>}</>}{grantPanel}</div></div>}
        {(view === "teams" || view === "approvals" || view === "activity") && <label className="field-label">任务范围<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)}><option value="">{view === "activity" ? "全部任务" : "选择任务"}</option>{quests.map((quest) => <option key={quest.id} value={quest.id}>{quest.title}</option>)}</select></label>}
        {settingsOpen && view === "memory" && <SettingsRow label="记忆策略" description="检索结果保留来源、有效期与冲突状态。">当前 Core 未提供可编辑策略</SettingsRow>}
import json
from datetime import UTC, datetime
from enum import Enum
from typing import Annotated
from urllib.parse import urlsplit
from uuid import uuid4

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


def now_iso() -> str:
    return datetime.now(UTC).isoformat()


def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid4().hex[:12]}"


class IntentType(str, Enum):
    CHAT = "chat"
    CREATE_QUEST = "create_quest"
    CONTINUE_QUEST = "continue_quest"
    UPDATE_QUEST = "update_quest"
    STATUS_QUERY = "status_query"
    APPROVAL_RESPONSE = "approval_response"
    AMBIGUOUS = "ambiguous"


class QuestStatus(str, Enum):
    PROPOSED = "proposed"
    AWAITING_APPROVAL = "awaiting_approval"
    APPROVED = "approved"
    QUEUED = "queued"
    RUNNING = "running"
    BLOCKED = "blocked"
    PAUSED = "paused"
    NEEDS_INPUT = "needs_input"
    REVIEWING = "reviewing"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"
    REJECTED = "rejected"


ALLOWED_QUEST_TRANSITIONS = {
    QuestStatus.PROPOSED: {
        QuestStatus.AWAITING_APPROVAL,
        QuestStatus.REJECTED,
        QuestStatus.CANCELLED,
    },
    QuestStatus.AWAITING_APPROVAL: {
        QuestStatus.APPROVED,
        QuestStatus.REJECTED,
        QuestStatus.CANCELLED,
    },
    QuestStatus.APPROVED: {QuestStatus.QUEUED, QuestStatus.PAUSED, QuestStatus.CANCELLED},
    QuestStatus.QUEUED: {QuestStatus.RUNNING, QuestStatus.PAUSED, QuestStatus.CANCELLED},
    QuestStatus.RUNNING: {
        QuestStatus.BLOCKED,
        QuestStatus.PAUSED,
        QuestStatus.NEEDS_INPUT,
        QuestStatus.REVIEWING,
        QuestStatus.COMPLETED,
        QuestStatus.FAILED,
        QuestStatus.CANCELLED,
    },
    QuestStatus.BLOCKED: {
        QuestStatus.QUEUED,
        QuestStatus.RUNNING,
        QuestStatus.CANCELLED,
        QuestStatus.FAILED,
    },
    QuestStatus.PAUSED: {QuestStatus.QUEUED, QuestStatus.CANCELLED},
    QuestStatus.NEEDS_INPUT: {QuestStatus.QUEUED, QuestStatus.CANCELLED},
    QuestStatus.REVIEWING: {QuestStatus.RUNNING, QuestStatus.COMPLETED, QuestStatus.FAILED},
    QuestStatus.COMPLETED: set(),
    QuestStatus.FAILED: set(),
    QuestStatus.CANCELLED: set(),
    QuestStatus.REJECTED: set(),
}


class DomainError(ValueError):
    pass


class QuestVersionConflict(DomainError):
    pass


def validate_quest_transition(current: QuestStatus, target: QuestStatus) -> None:
    if target not in ALLOWED_QUEST_TRANSITIONS[current]:
        raise DomainError(f"Illegal Quest transition: {current.value} -> {target.value}")


class ConversationMessage(BaseModel):
    id: str = Field(default_factory=lambda: new_id("msg"))
    role: str
    content: str
    created_at: str = Field(default_factory=now_iso)
    metadata: dict = Field(default_factory=dict)


class Quest(BaseModel):
    id: str = Field(default_factory=lambda: new_id("quest"))
    title: str
    goal: str
    status: QuestStatus = QuestStatus.PROPOSED
    version: int = Field(default=0, ge=0)
    priority: int = Field(default=3, ge=1, le=5)
    created_at: str = Field(default_factory=now_iso)
    updated_at: str = Field(default_factory=now_iso)
    metadata: dict = Field(default_factory=dict)
}) {
  const items = groupEvents(mergeTimeline(messages, events, outgoing));
