    {conversationError && <p className="notice error" role="alert">{conversationError}</p>}
    {timelineError && <p className="notice error" role="alert">过程记录暂不可用：{timelineError}</p>}
    {!items.length && <div className="empty-conversation"><svg className="empty-symbol" viewBox="149 149 418 418" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M247.429 247.43C257.73 208.911 292.871 180.543 334.638 180.543C359.555 180.543 382.115 190.64 398.449 206.964C405.906 204.97 413.743 203.905 421.829 203.905C471.681 203.906 512.096 244.32 512.096 294.173C512.096 302.259 511.031 310.096 509.037 317.553C525.361 333.887 535.458 356.446 535.458 381.364C535.458 423.131 507.09 458.271 468.571 468.572C458.271 507.091 423.131 535.459 381.364 535.459C356.446 535.459 333.886 525.362 317.552 509.037C310.095 511.031 302.258 512.097 294.172 512.097C244.319 512.097 203.906 471.682 203.906 421.829C203.906 413.743 204.969 405.905 206.963 398.448C190.639 382.115 180.543 359.555 180.543 334.638C180.543 292.871 208.91 257.73 247.429 247.43Z" strokeWidth="41.162" /><path d="M436.706 408.738H370.021M276.533 309.154L303.468 357.831C304.433 359.575 304.412 361.698 303.414 363.423L276.533 409.854" strokeWidth="24" /></svg><h2>你想让我们在 FORGE 中构建什么？</h2><p>从这里开始。描述目标，或继续之前的任务。所有结果都会回到这个对话。</p></div>}
    {items.map((item) => {
      if (item.type === "group") return <EventGroup key={`${item.events[0].kind}:${item.events[0].event_id}`} item={item} onQuest={onQuest} onInspect={onInspect} />;
      if (item.type === "outgoing") return <article key={`outgoing:${item.value.requestId}`} className="message from-user"><div className="message-meta"><span className="message-avatar">你</span><strong>你</strong><span>{item.value.status === "sending" ? "发送中" : "发送失败"}</span></div><div className="message-body"><MarkdownMessage content={item.value.content} native={native} onInspect={onInspect} />{item.value.status === "failed" && <div className="outgoing-error" role="alert">{item.value.error || "请求未完成"} · 请求 ID：<code>{item.value.requestId}</code><button className="text-button" disabled={!canRetry} onClick={() => onRetry(item.value)}>使用原请求重试</button></div>}</div></article>;
      const message = item.value, meta = messageMetadata(message.metadata);
      return <article key={message.id} className={`message ${message.role === "user" ? "from-user" : "from-agent"}`}><div className="message-meta"><span className="message-avatar">{message.role === "user" ? "你" : "F"}</span><strong>{message.role === "user" ? "你" : "FORGE"}</strong>{meta.execution_mode === "mock" && <span>模拟</span>}{meta.execution_mode === "live" && <span>真实执行</span>}{message.role !== "user" && meta.execution_mode !== "live" && meta.execution_mode !== "mock" && <span>来源未知</span>}<time>{message.created_at ? new Date(message.created_at).toLocaleString() : ""}</time></div><div className="message-body"><MarkdownMessage content={message.content} native={native} onInspect={onInspect} /></div></article>;
    })}
    {connected && (active.length > 0 || approvals.length > 0) && <section className="timeline-updates" aria-label="任务与审批更新"><div className="timeline-updates-label">当前任务与审批</div>{approvals.slice(0, 3).map((item) => <div className="timeline-update approval-card" key={text(item.id)}><button className="approval-summary" onClick={() => onApproval(text(item.quest_id, ""))}><span><strong>需要审批 · {text(item.action_type)}</strong><small>风险 {text(item.risk)} · {text(item.resource_scope)}</small></span><span aria-hidden="true">›</span></button><dl><dt>计划版本</dt><dd>{text(item.plan_revision)}</dd><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl><div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={approvalsBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => onApprovalDecision(item, decision)}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div></div>)}{active.map((quest) => <button className="timeline-update" key={quest.id} onClick={() => onQuest(quest.id)}><span><strong>{quest.title}</strong><small>状态：{quest.status} · 版本 {quest.version}</small></span><span aria-hidden="true">›</span></button>)}</section>}
    {connected && approvalError && <p className="notice error" role="alert">审批状态暂不可用：{approvalError}</p>}
  </div>;
}

