.desktop-chrome { grid-column: 1 / -1; height: 36px; display: flex; align-items: center; justify-content: space-between; padding: 0 12px 0 0; }
.desktop-chrome-leading { display: flex; align-items: center; gap: 6px; color: var(--muted); }
.desktop-chrome-leading > span { display: grid; place-items: center; width: 28px; height: 28px; }
.desktop-chrome-leading > span:first-child, .desktop-chrome-leading > span:nth-child(2) { opacity: .45; }
.desktop-menu { display: flex; align-items: center; gap: 2px; margin-left: 4px; }
.desktop-menu > span { padding: 3px 10px; font-size: 13px; line-height: 22px; }
.connection-indicator { font-size: 11px; line-height: 16px; color: var(--muted); white-space: nowrap; }
.status-dot { display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--muted); }
.status-dot.on { background: var(--color-accent); }

