.nav-item.active { color: var(--color-text); background: var(--color-background-nav-active); }
.nav-item:hover, .profile-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.nav-icon { width: 20px; height: 20px; flex: none; }
.profile-button { margin-top: auto; }
.sidebar-panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; }
/* Settings replaces the conversation list, while the primary icon rail stays available. */
.app-shell.settings-open { grid-template-columns: 52px minmax(0,1fr); }
.settings-open .rail { grid-template-columns: 52px; }
.settings-open .sidebar-panel { display: none; }
.sidebar-heading { height: 60px; display: flex; align-items: center; gap: 4px; padding: 0 16px; }
.sidebar-heading > strong { font-size: 18px; font-weight: 500; line-height: 24px; }
