      <div className="desktop-location"><strong>FORGE</strong><span aria-hidden="true">/</span><span>{settingsOpen ? "设置" : taskView ? "任务工作台" : view === "memory" ? "记忆检索" : "长期对话"}</span></div>
      <div className="connection-indicator"><span className={connection ? "status-dot on" : "status-dot"} />{connection ? "Core 已连接" : "Core 未连接"}</div>
    </header>
