    shortcuts: [["打开设置", "Ctrl + ,"], ["发送消息", "Enter"], ["换行", "Shift + Enter"]],
  };
  return <>{information[setting]?.map(([label, value]) => <SettingsRow key={label} label={label}><span>{value}</span></SettingsRow>)}</>;
