.settings-content .inspector-header > div { display: none; }
.settings-content .inspector-body { overflow: visible; padding: 0; }
.settings-content .field-label { display: grid; grid-template-columns: minmax(0,1fr) minmax(160px,48%); align-items: center; gap: 24px; margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18px; }
.settings-content .field-label input, .settings-content .field-label textarea, .settings-content .field-label select { padding: 4px 12px; font-size: 13px; line-height: 18px; background: var(--color-background-control-subtle); }
.settings-content .check-label { margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); font-size: 13px; }
