.quest-technical { margin-top: 16px; font-size: 12px; line-height: 18px; }
.quest-technical > summary { width: fit-content; color: var(--muted); }
.quest-technical > summary:hover { color: var(--color-text); }
.quest-technical pre { border-radius: 8px; }
.section-heading { display: flex; justify-content: space-between; margin-bottom: 12px; color: var(--muted); font-size: 12px; line-height: 16px; font-weight: 500; }
.section-heading.spaced { margin-top: 24px; }
.list-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; width: 100%; padding: 8px 10px; border: 0; border-radius: 12.5px; background: none; text-align: left; }
.list-row:hover, .list-row.selected { background: var(--color-background-secondary-ghost-hover); }
.list-row strong, .data-row strong, .plan-node strong { display: block; font-size: 13px; line-height: 20px; font-weight: 500; overflow-wrap: anywhere; }
.list-row small, .data-row small, .plan-node small { display: block; margin-top: 4px; color: var(--muted); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.state-label { color: var(--muted); font-size: 12px; white-space: nowrap; }
.data-row, .detail { padding: 16px 0; border-bottom: 1px solid var(--color-border-subtle); }
.detail h3 { margin: 8px 0; font-size: 16px; line-height: 24px; font-weight: 500; }
.detail p, .data-row p { font-size: 13px; line-height: 20px; color: var(--color-text-secondary); }
.plan-node { padding: 12px 0; border-top: 1px solid var(--color-border-subtle); }
.notice { color: var(--muted); font-size: 12px; line-height: 18px; }
.error, .send-error { color: var(--color-status-error) !important; }
.warning { color: var(--color-status-warning) !important; }
dl { display: grid; grid-template-columns: 80px minmax(0,1fr); gap: 8px 12px; font-size: 12px; line-height: 18px; }
dt { color: var(--muted); }
dd { margin: 0; min-width: 0; color: var(--color-text-secondary); }
.mono, pre, code { font-family: var(--font-mono); }
.mono { font-size: 12px; }
.break { overflow-wrap: anywhere; }
pre { max-height: 300px; overflow: auto; padding: 12px; white-space: pre-wrap; overflow-wrap: anywhere; background: var(--app-color-background-surface-under); font-size: 12px; line-height: 18px; }
