.field-label { display: grid; gap: 8px; margin-bottom: 16px; color: var(--color-text-secondary); font-size: 13px; line-height: 18px; }
.field-label input, .field-label select, .field-label textarea, .search input { width: 100%; min-width: 0; border: 1px solid var(--color-border); border-radius: 8px; padding: 8px 10px; background: var(--app-color-background-control); }
.search { display: flex; gap: 8px; margin-bottom: 16px; }
.button { border: 1px solid var(--color-border); border-radius: 8px; padding: 6px 12px; background: var(--app-color-background-surface); color: var(--color-text); font-size: 13px; line-height: 18px; white-space: nowrap; }
.button:hover { background: var(--color-background-secondary-ghost-hover); }
