.restore-warning { margin: 16px 0; padding: 12px; border: 1px solid var(--color-border-warning); border-radius: 12.5px; background: var(--color-background-warning); color: var(--color-status-warning); font-size: 12px; line-height: 18px; }

/* Safe Markdown rendering stays in React; these are presentation rules only. */
.markdown { font-size: inherit; line-height: inherit; overflow-wrap: anywhere; }
.markdown p { margin: 0 0 12px; }
.markdown p:last-child { margin-bottom: 0; }
.markdown h1, .markdown h2, .markdown h3 { margin: 24px 0 12px; line-height: 1.4; font-weight: 500; }
.markdown h1 { font-size: 24px; } .markdown h2 { font-size: 20px; } .markdown h3 { font-size: 18px; }
