.code-block pre code { padding: 0; background: none; font-size: inherit; line-height: inherit; }
.copy-status, .image-placeholder { color: var(--muted); font-size: 12px; line-height: 16px; }
.message .message-meta, .copy-btn, .code-toolbar button, .event-line .actions { opacity: 0; transition: opacity var(--transition-duration-basic) var(--ease-basic); }
.message:hover .message-meta, .message:focus-within .message-meta, .command-card:hover .copy-btn, .command-card:focus-within .copy-btn, .code-block:hover .code-toolbar button, .code-block:focus-within .code-toolbar button, .event-line:hover .actions, .event-line:focus-within .actions, .copy-btn:focus-visible, .code-toolbar button:focus-visible { opacity: 1; }

@media (max-width: 1000px) {
  .settings-view { grid-template-columns: 224px minmax(0,1fr); }
  .settings-nav { width: 224px; }
  .settings-content { padding: 24px; }
  .settings-row { gap: 16px; }
  .quest-workspace { grid-template-columns: minmax(0,1fr); }
  .quest-list { padding: 0 0 16px; border-right: 0; border-bottom: 1px solid var(--color-border-subtle); }
