import type { ReactNode } from "react";
import { namesLabel, statusLabel } from "./presentation";

type Row = Record<string, unknown>;

export interface WorkspaceQuest {
  id: string;
  title: string;
  status: string;
  version: number;
  goal: string;
}

export interface QuestWorkspaceProps {
  quests: WorkspaceQuest[];
  selected: WorkspaceQuest | null;
  selectedId: string;
  connected: boolean;
  error: string;
  hasMore: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  plan: Row | null;
  planNotice: ReactNode;
  blocked: boolean;
  onApprove: () => void;
  grants: ReactNode;
}

const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const records = (value: unknown): Row[] => Array.isArray(value)
  ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];

const QUEST_PHASES: Record<string, string> = {
  proposed: "目标已提出，后续计划与团队仍以实际提案为准。",
  awaiting_approval: "任务正在等待批准。请核对计划、任务团队及审批中心中需要确认的内容。",
  approved: "任务已批准；执行仍需满足当前计划、团队、工具权限与预算约束。",
  queued: "任务已进入队列，等待满足资源与执行条件。",
  running: "任务处于运行阶段。运行活动中可查看已记录的成员执行情况。",
  blocked: "任务已阻塞。请结合运行活动、审批与权限记录核对原因。",
  paused: "任务已暂停，当前记录保留在此工作空间。",
  needs_input: "任务需要补充信息，请回到长期对话继续说明。",
  reviewing: "任务正在复核。请以验证与最终任务状态判断结果。",
  completed: "任务状态为已完成，可通过计划与运行活动回查执行和验证记录。",
  failed: "任务已失败。请查看运行活动，并在长期对话中讨论后续处理。",
  cancelled: "任务已取消，历史计划与执行记录仍可回查。",
  rejected: "任务已拒绝，可查看历史计划与审批记录了解处理经过。",
};

function costLimit(plan: Row): string {
  if (plan.max_cost_microunits === null) return "未设置";
  if (plan.max_cost_microunits === undefined) return "未知";
  return `${text(plan.max_cost_microunits)} 微单位 · ${text(plan.cost_currency, "币种未知")}`;
}

function criteria(value: unknown): string {
  return Array.isArray(value) ? value.map((item) => text(item)).join("；") || "未提供" : text(value, "未提供");
}

export default function QuestWorkspace({
  quests, selected, selectedId, connected, error, hasMore, onSelect, onLoadMore,
  plan, planNotice, blocked, onApprove, grants,
}: QuestWorkspaceProps) {
  const nodes = records(plan?.nodes);
  return <div className="quest-workspace">
    <div className="quest-list">
      <div className="section-heading"><span>后台任务</span><span>{quests.length}{hasMore ? "+" : ""} 项已加载</span></div>
      {error && <p className="notice error" role="alert">任务列表加载失败：{error}</p>}
      {!quests.length ? <div className="quest-empty">
        <p>{connected ? "暂无后台任务" : "连接 Core 后显示任务"}</p>
        <p className="notice">在长期对话中提出目标，计划、团队与执行记录会归到对应任务。</p>
      </div> : <div className="list">{quests.map((quest) => <button
        type="button" key={quest.id}
        className={selectedId === quest.id ? "list-row selected" : "list-row"}
        aria-label={`${quest.title} ${quest.id} ${quest.status}`}
        aria-current={selectedId === quest.id ? "page" : undefined}
        onClick={() => onSelect(quest.id)}
      ><span><strong>{quest.title}</strong><small>{quest.goal}</small></span><span className="state-label">{statusLabel(quest.status)}</span></button>)}</div>}
      {hasMore && <button type="button" className="text-button more" onClick={onLoadMore}>加载更多任务</button>}
    </div>

    <div className="quest-detail">
      {!selected ? <div className="quest-empty quest-empty-selection"><h3>选择任务，查看计划与权限</h3><p className="notice">每个任务的计划、团队、审批与执行记录保持独立，结果回到同一个长期对话。</p></div> : <>
        <div className="detail quest-overview">
          <span className="eyebrow">当前任务</span>
          <h3>{selected.title}</h3>
          <p className="quest-goal">{selected.goal}</p>
          <div className="quest-phase"><strong>{statusLabel(selected.status)}</strong><span>版本 {selected.version}</span></div>
          <p className="notice">{QUEST_PHASES[selected.status] || "当前阶段以服务端原始状态为准。"}</p>
        </div>

        <section className="quest-plan">
          <div className="section-heading spaced"><span>执行计划</span>{plan && <span>{nodes.length} 个节点</span>}</div>
          {planNotice}
          {plan && <>
            <dl className="quest-plan-facts"><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>状态</dt><dd>{statusLabel(plan.status)}</dd><dt>总 Token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{costLimit(plan)}</dd></dl>
            <div className="quest-plan-nodes">{nodes.map((node, index) => <div className="plan-node" key={text(node.key, String(index))}>
              <div className="plan-node-heading"><strong>{index + 1}. {text(node.objective)}</strong><span className="state-label">{statusLabel(node.status)}</span></div>
              <small>Token 预算：{text(node.budget_tokens)}</small>
              <small>允许工具：{namesLabel(node.allowed_tools)}</small>
              <small>验收条件：{criteria(node.success_criteria)}</small>
            </div>)}</div>
            <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>计划摘要</dt><dd className="mono break">{text(plan.digest)}</dd></dl><pre>{JSON.stringify(plan, null, 2)}</pre></details>
            {plan.status === "proposed" && typeof plan.digest === "string" && <div className="button-row"><button type="button" className="button primary" disabled={blocked} onClick={onApprove}>批准此计划</button></div>}
          </>}
          {!plan && <details className="quest-technical"><summary>技术详情</summary><dl><dt>任务 ID</dt><dd className="mono break">{selected.id}</dd><dt>原始状态</dt><dd>{selected.status}</dd></dl></details>}
        </section>
      </>}
      {grants}
    </div>
  </div>;
}

    catch (error) { setActionError(errorMessage(error)); }
    finally { maintenanceSubmitting.current = false; setActionBusy(false); }
  };

  const retryRuntime = async () => {
    if (!native || writesBlocked || actionBusy || !window.confirm("重启本地 Core？正在运行的任务可能中断。")) return;
    setActionBusy(true); setActionError("");
    try { await invoke("runtime_retry"); await syncNative(); }
    catch (error) { setActionError(errorMessage(error)); }
    finally { setActionBusy(false); }
  };

  const plan = visiblePlan.value as Row | null;
  const panelItems = (view === "memory" || view === "approvals") && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items) :
    view === "activity" && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items ?? (visiblePanel.value as Row).events) : rows(visiblePanel.value);
  const title = VIEW_NAMES[view];
  const taskView = TASK_VIEWS.includes(view);
  const openTaskView = (destination: View, id = selectedId) => { setSettingsOpen(false); setSelectedId(id); setView(destination); setActionError(""); };
  const openConversation = () => { setSettingsOpen(false); setView("chat"); requestAnimationFrame(() => document.querySelector<HTMLTextAreaElement>('textarea[aria-label="消息内容"]')?.focus()); };
  const workspaceTitle = connection ? text(coreInfo.workspace_root, connection.workspace_id).split(/[\\/]/).filter(Boolean).slice(-1)[0] || connection.workspace_id : "工作空间";
  const selectSetting = (id: SettingId) => { setSetting(id); setView(SETTING_VIEWS[id] || "settings"); setActionError(""); };
  const decideApproval = (item: Row, decision: "APPROVED" | "REJECTED") => {
    if (window.confirm(`${decision === "APPROVED" ? "批准" : "拒绝"}此操作？\n风险：${text(item.risk)}\n范围：${text(item.resource_scope)}\n计划版本：${text(item.plan_revision)}\n参数摘要：${text(item.parameter_digest)}`)) void perform(`/api/approvals/${encodeURIComponent(text(item.id))}/decision`, { decision, expected_digest: item.parameter_digest, expected_plan_revision: item.plan_revision });
  };
  const grantPanel = (view === "quests" || view === "approvals") && selected && <GrantPanel quest={selected} state={visibleGrants} workspace={grantContext === `${questContextKey}|${view}` ? workspaceRoot : ""} scope={grantScope} setScope={setGrantScope} blocked={actionBusy || writesBlocked} submit={(path, body) => void perform(path, body)} />;

  return <div className={`app-shell${settingsOpen ? " settings-open" : ""}`}>
    <header className="desktop-chrome">
      <div className="desktop-location"><strong>FORGE</strong><span aria-hidden="true">/</span><span>{settingsOpen ? "设置" : taskView ? "任务工作台" : view === "memory" ? "记忆检索" : "长期对话"}</span></div>
      <div className="connection-indicator"><span className={connection ? "status-dot on" : "status-dot"} />{connection ? "Core 已连接" : "Core 未连接"}</div>
    </header>
    <aside className="rail" aria-label="主导航">
      <div className="primary-rail"><nav className="primary-nav">{NAV.map((item) => <button key={item.id} title={item.name} aria-label={item.name} className={!settingsOpen && (view === item.id || (item.id === "quests" && taskView)) ? "nav-item active" : "nav-item"} aria-current={!settingsOpen && (view === item.id || (item.id === "quests" && taskView)) ? "page" : undefined} onClick={() => { setSettingsOpen(false); setView(item.id); setActionError(""); }}><Icon name={item.id} /><span className="sr-only">{item.label}</span></button>)}</nav>
        <button className="profile-button" aria-label="设置" title="设置 (Ctrl+,)" onClick={openSettings}><Icon name="settings" /></button>
      </div>
      <WorkspaceSidebar connected={!!connection} workspaceId={connection?.workspace_id || ""} workspaceRoot={connection ? text(coreInfo.workspace_root, "") : ""}
        quests={quests} selectedId={taskView ? selectedId : ""} chatActive={view === "chat" && !settingsOpen} ready={!!connection && seenInitialized.current}
        questError={questLoadError} approvalError={approvalLoadError} pendingApprovals={pendingApprovals.length}
        onChat={openConversation} onQuest={(id) => openTaskView("quests", id)} onTasks={() => openTaskView("quests")}
        onApprovals={() => openTaskView("approvals", text(pendingApprovals[0]?.quest_id, selectedId))}>
        {!connection && <div className="connect-banner" role="status"><div><strong>{native ? "正在连接本地 Core" : "连接开发 Core"}</strong><p>{native ? "等待桌面运行时提供安全会话。" : "输入本次 Core 启动密钥。密钥不会保存在浏览器中。"}</p>{connectionError && <p className="error">{connectionError}</p>}</div>{!native && <div className="connect-controls"><input ref={secretInput} type="password" autoComplete="off" aria-label="Core 启动密钥" placeholder="本次启动密钥" /><button className="button primary" onClick={() => void connectBrowser()}>连接</button></div>}</div>}
      </WorkspaceSidebar>
    </aside>
    <main className={`conversation-shell${messages.length || timelineEvents.length || outgoing.length ? "" : " home-state"}`} hidden={view !== "chat"}>
      <header className="topbar"><div className="topbar-title"><h1>长期对话</h1><small>{workspaceTitle} · 已加载 {messages.length} 条消息、{timelineEvents.length} 条记录</small></div></header>
      {writesBlocked && <div className="maintenance-banner" role="status">{restoreFenced === true ? "恢复后写操作已锁定，请先人工核对。" : workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged ? "维护结果未知，请人工核查；写操作已暂停。" : runtimeStatus?.state === "maintenance" || workspaceOperation?.status === "running" ? "正在备份或恢复，完成后可退出；写操作已暂停。" : "正在核对工作空间恢复状态；写操作暂不可用。"}</div>}
      <ChatTimeline messages={messages} events={timelineEvents} outgoing={outgoing} quests={quests}
        approvals={pendingApprovals} native={native} connected={!!connection} historyMore={hasMore || timelineHasMore}
        historyBusy={historyBusy} timelineError={timelineError} conversationError={conversationError}
        approvalError={approvalLoadError} canRetry={!!connection && !sending && !writesBlocked} scrollRef={scrollRef}
        onScroll={() => { const element = scrollRef.current; if (!element || manualPause.current) return; followBottom.current = isNearBottom(element.scrollTop, element.clientHeight, element.scrollHeight); if (followBottom.current) setHasNew(false); }}
        onInspect={() => { manualPause.current = true; followBottom.current = false; setReadingPaused(true); }}
        onLoadOlder={() => void loadOlder()} onRetry={(item) => void sendPending(item, false)}
        onQuest={(id) => openTaskView("quests", id)}
        onApproval={(id) => openTaskView("approvals", id)}
        approvalsBlocked={actionBusy || writesBlocked} onApprovalDecision={decideApproval} />
      {actionError && <p className="notice error action-error" role="alert">{actionError}</p>}
      {(hasNew || readingPaused) && <button className="new-messages" onClick={() => { manualPause.current = false; followBottom.current = true; setReadingPaused(false); setHasNew(false); if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }}>{hasNew ? "有新消息 · 回到最新 ↓" : "回到最新 ↓"}</button>}
      <footer className="composer-wrap"><div className="composer-context"><span title={connection ? text(coreInfo.workspace_root, connection.workspace_id) : "未连接工作空间"}><ShellGlyph name="folder" />{workspaceTitle}</span><span><ShellGlyph name="local" />{connection ? coreInfo.provider_configured === false ? "供应商未配置" : "Core 已连接" : "等待 Core 连接"}</span><span className="composer-context-model">{connection ? text(coreInfo.provider_id, "") : ""}</span></div><div className="composer"><textarea value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => { if (shouldSubmitOnEnter({ key: event.key, shiftKey: event.shiftKey, isComposing: event.nativeEvent.isComposing, keyCode: event.nativeEvent.keyCode })) { event.preventDefault(); void send(); } }} placeholder="描述目标、补充信息，或继续之前的任务…" aria-label="消息内容" /><div className="composer-bottom"><span className="composer-keyboard">Enter 发送 · Shift + Enter 换行</span><span className="composer-model" title="当前 Router 模型（只读）">Router · {connection ? text(coreInfo.router_model_id) : "未连接"}</span><button className="send-button" aria-label="发送消息" disabled={!connection || sending || writesBlocked || !draft.trim()} onClick={() => void send()}>↑</button></div></div>{sendError && <p className="send-error" role="alert">{sendError} 草稿已保留。请求 ID：<code>{pending?.requestId}</code></p>}</footer>
    </main>
    {view !== "chat" && <WorkspaceFrame settingsOpen={settingsOpen} setting={setting} onSetting={selectSetting} title={title}>
      <header className="inspector-header"><div><h2>{title}</h2></div><button className="icon-button" aria-label="刷新当前视图" onClick={() => { void refreshConversation(); void refreshPanel(); void refreshGrants(); setPlanRefresh((value) => value + 1); }}>↻</button></header>
      <div className="inspector-body">
        {!settingsOpen && taskView && <><p className="workspace-description">围绕同一个任务查看计划、团队、执行与审批。进展和交付始终回到长期对话。</p><div className="workspace-tabs">{TASK_VIEWS.map((destination) => <button key={destination} className={view === destination ? "text-button active" : "text-button"} aria-current={view === destination ? "page" : undefined} onClick={() => openTaskView(destination)}>{VIEW_NAMES[destination]}</button>)}</div></>}
        {view === "quests" && <QuestWorkspace quests={quests} selected={selected || null} selectedId={selectedId}
          connected={!!connection} error={questLoadError} hasMore={!!questsBefore}
          onSelect={(id) => { setSelectedId(id); setView("quests"); }} onLoadMore={() => void loadMoreQuests()}
          plan={plan} planNotice={<StateNotice state={visiblePlan} empty="暂无计划" />} blocked={actionBusy || writesBlocked || visiblePlan.loading}
          onApprove={() => { if (selected && plan && window.confirm(`批准计划？\n任务版本：${selected.version}\n计划版本：${text(plan.plan_revision)}\n摘要：${text(plan.digest)}\n请先检查任务节点、权限和预算。`)) void perform(`/api/quests/${encodeURIComponent(selected.id)}/plan/approve`, { digest: plan.digest, plan_revision: plan.plan_revision, expected_version: selected.version }); }}
          grants={grantPanel} />}
        {(view === "teams" || view === "approvals" || view === "activity") && <label className="field-label">任务范围<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)}><option value="">{view === "activity" ? "全部任务" : "选择任务"}</option>{quests.map((quest) => <option key={quest.id} value={quest.id}>{quest.title}</option>)}</select></label>}
        {view === "teams" && <p className="notice">成员在各自的私有执行上下文中工作。批准前核对模型、工具权限与预算；团队批准绑定当前任务和计划版本。</p>}
