        {view === "memory" && panelItems.length > 0 && <><div className="list">{(panelItems as MemoryItem[]).map((item) => <div className="data-row" key={item.id}><strong>{item.statement}</strong><small>{text(item.layer)} · {text(item.kind)} · {statusLabel(item.status)} · {text(item.freshness, "新鲜度未知")}</small><dl><dt>来源</dt><dd className="break">{item.source_refs?.join(", ") || "未知"}</dd><dt>记录时间</dt><dd>{text(item.created_at)}</dd><dt>有效至</dt><dd>{text(item.valid_until, "未指定")}</dd><dt>可信度</dt><dd>{text(item.confidence, "未知")}</dd><dt>关联任务</dt><dd className="break">{Array.isArray(item.related_quest_ids) ? item.related_quest_ids.join(", ") || "无" : "未知"}</dd></dl>{item.conflicted === true && <p className="warning">存在冲突，请核对来源。</p>}{/^[a-f0-9]{32}$/i.test(item.id) && <button className="button" disabled={actionBusy || writesBlocked} onClick={() => { if (window.confirm(`撤销这条记忆？\n${item.statement}`)) void perform(`/api/memory/${encodeURIComponent(item.id)}/revoke`); }}>撤销记忆</button>}</div>)}</div>{memoryCursor && <button className="text-button more" disabled={visiblePanel.loading} onClick={() => void loadPanelPage()}>加载更多记忆</button>}</>}
        {view === "settings" && <>
          <SettingInfo setting={setting} />
          {setting === "general" && <CoreOverview settings={Array.isArray(visiblePanel.value) ? visiblePanel.value[0] as Row : coreInfo} connected={!!connection} />}
          {setting === "environment" && <><div className="section-heading"><span>运行配置与预算</span></div><p className="notice">仅显示 Core 提供的非密钥配置；未知值保持未知。</p>{runtimeStatus && <div className="settings-facts"><SettingsRow label="运行状态"><span>{text(runtimeStatus.state)}</span></SettingsRow><SettingsRow label="进程代次"><span className="break">{text(runtimeStatus.generation)}</span></SettingsRow><SettingsRow label="重启次数"><span>{runtimeStatus.restartCount}</span></SettingsRow><SettingsRow label="最近错误"><span>{text(runtimeStatus.lastErrorCode, "无")}</span></SettingsRow></div>}{Array.isArray(visiblePanel.value) && <OperatorSettings key={text((visiblePanel.value[0] as Row)?.revision, "0")} settings={visiblePanel.value[0] as Row} budget={visiblePanel.value[1] as Row} blocked={writesBlocked || actionBusy} save={(value) => void perform("/api/settings", value)} />}</>}
          {setting === "storage" && Array.isArray(visiblePanel.value) && <><BudgetOverview budget={visiblePanel.value[1] as Row} /><TechnicalDetails value={visiblePanel.value[1]} /></>}
          {setting === "maintenance" && <>{!native && <p className="notice">请在桌面应用中备份、恢复或重启本地 Core。恢复后的写入锁定与人工复核仍然适用。</p>}{native && <><div className="section-heading spaced"><span>工作空间维护</span></div><p className="notice">备份和恢复会暂时停止 Core；恢复成功后写操作保持锁定，需人工核对。</p><label className="field-label">备份目录的绝对路径<input value={workspacePath} onChange={(event) => setWorkspacePath(event.target.value)} placeholder="例如 D:/Backup/FORGE" /></label><div className="button-row"><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("backup")}>备份</button><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("restore")}>恢复</button><button className="button" disabled={writesBlocked || actionBusy} onClick={() => void retryRuntime()}>重启 Core</button></div>{workspaceOperation && <p className={workspaceOperation.status === "unknown" || workspaceOperation.result?.ok === false ? "notice error" : "notice"} role="status">{workspaceOperation.status === "running" ? "正在备份或恢复，完成后可退出。" : workspaceOperation.status === "unknown" ? (workspaceOperation.acknowledged ? "未知结果已归档；这不表示操作成功，也不会解除恢复锁定。" : "维护结果未知，请人工核查；不要重复发起。") : workspaceOperation.result?.ok ? (workspaceOperation.operation === "restore" ? "恢复完成；写操作已锁定，请先人工核对。" : "备份完成。") : `维护未完成：${text(workspaceOperation.result?.code)}`}{workspaceOperation.operationId && <> 操作 ID：<code>{workspaceOperation.operationId}</code></>}</p>}{workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged && workspaceOperation.operationId && <><label className="field-label">人工核查说明<input value={reviewReason} onChange={(event) => setReviewReason(event.target.value)} /></label><button className="button" disabled={actionBusy || !reviewReason.trim() || runtimeStatus?.state !== "ready"} onClick={() => void acknowledgeUnknown()}>归档未知结果</button><p className="notice">仅归档，不表示成功，不解除恢复锁或预算限制。</p></>}</>}</>}
          {setting === "connections" && <><SettingsRow label="供应商" description="当前 Core 的模型连接。">{text(coreInfo.provider_id)}</SettingsRow><SettingsRow label="Router 模型" description="运行配置中的默认模型。">{text(coreInfo.router_model_id)}</SettingsRow>{<><div className="section-heading spaced"><span>供应商凭据</span></div>{native ? <div className="credential-form"><label className="field-label">供应商 ID<input value={providerId} onChange={(event) => setProviderId(event.target.value)} autoComplete="off" /></label><label className="field-label">凭据引用<input value={credentialRef} onChange={(event) => setCredentialRef(event.target.value)} autoComplete="off" /></label><label className="field-label">新凭据<input ref={credentialInput} type="password" autoComplete="new-password" /></label><div className="button-row"><button className="button primary" disabled={writesBlocked} onClick={() => void credential("set")}>保存</button><button className="button" onClick={() => void credential("exists")}>检查是否存在</button><button className="button" disabled={writesBlocked} onClick={() => void credential("delete")}>删除</button></div>{credentialStatus && <p className="notice" role="status">{credentialStatus}</p>}</div> : <p className="notice">浏览器开发模式不提供系统凭据库。请在桌面应用中管理凭据。</p>}</>}</>}
          {restoreFenced === true && <div className="restore-warning"><strong>恢复待复核，后台与写入已暂停</strong><p>{restoreStatus?.review_available === true ? "请先核对当前工作区与回滚目录，退出应用后按 README 的离线维护步骤提交复核；此界面不会自动解除锁定。" : "复核记录不可用或损坏，请人工检查；不要尝试自动解锁。"}</p><div className="settings-facts"><SettingsRow label="清单摘要"><span className="break">{text(restoreStatus?.manifest_sha256)}</span></SettingsRow><SettingsRow label="回滚目录"><span className="break">{text(restoreStatus?.rollback_directory)}</span></SettingsRow></div></div>}
        </>}
        {view === "approvals" && grantPanel}
        {actionError && <p className="notice error" role="alert">{actionError}</p>}
      </div>
    </WorkspaceFrame>}
  </div>;
}
import { useRef, useState, type KeyboardEvent, type ReactNode } from "react";

export type SettingId = "general" | "shortcuts" | "models" | "environment" |
  "storage" | "connections" | "maintenance";

export interface SettingItem {
  id: SettingId;
  label: string;
  description: string;
  accessibleLabel?: string;
  keywords?: string;
}
interface SettingGroup { label: string; items: SettingItem[] }

export const settingGroups: SettingGroup[] = [
  { label: "工作空间", items: [
    { id: "general", label: "工作空间概况", accessibleLabel: "常规", description: "查看当前工作空间、Router 模型与 Core 连接状态。", keywords: "目录 路径 状态" },
    { id: "shortcuts", label: "键盘快捷键", description: "查找发送消息、换行和打开设置的键盘操作。" },
  ] },
  { label: "模型与运行", items: [
    { id: "models", label: "模型库", description: "管理模型档案、协议支持、上下文上限与能力来源。", keywords: "Registry 供应商 能力测量 启用 禁用" },
    { id: "environment", label: "运行配置", accessibleLabel: "环境", description: "配置模型连接、Router、Token 上限及网络访问范围。", keywords: "供应商 地址 API 网络 白名单 并发 重启" },
    { id: "storage", label: "用量与预算", accessibleLabel: "存储", description: "查看 Token 预算、已确认用量、未结算预留与并发占用。", keywords: "费用 货币 消耗 账本" },
  ] },
  { label: "安全与数据", items: [
    { id: "connections", label: "供应商凭据", accessibleLabel: "连接", description: "在桌面应用的系统凭据库中保存、检查和删除供应商凭据。", keywords: "密钥 API key credential" },
    { id: "maintenance", label: "备份与恢复", description: "备份和恢复工作空间，检查维护状态与恢复后的写入锁定。", keywords: "维护 数据 回滚 Core 重启" },
  ] },
];

export const settingMetadata = Object.fromEntries(settingGroups.flatMap((group) => group.items).map((item) => [item.id, item])) as Record<SettingId, SettingItem>;

function SettingsIcon({ id }: { id: SettingId }) {
  const symbols: Record<SettingId, ReactNode> = {
    general: <><path d="M3 7.5h18v12a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 19.5v-12Z" /><path d="m3 7.5 2-4h5l2 4m-5 5h10m-10 4h6" /></>,
    shortcuts: <><rect x="2.5" y="5.5" width="19" height="13" rx="2" /><path d="M6 9h1m4 0h1m4 0h1M6 12h1m4 0h1m4 0h1M7 15.5h10" /></>,
    models: <><path d="m12 2.5 9 5-9 5-9-5 9-5Z" /><path d="m3 12 9 5 9-5m-18 4.5 9 5 9-5" /></>,
    environment: <><path d="M4 6h3m4 0h9M4 12h10m4 0h2M4 18h3m4 0h9" /><rect x="7" y="3.5" width="4" height="5" rx="1" /><rect x="14" y="9.5" width="4" height="5" rx="1" /><rect x="7" y="15.5" width="4" height="5" rx="1" /></>,
    storage: <><path d="M4 3.5v17h17M8 16v-4m5 4V8m5 8V5" /></>,
    connections: <><circle cx="8" cy="8" r="4.5" /><path d="m11.5 11.5 9 9m-3-3 2.5-2.5m-5.5-.5 2.5-2.5" /></>,
    maintenance: <><path d="M4 9a8 8 0 1 1 0 6M4 3v6h6" /><path d="M12 7v5l3 2" /></>,
  };
  return <svg className="settings-nav-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">{symbols[id]}</svg>;
}

export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control settings-row-value">{children}</div>
  </div>;
}

export default function SettingsView({ selected, onSelect, children }: { selected: SettingId; onSelect: (id: SettingId) => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const searchInput = useRef<HTMLInputElement>(null);
  const itemButtons = useRef<Partial<Record<SettingId, HTMLButtonElement | null>>>({});
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.description} ${item.accessibleLabel || ""} ${item.keywords || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const visibleItems = groups.flatMap((group) => group.items);
  const current = settingMetadata[selected];
  const clearSearch = () => { setQuery(""); searchInput.current?.focus(); };
  const activate = (item: SettingItem) => { onSelect(item.id); itemButtons.current[item.id]?.focus(); };
  const navigate = (event: KeyboardEvent<HTMLButtonElement>, id: SettingId) => {
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    const index = visibleItems.findIndex((item) => item.id === id);
    const next = event.key === "ArrowDown" ? (index + 1) % visibleItems.length
      : event.key === "ArrowUp" ? (index - 1 + visibleItems.length) % visibleItems.length
      : event.key === "Home" ? 0 : event.key === "End" ? visibleItems.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    activate(visibleItems[next]);
  };
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <h1 className="settings-page-title">设置</h1><div className="settings-search"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg><input ref={searchInput} type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
        if (event.nativeEvent.isComposing) return;
        if (event.key === "Escape") { event.preventDefault(); clearSearch(); }
        else if (event.key === "Enter" && visibleItems.length) { event.preventDefault(); activate(visibleItems[0]); }
      }} />{query && <button type="button" className="settings-search-clear" aria-label="清除设置搜索" title="清除设置搜索" onClick={clearSearch}><svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><path d="m4 4 8 8m0-8-8 8" /></svg></button>}</div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} ref={(button) => { itemButtons.current[item.id] = button; }} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onKeyDown={(event) => navigate(event, item.id)} onClick={() => onSelect(item.id)}><SettingsIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <div className="settings-search-empty"><p className="notice">未找到匹配的设置</p><button type="button" className="text-button" onClick={clearSearch}>显示全部设置</button></div>}
    </nav>
    <div className="settings-content"><div className="settings-content-inner"><h1 className="settings-title">{current.label}</h1><p className="settings-description">{current.description}</p>{children}</div></div>
  </section>;
}

