          {planNotice}
          {plan && <>
            <dl className="quest-plan-facts"><dt>计划版本</dt><dd>{text(plan.plan_revision)}</dd><dt>状态</dt><dd>{statusLabel(plan.status)}</dd><dt>总 Token 预算</dt><dd>{text(plan.max_total_tokens)}</dd><dt>费用上限</dt><dd>{costLimit(plan)}</dd></dl>
            <div className="quest-plan-nodes">{nodes.map((node, index) => <div className="plan-node" key={text(node.key, String(index))}>
              <div className="plan-node-heading"><strong>{index + 1}. {text(node.objective)}</strong><span className="state-label">{statusLabel(node.status)}</span></div>
              <small>Token 预算：{text(node.budget_tokens)}</small>

  return <div className="sidebar-panel">
    <div className="sidebar-heading"><strong>FORGE</strong><small>长期任务工作空间</small></div>
    <div className="sidebar-workspace" title={workspacePath || undefined}>
      <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3" /></svg>
      <div><strong>{workspaceName}</strong><small>{workspacePath || "连接后显示工作空间"}</small></div>
    </div>
    <div className="sidebar-scroll">
      <button type="button" className={`thread-row${chatActive ? " active" : ""}`} aria-label="长期对话" aria-current={chatActive ? "page" : undefined} onClick={onChat}>
        <svg className="thread-icon" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M5 3.5h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 4v-16a2 2 0 0 1 2-2Z" /><path d="M7 8h10M7 12h7" /></svg>
        <span className="thread-text"><strong>长期对话</strong><small>提出目标、追问进展、继续任务</small></span>
      </button>

      <section className="sidebar-attention">
        <div className="sidebar-section-title"><span>需要处理</span><small>本次已加载</small></div>
        {approvalsKnown && pendingApprovals > 0
          ? <button type="button" className="sidebar-attention-row sidebar-attention-action" aria-label="查看待审批" onClick={onApprovals}><span>待审批操作</span><strong>{pendingApprovals}</strong></button>
          : <div className="sidebar-attention-row"><span>待审批操作</span><strong>{approvalsKnown ? pendingApprovals : pendingLabel}</strong></div>}
        <div className="sidebar-attention-row"><span>待处理任务</span><strong>{tasksKnown ? attentionCount : pendingLabel}</strong></div>
        {approvalError && <p className="sidebar-notice">审批状态暂不可用</p>}
      </section>

      <section className="sidebar-tasks">
        <div className="sidebar-section-title"><button type="button" className="sidebar-section-toggle" aria-label={tasksExpanded ? "折叠活跃任务" : "展开活跃任务"} aria-expanded={tasksExpanded} aria-controls={taskRegionId} onClick={() => setTasksExpanded((expanded) => !expanded)}><svg className="sidebar-section-chevron" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={tasksExpanded ? "m4 6 4 4 4-4" : "m6 4 4 4-4 4"} /></svg><span>活跃任务</span></button>{tasksKnown && <small>{activeQuests.length} 项已加载</small>}</div>
        <div id={taskRegionId} className="sidebar-task-items" hidden={!tasksExpanded}>
          {!connected ? <p className="sidebar-notice">连接后显示后台任务</p>
          : !ready ? <p className="sidebar-notice">正在同步任务…</p>
          : questError ? <p className="sidebar-notice">任务列表暂不可用</p>
          : activeQuests.length === 0 ? <p className="sidebar-notice">暂无活跃任务。在对话中描述你的目标。</p>
          : activeQuests.slice(0, 4).map((quest) => <button
            type="button" key={quest.id}
            title={quest.title}
            className={`sidebar-quest${!chatActive && selectedId === quest.id ? " selected" : ""}${needsQuestAttention(quest.status) ? " is-attention" : ""}`}
            aria-current={!chatActive && selectedId === quest.id ? "page" : undefined}
            onClick={() => onQuest(quest.id)}
          ><span>{quest.title}</span><small className="state-label sidebar-quest-status"><span className="sidebar-status-dot" data-status={quest.status} aria-hidden="true" /><span>{statusLabel(quest.status)}</span></small></button>)}
          <button type="button" className="text-button sidebar-action" disabled={!connected} onClick={onTasks}>查看全部任务</button>
        </div>
      </section>
    </div>
    <div className="sidebar-connection">{children}</div>
  </div>;
}

