      </section>

      <section className="sidebar-tasks">
        <div className="sidebar-section-title"><button type="button" className="sidebar-section-toggle" aria-label={tasksExpanded ? "折叠活跃任务" : "展开活跃任务"} aria-expanded={tasksExpanded} aria-controls={taskRegionId} onClick={() => setTasksExpanded((expanded) => !expanded)}><svg className="sidebar-section-chevron" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={tasksExpanded ? "m4 6 4 4 4-4" : "m6 4 4 4-4 4"} /></svg><span>活跃任务</span></button>{tasksKnown && <small>{activeQuests.length} 项已加载</small>}</div>
        <div id={taskRegionId} className="sidebar-task-items" hidden={!tasksExpanded}>
