/* ------------------------------------------------------------ bootstrapping */
async function boot() {
  const [threads, projects, agents] = await Promise.all([
    fetch('/data/threads.json').then(r => r.json()),
    fetch('/data/projects.json').then(r => r.json()),
    fetch('/data/agents.json').then(r => r.json()),
  ]);
  state.threads = threads;
  state.projects = projects;
  state.agents = agents;
  threads.forEach(t => THREADS_BY_ID.set(t.id, t));

  // agent thread id -> friendly name (from the spawn path)
  for (const a of agents) {
    if (!a.agentThreadId) continue;
    const name = a.agentPath ? a.agentPath.split('/').filter(Boolean).pop() : null;
    if (name) AGENT_NAME_BY_THREAD.set(a.agentThreadId, name);
  }

  await injectPartials();
  buildSidebar();
  wireTopbar();
  wireSidebarNav();
  wireProfileMenu();
  wireHomeComposer();
  wireGlobalKeys();
  buildSearchDialog();

  window.addEventListener('hashchange', route);
  route();
}

