      const m = s.match(/#\s*"([^"]{6,80})"/);
      return m ? m[1] : '粘贴文件的会话';
    }
    return s.length > 64 ? s.slice(0, 62) + '…' : s;
  }
  // subagent threads have no title: derive it from the spawn path
  const agentName = AGENT_NAME_BY_THREAD.get(t.id);
  if (agentName) return agentName;
  return '未命名会话';
}

