function projectOf(t) {
  if (!t.cwd) return null;
  const cwd = shortPath(t.cwd).toLowerCase();
  let best = null;
  for (const p of state.projects) {
    for (const root of p.roots || []) {
      const r = shortPath(root).toLowerCase().replace(/\\+$/, '');
      if (r && cwd.startsWith(r)) {
        if (!best || r.length > best.len) best = { name: p.name, len: r.length };
      }
    }
  }
  return best ? best.name : null;
}

