import { invoke, isTauri } from "@tauri-apps/api/core";
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import ChatTimeline from "./ChatTimeline";
import WorkerActivity, { useWorkerActivity } from "./ConversationRuntime";
import SettingsView, { SettingsRow, type SettingId } from "./SettingsView";
import WorkspaceSidebar from "./WorkspaceSidebar";
import BudgetOverview from "./BudgetOverview";
import QuestWorkspace from "./QuestWorkspace";
import ModelProfileSummary from "./ModelProfileSummary";
import { statusLabel, riskLabel, toolLabel } from "./presentation";
import { ApiError, browserConnection, request, type Connection } from "./api";
import { appendUnique, errorMessage, isNearBottom, operatorConfig, pendingMessage, preservedScrollTop, RequestGuard, retainIfEqual, shouldSubmitOnEnter, type OperatorForm, type PendingMessage } from "./logic";
import { messageMetadata, type ChatMessage as Message, type Outgoing, type TimelineEvent } from "./timeline";

type View = "chat" | "quests" | "activity" | "models" | "teams" | "memory" | "approvals" | "settings";
type Row = Record<string, unknown>;
interface TimelinePage { items: TimelineEvent[]; next_before?: string | null; has_more?: boolean }
interface Page { messages: Message[]; router?: Row; next_before?: string | null; has_more?: boolean }
interface NativeConnection { state: string; baseUrl: string; bearer: string; workspaceId: string; generation: string }
interface NativeStatus { state: string; generation: string; restartCount: number; lastErrorCode: string | null }
interface WorkspaceOperation { operationId: string; operation: "backup" | "restore"; status: "running" | "completed" | "unknown"; acknowledged?: boolean; result?: { ok: boolean; operation: string; code?: string } }
interface Quest extends Row { id: string; title: string; status: string; version: number; goal: string }
interface QuestPage { items: Quest[]; next_before?: string | null; has_more?: boolean }
interface MemoryItem extends Row { id: string; statement: string; source_refs: string[] }
interface DataState { loading: boolean; error: string; value: unknown }

const NAV: { id: View; label: string; name: string }[] = [
  { id: "chat", label: "对话", name: "对话" },
  { id: "quests", label: "任务", name: "后台任务" },
  { id: "memory", label: "记忆", name: "记忆中心" },
];
const VIEW_NAMES: Record<View, string> = { chat: "对话", quests: "后台任务", activity: "运行活动", models: "模型库", teams: "任务团队", memory: "记忆中心", approvals: "审批中心", settings: "设置" };
const SETTING_VIEWS: Partial<Record<SettingId, View>> = { models: "models" };
const TASK_VIEWS: View[] = ["quests", "teams", "activity", "approvals"];
const EMPTY: DataState = { loading: false, error: "", value: null };
const text = (value: unknown, fallback = "未知") => value == null || value === "" ? fallback : String(value);
const rows = (value: unknown): Row[] => Array.isArray(value) ? value.filter((x): x is Row => !!x && typeof x === "object") : [];
const display = (value: unknown) => typeof value === "string" ? value : JSON.stringify(value, null, 2);
const eventKey = (event: TimelineEvent) => `${event.kind}:${event.event_id}`;
const mergeEvents = (current: TimelineEvent[], next: TimelineEvent[]) => retainIfEqual(current, [...new Map([...current, ...next].map((event) => [eventKey(event), event])).values()]);

function Icon({ name }: { name: View }) {
  const paths: Record<View, React.ReactNode> = {
    chat: <path d="m3.5 10 8.5-7 8.5 7v10H15v-6H9v6H3.5Z" fill="currentColor" stroke="none" />,
    quests: <><path d="M3.5 7h6l2 2H20v9.5H3.5z" /><path d="M3.5 7V5.5h6l2 1.5" /></>,
    activity: <><circle cx="12" cy="12" r="8.5" /><path d="M12 7v5l3.5 2" /></>,
    models: <><rect x="4" y="4" width="6" height="6" rx="1" /><rect x="14" y="4" width="6" height="6" rx="1" /><rect x="4" y="14" width="6" height="6" rx="1" /><rect x="14" y="14" width="6" height="6" rx="1" /></>,
    teams: <><circle cx="9" cy="8" r="3" /><path d="M3.5 19c.3-3.2 2.1-5 5.5-5s5.2 1.8 5.5 5M15 5.5a3 3 0 0 1 0 5.8M16 14c2.5.3 3.9 2 4 5" /></>,
    memory: <><path d="M12 3.5 20.5 12 12 20.5 3.5 12z" /><circle cx="12" cy="12" r="2.5" /></>,
    approvals: <><path d="M12 3.5 19 6v5.5c0 4.1-2.4 7.2-7 9-4.6-1.8-7-4.9-7-9V6z" /><path d="m8.5 12 2.3 2.3 4.7-4.7" /></>,
    settings: <><circle cx="12" cy="12" r="3.2" /><path d="m9.8 3-1.2 2.2H6l-1.5 2.6 1.3 2.3v3.8l-1.3 2.3L6 18.8h2.6l1.2 2.2h4.4l1.2-2.2H18l1.5-2.6-1.3-2.3v-3.8l1.3-2.3L18 5.2h-2.6L14.2 3z" /></>,
  };
  return <svg className="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.55" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

function StateNotice({ state, empty = "暂无数据" }: { state: DataState; empty?: string }) {
  if (state.loading && state.value == null) return <p className="notice" role="status">正在加载…</p>;
  if (state.error) return <p className="notice error" role="alert">{state.error}</p>;
  if (state.value == null || (Array.isArray(state.value) && !state.value.length) ||
      (typeof state.value === "object" && state.value !== null && "items" in state.value && Array.isArray((state.value as Row).items) && !(state.value as {items: unknown[]}).items.length)) return <p className="notice">{empty}</p>;
  return null;
}

function TechnicalDetails({ value }: { value: unknown }) {
  return <details><summary>技术详情</summary><pre>{display(value)}</pre></details>;
}

function WorkspaceFrame({ settingsOpen, setting, onSetting, title, children }: {
  settingsOpen: boolean; setting: SettingId; onSetting: (id: SettingId) => void; title: string; children: React.ReactNode;
}) {
  return settingsOpen ? <SettingsView selected={setting} onSelect={onSetting}><aside className="settings-page" aria-label={title}>{children}</aside></SettingsView>
    : <aside className="workspace-panel" aria-label={title}>{children}</aside>;
}

function SettingInfo({ setting }: { setting: SettingId }) {
  const information: Partial<Record<SettingId, [string, string][]>> = {
    shortcuts: [["打开设置", "Ctrl + ,"], ["发送消息", "Enter"], ["换行", "Shift + Enter"]],
  };
  return <>{information[setting]?.map(([label, value]) => <SettingsRow key={label} label={label}><span>{value}</span></SettingsRow>)}</>;
}

function CoreOverview({ settings, connected }: { settings: Row; connected: boolean }) {
  return <div className="settings-group">
    <SettingsRow label="工作空间" description="当前长期对话与任务所在的工作空间。">{text(settings.workspace_root ?? settings.workspace_id)}</SettingsRow>
    <SettingsRow label="供应商" description="Core 当前使用的模型供应商。">{text(settings.provider_id)}</SettingsRow>
import { useId, useState, type ReactNode } from "react";
import { isClosedQuest, needsQuestAttention, statusLabel } from "./presentation";

export interface WorkspaceSidebarProps {
  connected: boolean;
  workspaceId: string;
  workspaceRoot: string;
  quests: Array<{ id: string; title: string; status: string }>;
  selectedId: string;
  chatActive: boolean;
  ready: boolean;
  questError: string;
  approvalError: string;
  pendingApprovals: number;
  onChat: () => void;
  onQuest: (id: string) => void;
  onTasks: () => void;
  onApprovals: () => void;
  children: ReactNode;
}

export default function WorkspaceSidebar({
  connected, workspaceId, workspaceRoot, quests, selectedId, chatActive, ready,
  questError, approvalError, pendingApprovals, onChat, onQuest, onTasks,
  onApprovals, children,
}: WorkspaceSidebarProps) {
  const [tasksExpanded, setTasksExpanded] = useState(true);
  const taskRegionId = useId();
  const tasksKnown = connected && ready && !questError;
  const approvalsKnown = connected && ready && !approvalError;
  const activeQuests = quests.filter((quest) => !isClosedQuest(quest.status));
  const attentionCount = activeQuests.filter((quest) => needsQuestAttention(quest.status)).length;
  const pendingLabel = !connected ? "未连接" : !ready ? "同步中" : "暂不可用";
  const workspacePath = connected ? workspaceRoot || workspaceId : "";
  const workspaceName = workspacePath.replace(/[\\/]+$/, "").split(/[\\/]/).pop() || "工作空间";

  return <div className="sidebar-panel">
    <div className="sidebar-heading"><strong>FORGE</strong><small>长期任务工作空间</small></div>
    <div className="sidebar-workspace" title={workspacePath || undefined}>
      <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3" /></svg>
      <div><strong>{workspaceName}</strong><small>{workspacePath || "连接后显示工作空间"}</small></div>
    </div>
    <div className="sidebar-scroll">
      <button type="button" className={`thread-row${chatActive ? " active" : ""}`} aria-label="长期对话" aria-current={chatActive ? "page" : undefined} onClick={onChat}>
        <svg className="thread-icon" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M5 3.5h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 4v-16a2 2 0 0 1 2-2Z" /><path d="M7 8h10M7 12h7" /></svg>
        <span className="thread-text"><strong>长期对话</strong><small>提出目标、追问进展、继续任务</small></span>
      </button>

      <section className="sidebar-attention">
        <div className="sidebar-section-title"><span>需要处理</span><small>本次已加载</small></div>
        {approvalsKnown && pendingApprovals > 0
          ? <button type="button" className="sidebar-attention-row sidebar-attention-action" aria-label="查看待审批" onClick={onApprovals}><span>待审批操作</span><strong>{pendingApprovals}</strong></button>
          : <div className="sidebar-attention-row"><span>待审批操作</span><strong>{approvalsKnown ? pendingApprovals : pendingLabel}</strong></div>}
        <div className="sidebar-attention-row"><span>待处理任务</span><strong>{tasksKnown ? attentionCount : pendingLabel}</strong></div>
        {approvalError && <p className="sidebar-notice">审批状态暂不可用</p>}
      </section>

      <section className="sidebar-tasks">
        <div className="sidebar-section-title"><button type="button" className="sidebar-section-toggle" aria-label={tasksExpanded ? "折叠活跃任务" : "展开活跃任务"} aria-expanded={tasksExpanded} aria-controls={taskRegionId} onClick={() => setTasksExpanded((expanded) => !expanded)}><svg className="sidebar-section-chevron" viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={tasksExpanded ? "m4 6 4 4 4-4" : "m6 4 4 4-4 4"} /></svg><span>活跃任务</span></button>{tasksKnown && <small>{activeQuests.length} 项已加载</small>}</div>
        <div id={taskRegionId} className="sidebar-task-items" hidden={!tasksExpanded}>
          {!connected ? <p className="sidebar-notice">连接后显示后台任务</p>
          : !ready ? <p className="sidebar-notice">正在同步任务…</p>
          : questError ? <p className="sidebar-notice">任务列表暂不可用</p>
          : activeQuests.length === 0 ? <p className="sidebar-notice">暂无活跃任务。在对话中描述你的目标。</p>
          : activeQuests.slice(0, 4).map((quest) => <button
            type="button" key={quest.id}
            title={quest.title}
            className={`sidebar-quest${!chatActive && selectedId === quest.id ? " selected" : ""}${needsQuestAttention(quest.status) ? " is-attention" : ""}`}
            aria-current={!chatActive && selectedId === quest.id ? "page" : undefined}
            onClick={() => onQuest(quest.id)}
          ><span>{quest.title}</span><small className="state-label sidebar-quest-status"><span className="sidebar-status-dot" data-status={quest.status} aria-hidden="true" /><span>{statusLabel(quest.status)}</span></small></button>)}
          <button type="button" className="text-button sidebar-action" disabled={!connected} onClick={onTasks}>查看全部任务</button>
        </div>
      </section>
    </div>
    <div className="sidebar-connection">{children}</div>
  </div>;
}

