export default function SettingsView({ selected, onSelect, onClose, children }: { selected: SettingId; onSelect: (id: SettingId) => void; onClose: () => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const searchInput = useRef<HTMLInputElement>(null);
  const itemButtons = useRef<Partial<Record<SettingId, HTMLButtonElement | null>>>({});
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.description} ${item.accessibleLabel || ""} ${item.keywords || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const visibleItems = groups.flatMap((group) => group.items);
  const current = settingMetadata[selected];
  const clearSearch = () => { setQuery(""); searchInput.current?.focus(); };
  const activate = (item: SettingItem) => { onSelect(item.id); itemButtons.current[item.id]?.focus(); };
  const navigate = (event: KeyboardEvent<HTMLButtonElement>, id: SettingId) => {
    if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229 || event.altKey || event.ctrlKey || event.metaKey) return;
    const index = visibleItems.findIndex((item) => item.id === id);
    const next = event.key === "ArrowDown" ? (index + 1) % visibleItems.length
      : event.key === "ArrowUp" ? (index - 1 + visibleItems.length) % visibleItems.length
      : event.key === "Home" ? 0 : event.key === "End" ? visibleItems.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    activate(visibleItems[next]);
  };
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-nav-header"><button type="button" className="settings-back" aria-label="返回对话" title="返回对话" onClick={onClose}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m10 5-7 7 7 7M3 12h18" /></svg></button><h1 className="settings-page-title">设置</h1></div><div className="settings-search"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg><input ref={searchInput} type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
        if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229) return;
        if (event.key === "Escape") { event.preventDefault(); clearSearch(); }
        else if (event.key === "Enter" && visibleItems.length) { event.preventDefault(); activate(visibleItems[0]); }
      }} />{query && <button type="button" className="settings-search-clear" aria-label="清除设置搜索" title="清除设置搜索" onClick={clearSearch}><svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><path d="m4 4 8 8m0-8-8 8" /></svg></button>}</div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} ref={(button) => { itemButtons.current[item.id] = button; }} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onKeyDown={(event) => navigate(event, item.id)} onClick={() => onSelect(item.id)}><SettingsIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <div className="settings-search-empty"><p className="notice">未找到匹配的设置</p><button type="button" className="text-button" onClick={clearSearch}>显示全部设置</button></div>}
    </nav>
    <div className="settings-content"><div className="settings-content-inner"><h1 className="settings-title">{current.label}</h1><p className="sr-only">{current.description}</p>{children}</div></div>
  </section>;
}

import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, summaryTitle, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; summaryTitle?: string; children: ReactNode; onInspect: () => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const [present, setPresent] = useState(false);
  const desired = useRef(false);
  const panel = useRef<HTMLDivElement>(null);

  // Depend only on user expansion. Polling must not restart animations or move scroll positions.
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !expanded);
    const finish = () => {
      element.style.height = desired.current ? "auto" : "0px";
      element.style.opacity = desired.current ? "1" : "0";
      if (!desired.current) setPresent(false);
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    const height = element.getBoundingClientRect().height;
    const opacity = getComputedStyle(element).opacity;
    element.style.height = `${height}px`;
    element.style.opacity = opacity;
    // Establish the current rendered height before transitioning to the measured target.
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = expanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = expanded ? "1" : "0";
      const seconds = Number.parseFloat(getComputedStyle(element).getPropertyValue("--transition-duration-basic")) || .15;
      timeout = window.setTimeout(finish, seconds * 1000 + 50);
    });
    const transitioned = (event: TransitionEvent) => {
      if (event.target === element && event.propertyName === "height") finish();
    };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [expanded]);

  return <details className={className} open={present}>
    <summary aria-label={summaryLabel} aria-expanded={expanded} title={summaryTitle || undefined} onClick={(event) => {
      event.preventDefault();
      onInspect();
      desired.current = !desired.current;
      setPresent(true);
      setExpanded(desired.current);
    }}>{summary}</summary>
    <div ref={panel} className="detail-collapsible">{children}</div>
  </details>;
}

