/* FORGE semantic extensions: statuses and surfaces outside the captured subset.
   Static system fonts approximate captured 430 / 510 weights with 400 / 500. */
:root {
  --color-text-secondary: rgba(13, 13, 13, .72);
  --color-background-nav-active: rgba(13, 13, 13, .055);
  --color-background-control-subtle: rgba(13, 13, 13, .03);
  --color-border-strong: rgba(13, 13, 13, .118);
  --color-background-command: rgba(13, 13, 13, .055);
  --color-status-error: #a24740;
  --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1;
  --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13, 13, 13, .18);
  --color-empty-symbol: rgba(13, 13, 13, .3);
  --color-shadow-soft: rgba(0, 0, 0, .04);
  --color-mask-solid: #000000;
  --color-shell-background: #f1f4f6;
  --color-sidebar-surface: #f8fafb;
  --muted: var(--app-color-text-foreground-tertiary);
  --line: var(--color-border);
  --accent: var(--color-accent);
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252, 252, 252, .72);
  --color-background-nav-active: rgba(252, 252, 252, .078);
  --color-background-control-subtle: rgba(252, 252, 252, .04);
  --color-border-strong: rgba(252, 252, 252, .14);
  --color-background-command: rgba(252, 252, 252, .055);
  --color-status-error: #ff9c94;
  --color-status-warning: #e0b471;
  --color-background-warning: #2a241b;
  --color-border-warning: #66523c;
  --color-scrollbar: rgba(252, 252, 252, .22);
  --color-empty-symbol: rgba(252, 252, 252, .3);
  --color-shell-background: #161819;
  --color-sidebar-surface: #191b1c;
}

/* The reference uses a 52px icon rail and a 288px conversation panel.
   Static system fonts approximate the captured 430 / 510 axes with 400 / 500. */
:root {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", var(--font-sans), Inter, sans-serif;
  font-size: 14px; font-weight: 400; color: var(--color-text);
  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
button, input, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .4; }
button, a, summary, input, textarea, select {
  transition: color var(--transition-duration-basic) var(--ease-out), background-color var(--transition-duration-basic) var(--ease-out), border-color var(--transition-duration-basic) var(--ease-out);
}
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.app-shell { display: grid; grid-template-columns: var(--sidebar-width) minmax(0,1fr); grid-template-rows: 44px minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--color-shell-background); transition: grid-template-columns var(--transition-duration-basic) var(--ease-out); }

/* Keep window chrome quiet; surface only the current workspace destination. */
.desktop-chrome { grid-column: 1 / -1; height: 44px; display: flex; align-items: center; justify-content: space-between; padding: 0 16px 0 0; }
.desktop-location { display: flex; align-items: center; gap: 10px; min-width: 0; padding-left: 12px; color: var(--muted); font-size: 12px; line-height: 18px; }
.desktop-location strong { color: var(--color-text-secondary); font-size: 12px; font-weight: 500; letter-spacing: .04em; }
.desktop-location > span:last-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.connection-indicator { font-size: 11px; line-height: 16px; color: var(--muted); white-space: nowrap; }
.status-dot { display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--muted); }
.status-dot.on { background: var(--color-accent); }

/* White, two-part sidebar. Navigation and the conversation list are distinct. */
.rail { display: grid; grid-template-columns: 52px 288px; min-width: 0; min-height: 0; background: var(--color-sidebar-surface); }
.primary-rail { display: flex; flex-direction: column; align-items: center; padding: 8px 8px 12px; min-height: 0; }
.primary-nav { display: flex; flex-direction: column; gap: 8px; }
