.nav-item.active { color: var(--color-text); background: var(--color-background-nav-active); }
.nav-item:hover, .profile-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.nav-icon { width: 20px; height: 20px; flex: none; }
.profile-button { margin-top: auto; }
.sidebar-panel { min-width: 0; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--color-border-subtle); }
/* Settings replaces the conversation list, while the primary icon rail stays available. */
.app-shell.settings-open, .app-shell.tasks-open, .app-shell.sidebar-collapsed { grid-template-columns: 52px minmax(0,1fr); }
.settings-open .rail, .tasks-open .rail, .sidebar-collapsed .rail { grid-template-columns: 52px; }
.settings-open .sidebar-panel, .tasks-open .sidebar-panel, .sidebar-collapsed .sidebar-panel { display: none; }
.sidebar-heading { height: 56px; flex: none; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 2px; padding: 0 16px; }
