.sidebar-section-title small { margin-left: 8px; font-size: 10px; line-height: 16px; white-space: nowrap; }
.thread-row { display: flex; align-items: center; gap: 10px; width: calc(100% - 16px); min-height: 60px; margin: 8px 8px 0; border: 0; border-radius: 12.5px; background: transparent; padding: 10px; text-align: left; }
.thread-row strong, .thread-row small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.thread-row strong { font-size: 14px; line-height: 22px; font-weight: var(--font-weight-strong); }
