/* Settings groups reflect the workspace, its model runtime, and its data. */
.settings-view { display: grid; grid-template-columns: 288px minmax(0,1fr); min-height: 0; min-width: 0; margin: 0 4px 4px 0; background: transparent; }
.settings-nav { display: flex; flex-direction: column; gap: 20px; min-height: 0; width: 288px; padding: 12px 12px 16px; overflow: auto; background: var(--color-sidebar-surface); }
.settings-page-title { flex: none; margin: 0; padding-left: 8px; font-size: 20px; line-height: 26px; font-weight: 600; }
.settings-search { display: flex; align-items: center; gap: 8px; height: 36px; flex: none; margin-top: -8px; padding: 6px 12px; border: 1px solid transparent; border-radius: 18px; background: var(--color-background-nav-active); color: var(--muted); }
.settings-search svg { flex: none; width: 16px; height: 16px; }
