.settings-nav-group { margin: 0; padding: 8px 10px 6px; font-size: 13px; line-height: 20px; font-weight: 500; color: var(--muted); }
.settings-nav-item { display: flex; align-items: center; gap: 10px; width: 100%; height: 36px; padding: 8px 10px; border: 0; border-radius: 12.5px; background: none; text-align: start; font-size: 14px; line-height: 20px; }
.settings-nav-item:hover { background: var(--color-background-secondary-ghost-hover); }
.settings-nav-item.active { background: var(--color-background-nav-active); }
.settings-content { min-width: 0; min-height: 0; padding: 32px; overflow: auto; border-left: 1px solid var(--color-border); border-radius: 16px 0 0 0; background: var(--app-color-background-surface); }
.settings-content-inner { position: relative; width: 100%; max-width: 760px; margin-inline: auto; }
.settings-title { margin: 0 40px 10px 0; font-size: 28px; line-height: 36px; font-weight: 600; }
.settings-description { max-width: 620px; margin: 0 0 28px; color: var(--muted); font-size: 13px; line-height: 20px; }
.settings-group, .settings-section { border: .8px solid var(--color-border-strong); border-radius: 12.5px; overflow: hidden; }
