.budget-unsettled-record { padding-inline: 16px; }
.budget-unsettled-record dl { grid-template-columns: 96px minmax(0,1fr); margin-bottom: 0; }
.settings-row { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding: 16px 20px; border-bottom: 1px solid var(--color-border-subtle); min-height: 64px; }
