.settings-row-control { display: inline-flex; align-items: center; gap: 6px; flex: none; max-width: 60%; min-width: 0; padding: 4px 12px; border: 1px solid var(--color-border); border-radius: 8px; background: var(--color-background-control-subtle); font-size: 13px; line-height: 18px; overflow-wrap: anywhere; }
