function CommandCard({ detail, onInspect }: { detail: Row; onInspect: () => void }) {
  const [copyStatus, setCopyStatus] = useState("");
  const command = text(detail.command, "");
  // The current Core normally returns a receipt digest, not stdout. Never infer output from it.
  const output = [detail.stdout, detail.output, detail.stderr].filter((value): value is string => typeof value === "string").join("\n");
  const copy = async () => {
    onInspect();
    try { await navigator.clipboard.writeText(command); setCopyStatus("已复制"); }
    catch { setCopyStatus("无法复制，请手动选择代码。"); }
  };
  return <div className="command-card"><header>{toolLabel(detail.tool, "命令")}</header>
    <div className="command-line"><div className="cmd">{command}</div><button type="button" className="copy-btn" aria-label="复制" onClick={() => void copy()}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.5" /><path d="M10.5 5.5v-2a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2" /></svg></button></div>
    {output ? <div className="out vertical-scroll-fade-mask"><code>{output}</code></div> : <p className="command-no-output">暂无输出</p>}
    {copyStatus && <span className="copy-status" role="status">{copyStatus}</span>}
  </div>;
}

function EventLine({ event, quests, runs, onQuest, onInspect }: { event: TimelineEvent; quests: Quest[]; runs: WorkerRun[]; onQuest: (id: string) => void; onInspect: () => void }) {
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const relatedQuest = quests.find((quest) => quest.id === event.quest_id);
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  const record = <>
    {workerIdentity(event, runs) && <p className="event-origin" title={workerIdentity(event, runs)}>{workerIdentity(event, runs)}</p>}
    <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>
    {event.quest_id && <button className="text-button" aria-label="查看关联任务" onClick={() => onQuest(event.quest_id!)}>查看关联任务{relatedQuest ? ` · ${relatedQuest.title}` : ""}</button>}
    <dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数", status: "状态", risk: "风险" } as Record<string, string>)[key] || key}</dt><dd>{key === "tool" ? toolLabel(value) : key === "status" ? statusLabel(value) : key === "risk" ? riskLabel(value) : text(value)}</dd></div>)}</dl>
    <small>记录 ID：{event.event_id}</small>
  </>;
  return <AnimatedDetails onInspect={onInspect} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`} summaryTitle={[workerIdentity(event, runs), target].filter(Boolean).join("\n")} summary={<><ActivityIcon event={event} /><span className="event-label">{target || eventTitle(event)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></>}>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} onInspect={onInspect} />}
      {["file_write", "file_revise"].includes(text(detail.tool, "")) && typeof detail.path === "string" && <div className="resource-card"><span className="resource-icon" aria-hidden="true"><ActivityIcon event={event} /></span><span><strong>{detail.path}</strong><small>{eventTitle(event)}</small></span></div>}
      {typeof detail.command === "string"
        ? <AnimatedDetails className="event-record" onInspect={onInspect} summary={<><span>记录详情</span><Chevron /></>}><div className="event-record-content">{record}</div></AnimatedDetails>
        : record}
    </div></AnimatedDetails>;
}

function EventGroup({ item, quests, runs, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; onQuest: (id: string) => void; onInspect: () => void }) {
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  return <AnimatedDetails className="event-group" onInspect={onInspect} summaryTitle={origins.join("\n")} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon event={item.events[0]} /><span className="event-label">{summary}</span><Chevron /></>}>
    <div className="event-detail">{item.events.map((event) => <EventLine key={`${event.kind}:${event.event_id}`} event={event} quests={quests} runs={runs} onQuest={onQuest} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
