  <button type="button"
          class="absolute inset-0 cursor-interaction rounded-md bg-transparent focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0 focus-visible:outline-none focus-visible:ring-inset"
          aria-expanded="false"></button>

  <span class="inline-flex min-w-0 gap-2 items-center shrink truncate text-size-chat pointer-events-none relative">
    <span class="text-tertiary flex min-w-0 max-w-full items-center truncate shrink group-hover/activity-header:text-default">
      <span class="flex min-h-4 max-w-full min-w-0 items-center truncate">
        <span class="inline-flex min-w-0 gap-2 items-center max-w-full overflow-hidden">
          <span class="contents text-tertiary"><!-- 16×16 svg --></span>
          <span class="min-w-0 flex-1 truncate">
            <span class="block min-w-0 max-w-full flex-1 truncate summary-fnAD_7 group-hover/activity-header:[--agent-activity-summary-color:var(--color-text)]">
              <span class="block max-w-full min-w-0 truncate">已读取文件运行了命令</span>
            </span>
          </span>
        </span>
