/* ============================================================
   ChatGPT Desktop design tokens — computed values from the live
   Electron renderer (Tailwind v4.3.3 build, appearance preset "codex").

   Drop this at the TOP of desktop/src/style.css.
   Light is the default; dark overrides live on [data-theme="dark"].

   Radii: xs 5 / sm 7.5 / md 10 / lg 12.5 / xl 15 / 2xl 20 (px)
   Weights 430 / 510 are variable-font mid weights; fall back to
   400 / 500 if the chosen font has no variable axis.
   ============================================================ */

:root {
  --app-color-background-surface: #ffffff;
  --app-color-background-surface-under: #f5f5f5;
  --app-color-background-elevated-primary: rgba(255, 255, 255, 0.96);
  --app-color-background-control: rgba(255, 255, 255, 0.96);
  --color-text: #0d0d0d;
  --app-color-text-foreground: #0d0d0d;
  --app-color-text-foreground-tertiary: rgba(13, 13, 13, 0.495);
  --color-border: rgba(13, 13, 13, 0.078);
  --color-border-subtle: rgba(13, 13, 13, 0.049);
  --app-color-border: rgba(13, 13, 13, 0.078);
  --app-color-border-light: rgba(13, 13, 13, 0.049);
  --color-background-user-message: rgba(13, 13, 13, 0.05);
  --color-text-user-message: #0d0d0d;
  --color-background-secondary-ghost-hover: rgba(13, 13, 13, 0.053);
  --app-color-background-button-secondary-hover: rgba(13, 13, 13, 0.053);
  --color-accent: #0169cc;
  --chatgpt-blue-400: #3a83f7;
  --color-text-accent: #014f99;
  --radius-xs: 5px;
  --radius-sm: 7.5px;
  --radius-md: 10px;
  --radius-lg: 12.5px;
  --radius-xl: 15px;
  --radius-2xl: 20px;
  --shadow-sm: 0px 1px 2px -1px #00000014;
  --shadow-md: 0px 2px 4px -1px #00000014;
  --shadow-lg: 0px 4px 8px -2px #0000001a;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-sans-default: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "SF Mono", menlo, consolas, "Liberation Mono", monospace;
  --height-token-row: calc(14px * 1.5 + calc(.25rem * 1) * 2);
  --padding-row-x: calc(.25rem * 2);
  --color-background-accent-solid: #0169cc;
  --spacing: .25rem;
  --brand-red-400: #fa423e;
  --brand-orange-400: #ff8066;
  --brand-green-400: #04b84c;
  --brand-blue-400: #0285ff;
  --brand-yellow-400: #ffcc38;
  --brand-purple-400: #a25bff;
  --text-chat: 14px;
  --text-chat-line: 21px;
  --text-assistant: 16px;
  --text-assistant-line: 24px;
  --text-meta: 13px;
  --text-meta-line: 18px;
  --text-small: 12px;
  --text-small-line: 16px;
  --font-weight-body: 430;
  --font-weight-strong: 510;
  --thread-content-max-width: 736px;
  --sidebar-width: 340px;
  --topbar-height: 36px;
  --row-height: 30px;
  --transition-duration-basic: .15s;
  --transition-duration-moderate: .2s;
  --transition-duration-relaxed: .3s;
  --default-transition-duration: .15s;
  --default-transition-timing-function: cubic-bezier(.4, 0, .2, 1);
  --ease-basic: ease;
  --ease-out: cubic-bezier(0, 0, .2, 1);
  --ease-in: cubic-bezier(.4, 0, 1, 1);
  --ease-in-out: cubic-bezier(.4, 0, .2, 1);
  --ease-enter-snappy: cubic-bezier(.23, 1, .32, 1);
  --ease-spring-snappy: linear(0, .086, .2539, .428, .5786, .698, .7879, .8534, .8998, .9323, .9546, .9697, .98, .9868, .9913, .9943, .9963, .9976, .9985, 1);
  --settings-nav-width: 288px;
  --settings-item-height: 30px;
  --settings-item-radius: 12.5px;
  --settings-row-padding: 12px 16px;
  --settings-content-max: 760px;

  color-scheme: light;
}

[data-theme="dark"] {
  --app-color-background-surface: #111111;
  --app-color-background-surface-under: #0e0e0e;
  --app-color-background-elevated-primary: rgba(47, 47, 47, 0.96);
  --app-color-background-control: rgba(38, 38, 38, 0.96);
  --color-text: #fcfcfc;
  --app-color-text-foreground: #fcfcfc;
  --app-color-text-foreground-tertiary: rgba(252, 252, 252, 0.498);
  --color-border: rgba(252, 252, 252, 0.084);
  --color-border-subtle: rgba(252, 252, 252, 0.042);
  --app-color-border: rgba(252, 252, 252, 0.084);
  --app-color-border-light: rgba(252, 252, 252, 0.042);
  --color-background-user-message: rgba(252, 252, 252, 0.05);
  --color-text-user-message: #fcfcfc;
  --color-background-secondary-ghost-hover: rgba(252, 252, 252, 0.078);
  --app-color-background-button-secondary-hover: rgba(252, 252, 252, 0.078);
  --color-text-accent: #a6cbed;

  color-scheme: dark;
}

/* FORGE semantic extensions: statuses and surfaces outside the captured subset.
   Static system fonts approximate captured 430 / 510 weights with 400 / 500. */
:root {
  --color-text-secondary: rgba(13, 13, 13, .72);
  --color-background-nav-active: rgba(13, 13, 13, .055);
  --color-background-control-subtle: rgba(13, 13, 13, .03);
  --color-border-strong: rgba(13, 13, 13, .118);
  --color-background-command: rgba(13, 13, 13, .055);
  --color-status-error: #a24740;
  --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1;
  --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13, 13, 13, .18);
  --color-empty-symbol: rgba(13, 13, 13, .3);
  --color-shadow-soft: rgba(0, 0, 0, .04);
  --color-mask-solid: #000000;
  --color-shell-background: var(--app-color-background-surface-under);
  --color-sidebar-surface: rgba(255, 255, 255, .65);
  --sidebar-width: 272px;
  --font-weight-body: 400;
  --font-weight-strong: 500;
  --muted: var(--app-color-text-foreground-tertiary);
  --line: var(--color-border);
  --accent: var(--color-accent);
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252, 252, 252, .72);
  --color-background-nav-active: rgba(252, 252, 252, .078);
  --color-background-control-subtle: rgba(252, 252, 252, .04);
  --color-border-strong: rgba(252, 252, 252, .14);
  --color-background-command: rgba(252, 252, 252, .055);
  --color-status-error: #ff9c94;
  --color-status-warning: #e0b471;
  --color-background-warning: #2a241b;
  --color-border-warning: #66523c;
  --color-scrollbar: rgba(252, 252, 252, .22);
  --color-empty-symbol: rgba(252, 252, 252, .3);
  --color-shell-background: var(--app-color-background-surface-under);
  --color-sidebar-surface: rgba(17, 17, 17, .65);
}

/* FORGE keeps one navigation entry per feature inside a 272px workspace rail. */
:root {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", var(--font-sans), Inter, sans-serif;
  font-size: 14px; font-weight: 400; color: var(--color-text);
  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
button, input, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .4; }
button, a, summary, input, textarea, select {
  transition: color var(--transition-duration-basic) var(--ease-out), background-color var(--transition-duration-basic) var(--ease-out), border-color var(--transition-duration-basic) var(--ease-out);
}
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.app-shell { display: grid; grid-template-columns: var(--sidebar-width) minmax(0,1fr); grid-template-rows: var(--topbar-height) minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--color-shell-background); transition: grid-template-columns var(--transition-duration-basic) var(--ease-out); }

/* Keep window chrome quiet; surface only the current workspace destination. */
.desktop-chrome { grid-column: 1 / -1; height: var(--topbar-height); display: flex; align-items: center; justify-content: space-between; padding: 0 16px 0 0; }
.desktop-location { display: flex; align-items: center; gap: 10px; min-width: 0; padding-left: 12px; color: var(--muted); font-size: 12px; line-height: 18px; }
.desktop-location strong { color: var(--color-text-secondary); font-size: 12px; font-weight: 500; letter-spacing: .04em; }
.desktop-location > span:last-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.connection-indicator { font-size: 11px; line-height: 16px; color: var(--muted); white-space: nowrap; }
.status-dot { display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--muted); }
.status-dot.on { background: var(--color-accent); }

/* The same navigation DOM becomes a 52px icon rail in settings or when collapsed. */
.rail { display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0 4px 4px 4px; border-radius: 12px; background: var(--color-sidebar-surface); }
.primary-nav { display: flex; flex-direction: column; gap: 2px; padding: 0 8px; }
.nav-item { display: flex; align-items: center; gap: 10px; width: 100%; height: 30px; padding: 5px 8px; border: 0; border-radius: 10px; background: transparent; color: var(--color-text-secondary); text-align: left; font-size: 13px; line-height: 20px; }
.nav-item.active { color: var(--color-text); background: var(--color-background-nav-active); }
.nav-item:hover, .profile-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.nav-icon { width: 20px; height: 20px; flex: none; }
.profile-button { display: flex; align-items: center; gap: 10px; flex: none; width: calc(100% - 16px); height: 40px; margin: 8px; padding: 6px 8px; border: 0; border-radius: 10px; background: transparent; color: var(--color-text-secondary); font-size: 13px; text-align: left; }
.profile-avatar { display: grid; place-items: center; width: 28px; height: 28px; flex: none; border-radius: 50%; background: var(--color-background-secondary-ghost-hover); color: var(--color-text); font-size: 13px; font-weight: 500; }
.profile-shortcut { margin-left: auto; color: var(--muted); font-size: 11px; }
.sidebar-panel { min-width: 0; min-height: 0; flex: 1; display: flex; flex-direction: column; }
/* Settings replaces the conversation list, while the primary icon rail stays available. */
.app-shell.settings-open, .app-shell.tasks-open, .app-shell.sidebar-collapsed { grid-template-columns: 52px minmax(0,1fr); }
.settings-open .rail, .tasks-open .rail, .sidebar-collapsed .rail { margin-inline: 0; background: transparent; }
.settings-open .sidebar-panel, .tasks-open .sidebar-panel, .sidebar-collapsed .sidebar-panel { display: contents; }
.settings-open .workspace-selector-wrap, .tasks-open .workspace-selector-wrap, .sidebar-collapsed .workspace-selector-wrap,
.settings-open .sidebar-connection, .tasks-open .sidebar-connection, .sidebar-collapsed .sidebar-connection { display: none; }
.settings-open .primary-nav, .tasks-open .primary-nav, .sidebar-collapsed .primary-nav { align-items: center; gap: 8px; padding: 8px; }
.settings-open .nav-item, .tasks-open .nav-item, .sidebar-collapsed .nav-item { justify-content: center; width: 36px; height: 36px; padding: 8px; }
.settings-open .nav-label, .tasks-open .nav-label, .sidebar-collapsed .nav-label,
.settings-open .profile-label, .tasks-open .profile-label, .sidebar-collapsed .profile-label,
.settings-open .profile-shortcut, .tasks-open .profile-shortcut, .sidebar-collapsed .profile-shortcut { display: none; }
.settings-open .profile-button, .tasks-open .profile-button, .sidebar-collapsed .profile-button { width: 36px; height: 36px; padding: 4px; }
.sidebar-scroll { min-height: 0; flex: 1; overflow: auto; padding-bottom: 16px; }
.workspace-selector-wrap { position: relative; flex: none; padding: 12px 8px 10px; }
.workspace-selector { display: flex; align-items: center; gap: 10px; width: 100%; height: 36px; padding: 6px 8px; border: 0; border-radius: 10px; background: transparent; text-align: left; }
.workspace-selector:hover, .workspace-selector.is-open { background: var(--color-background-secondary-ghost-hover); }
.workspace-selector > svg { flex: none; }
.workspace-selector-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 15px; line-height: 20px; font-weight: 500; }
.workspace-selector-chevron { margin-left: auto; color: var(--muted); transition: transform .15s var(--ease-out); }
.workspace-selector.is-open .workspace-selector-chevron { transform: rotate(180deg); }
.workspace-menu { position: absolute; z-index: 30; top: calc(100% - 6px); left: 8px; width: max(100% - 16px, 260px); max-width: calc(100vw - 32px); padding: 6px; border: .8px solid var(--color-border-strong); border-radius: 12.5px; background: var(--app-color-background-elevated-primary); box-shadow: var(--shadow-lg); animation: menu-enter .15s var(--ease-out); }
.workspace-menu-label { margin: 4px 8px 6px; color: var(--muted); font-size: 12px; line-height: 16px; }
.workspace-menu-current { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 0; border-radius: 7.5px; background: transparent; text-align: left; }
.workspace-menu-current:hover { background: var(--color-background-secondary-ghost-hover); }
.workspace-menu-current > svg { flex: none; color: var(--muted); }
.workspace-menu-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.workspace-menu-copy strong { font-size: 13px; line-height: 20px; font-weight: 500; }
.workspace-menu-path { overflow-wrap: anywhere; color: var(--muted); font-size: 12px; line-height: 18px; }
.workspace-menu-empty { margin: 8px; color: var(--muted); font-size: 13px; line-height: 20px; }
@keyframes menu-enter { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
.sidebar-connection:empty { display: none; }
.connect-banner { padding: 12px 16px 20px; font-size: 12px; line-height: 18px; color: var(--muted); }
.connect-banner strong { color: var(--color-text); font-size: 12px; font-weight: 500; }
.connect-banner p { margin: 4px 0 8px; }
.connect-controls { display: flex; gap: 6px; }
.connect-controls input { width: 100%; min-width: 0; padding: 6px 8px; border: 1px solid var(--color-border); border-radius: 8px; background: var(--app-color-background-control); font-size: 12px; }

/* Keep long-lived conversation reading and input on the same centered column. */
.conversation-shell { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; margin: 0 4px 4px 0; background: var(--app-color-background-surface); }
.topbar { height: 52px; flex: none; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 6px 24px; border-bottom: 1px solid var(--color-border-subtle); }
.topbar-title h1 { margin: 0; font-size: 15px; line-height: 20px; font-weight: var(--font-weight-strong); }
.topbar-title small { display: block; margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.timeline { flex: 1; min-height: 0; overflow: auto; overflow-anchor: none; padding: 32px 24px 56px; }
.timeline > * { width: 100%; max-width: 736px; min-width: 0; margin-inline: auto; }
.home-state .timeline { display: grid; place-items: center; padding: 0 24px; }
.empty-conversation { display: flex; flex-direction: column; align-items: center; gap: 12px; width: 100%; transform: translateY(-24px); text-align: center; }
.empty-conversation h2 { margin: 0; font-size: 28px; line-height: 36px; font-weight: 500; color: var(--color-text); }
.empty-conversation p { max-width: 480px; margin: 0; color: var(--muted); font-size: 14px; line-height: 22px; }
.message { position: relative; display: flex; flex-direction: column; gap: 0; margin: 0 auto 32px; }
.message-body { min-width: 0; overflow-wrap: anywhere; white-space: pre-wrap; font-size: 16px; line-height: 24px; }
.message.from-user { align-items: flex-end; margin-bottom: 24px; }
.message.from-user .message-body { max-width: min(80%,560px); border-radius: 20px; padding: 10px 16px; background: var(--color-background-user-message); color: var(--color-text-user-message); font-size: 14px; line-height: 21px; }
.message.from-agent .message-body { padding: 0; border-radius: 0; background: none; }
.message-meta { position: absolute; bottom: -23px; inset-inline-start: 0; display: flex; align-items: center; gap: 8px; height: 20px; font-size: 12px; line-height: 16px; color: var(--muted); }
.message.from-user .message-meta { inset-inline-start: auto; inset-inline-end: 0; }
.message-meta strong { font-size: 12px; font-weight: 400; }
