/* ============================================================
   ChatGPT Desktop design tokens — computed values from the live
   Electron renderer (Tailwind v4.3.3 build, appearance preset "codex").

   Drop this at the TOP of desktop/src/style.css.
   Light is the default; dark overrides live on [data-theme="dark"].

   Radii: xs 5 / sm 7.5 / md 10 / lg 12.5 / xl 15 / 2xl 20 (px)
   Weights 430 / 510 are variable-font mid weights; fall back to
   400 / 500 if the chosen font has no variable axis.
   ============================================================ */

:root {
  --app-color-background-surface: #ffffff;
  --app-color-background-surface-under: #f5f5f5;
  --app-color-background-elevated-primary: rgba(255, 255, 255, 0.96);
  --app-color-background-control: rgba(255, 255, 255, 0.96);
  --color-text: #0d0d0d;
  --app-color-text-foreground: #0d0d0d;
  --app-color-text-foreground-tertiary: rgba(13, 13, 13, 0.495);
  --color-border: rgba(13, 13, 13, 0.078);
  --color-border-subtle: rgba(13, 13, 13, 0.049);
  --app-color-border: rgba(13, 13, 13, 0.078);
  --app-color-border-light: rgba(13, 13, 13, 0.049);
  --color-background-user-message: rgba(13, 13, 13, 0.05);
  --color-text-user-message: #0d0d0d;
  --color-background-secondary-ghost-hover: rgba(13, 13, 13, 0.053);
  --app-color-background-button-secondary-hover: rgba(13, 13, 13, 0.053);
  --color-accent: #0169cc;
  --chatgpt-blue-400: #3a83f7;
  --color-text-accent: #014f99;
  --radius-xs: 5px;
  --radius-sm: 7.5px;
  --radius-md: 10px;
  --radius-lg: 12.5px;
  --radius-xl: 15px;
  --radius-2xl: 20px;
  --shadow-sm: 0px 1px 2px -1px #00000014;
  --shadow-md: 0px 2px 4px -1px #00000014;
  --shadow-lg: 0px 4px 8px -2px #0000001a;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-sans-default: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "SF Mono", menlo, consolas, "Liberation Mono", monospace;
  --height-token-row: calc(14px * 1.5 + calc(.25rem * 1) * 2);
  --padding-row-x: calc(.25rem * 2);
  --color-background-accent-solid: #0169cc;
  --spacing: .25rem;
  --brand-red-400: #fa423e;
  --brand-orange-400: #ff8066;
  --brand-green-400: #04b84c;
  --brand-blue-400: #0285ff;
  --brand-yellow-400: #ffcc38;
  --brand-purple-400: #a25bff;
  --text-chat: 14px;
  --text-chat-line: 21px;
  --text-assistant: 16px;
  --text-assistant-line: 24px;
  --text-meta: 13px;
  --text-meta-line: 18px;
  --text-small: 12px;
  --text-small-line: 16px;
  --font-weight-body: 430;
  --font-weight-strong: 510;
  --thread-content-max-width: 736px;
  --sidebar-width: 340px;
  --topbar-height: 36px;
  --row-height: 30px;
  --transition-duration-basic: .15s;
  --transition-duration-moderate: .2s;
  --transition-duration-relaxed: .3s;
  --default-transition-duration: .15s;
  --default-transition-timing-function: cubic-bezier(.4, 0, .2, 1);
  --ease-basic: ease;
  --ease-out: cubic-bezier(0, 0, .2, 1);
  --ease-in: cubic-bezier(.4, 0, 1, 1);
  --ease-in-out: cubic-bezier(.4, 0, .2, 1);
  --ease-enter-snappy: cubic-bezier(.23, 1, .32, 1);
  --ease-spring-snappy: linear(0, .086, .2539, .428, .5786, .698, .7879, .8534, .8998, .9323, .9546, .9697, .98, .9868, .9913, .9943, .9963, .9976, .9985, 1);
  --settings-nav-width: 288px;
  --settings-item-height: 30px;
  --settings-item-radius: 12.5px;
  --settings-row-padding: 12px 16px;
  --settings-content-max: 760px;

  color-scheme: light;
}

[data-theme="dark"] {
  --app-color-background-surface: #111111;
  --app-color-background-surface-under: #0e0e0e;
  --app-color-background-elevated-primary: rgba(47, 47, 47, 0.96);
  --app-color-background-control: rgba(38, 38, 38, 0.96);
  --color-text: #fcfcfc;
  --app-color-text-foreground: #fcfcfc;
  --app-color-text-foreground-tertiary: rgba(252, 252, 252, 0.498);
  --color-border: rgba(252, 252, 252, 0.084);
  --color-border-subtle: rgba(252, 252, 252, 0.042);
  --app-color-border: rgba(252, 252, 252, 0.084);
  --app-color-border-light: rgba(252, 252, 252, 0.042);
  --color-background-user-message: rgba(252, 252, 252, 0.05);
  --color-text-user-message: #fcfcfc;
  --color-background-secondary-ghost-hover: rgba(252, 252, 252, 0.078);
  --app-color-background-button-secondary-hover: rgba(252, 252, 252, 0.078);
  --color-text-accent: #a6cbed;

  color-scheme: dark;
}


/* One desktop composition. System fonts approximate the captured 430/510 axes with 400/500. */
:root {
  --font-weight-body: 400; --font-weight-strong: 500;
  --color-text-secondary: rgba(13,13,13,.65);
  --color-border-strong: rgba(13,13,13,.118);
  --color-background-nav-active: rgba(13,13,13,.055);
  --color-background-control-subtle: rgba(13,13,13,.03);
  --color-background-command: rgba(13,13,13,.055);
  --color-sidebar-surface: rgba(255,255,255,.65);
  --color-shell-background: var(--app-color-background-surface-under);
  --color-status-error: #a24740; --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1; --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13,13,13,.18); --color-mask-solid: #000;
  --muted: var(--app-color-text-foreground-tertiary); --line: var(--color-border); --accent: var(--color-accent);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif;
  font-size: 14px; font-weight: 400; color: var(--color-text);
  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252,252,252,.65); --color-border-strong: rgba(252,252,252,.14);
  --color-background-nav-active: rgba(252,252,252,.078); --color-background-control-subtle: rgba(252,252,252,.04);
  --color-background-command: rgba(252,252,252,.055); --color-sidebar-surface: rgba(17,17,17,.65);
  --color-status-error: #ff9c94; --color-status-warning: #e0b471;
  --color-background-warning: #2a241b; --color-border-warning: #66523c; --color-scrollbar: rgba(252,252,252,.22);
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
button, input, textarea, select { font: inherit; color: inherit; }
button, summary { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .4; }
button, a, summary, input, textarea, select { transition: color .15s var(--ease-out), background-color .15s var(--ease-out), border-color .15s var(--ease-out); }
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* Window and navigation: 52px utility rail, 288px workspace panel. */
.app-shell { display: grid; grid-template-columns: 340px minmax(0,1fr); grid-template-rows: 36px minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--color-shell-background); transition: grid-template-columns .15s var(--ease-out); }
.app-shell.compact-navigation { grid-template-columns: 52px minmax(0,1fr); }
.desktop-chrome { display: flex; grid-column: 1 / -1; align-items: center; justify-content: space-between; height: 36px; padding: 0 16px 0 8px; }
.desktop-location { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 12px; line-height: 18px; }
.desktop-location strong { font-size: 12px; font-weight: 400; }
.sidebar-toggle { display: grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); }
.sidebar-toggle:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.connection-indicator { color: var(--muted); font-size: 11px; line-height: 16px; }
.status-dot { display: inline-block; width: 5px; height: 5px; margin-right: 6px; border-radius: 50%; background: currentColor; opacity: .7; }
.status-dot.on { background: var(--color-accent); opacity: 1; }
.rail { position: relative; display: flex; min-height: 0; min-width: 0; }
.primary-rail { display: flex; flex: 0 0 52px; flex-direction: column; align-items: center; min-height: 0; padding: 8px 8px 12px; gap: 8px; }
.rail-brand { display: grid; place-items: center; width: 36px; height: 36px; color: var(--color-text); }
.utility-nav { display: flex; flex-direction: column; gap: 8px; }
.nav-item { display: inline-flex; align-items: center; gap: 8px; padding: 0 8px; border: 0; border-radius: 10px; background: none; color: var(--color-text); text-align: start; font-size: 13px; line-height: 20px; }
.utility-nav-item { justify-content: center; width: 36px; height: 36px; padding: 8px; color: var(--muted); }
.nav-icon { flex: none; width: 20px; height: 20px; }
.nav-item:hover, .nav-item.active { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.nav-item.active { font-weight: 500; }
.profile-button { display: grid; place-items: center; flex: none; width: 36px; height: 36px; margin-top: auto; padding: 4px; border: 0; border-radius: 10px; background: none; }
.profile-button:hover { background: var(--color-background-secondary-ghost-hover); }
.profile-avatar { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--color-background-nav-active); color: var(--color-text-secondary); font-size: 12px; font-weight: 500; }
.sidebar-panel { display: flex; flex: 0 0 288px; flex-direction: column; min-width: 0; min-height: 0; margin-bottom: 4px; border-radius: 12px 0 0 12px; background: var(--color-sidebar-surface); }
