.composer-model { display: inline-flex; align-items: center; gap: 4px; max-width: min(300px,40vw); height: 28px; padding: 4px 6px; border: 0; border-radius: 7.5px; background: none; color: var(--color-text-secondary); font-size: 12px; line-height: 18px; }
.composer-model > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.composer-model svg { flex: none; }
.composer-model:hover, .composer-model[aria-expanded="true"] { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
