.resource-card { display: flex; align-items: center; gap: 12px; padding: 12px; min-width: 0; border: .8px solid var(--color-border-strong); border-radius: 12.5px; background: var(--app-color-background-surface-under); }
.resource-icon { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 12.5px; background: var(--color-background-secondary-ghost-hover); }
.resource-icon svg { width: 24px; height: 24px; }
.resource-card strong { display: block; font-size: 14px; line-height: 21px; color: var(--color-text); overflow-wrap: anywhere; }
.resource-card small { font-size: 13px; line-height: 18px; }
.timeline-updates { margin: 24px auto 0; }
.timeline-updates-label { margin-bottom: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.timeline-update { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; margin: 8px 0; padding: 10px 12px; border: .8px solid var(--color-border); border-radius: 12.5px; background: var(--app-color-background-surface); text-align: left; }
.timeline-update:hover { background: var(--color-background-secondary-ghost-hover); }
.timeline-update strong, .timeline-update small { display: block; overflow-wrap: anywhere; }
.timeline-update strong { font-size: 13px; line-height: 18px; font-weight: 500; }
.timeline-update small { margin-top: 4px; color: var(--muted); font-size: 12px; line-height: 16px; }
.timeline-update:not(.approval-card) { padding-inline: 4px; border: 0; border-bottom: 1px solid var(--color-border-subtle); border-radius: 0; }
.approval-card { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 10px 16px; padding: 16px; }
.approval-summary { grid-column: 1 / -1; display: flex; justify-content: space-between; gap: 12px; padding: 0; border: 0; background: none; text-align: left; }
