.approval-scope { grid-column: 1 / -1; display: flex; align-items: baseline; justify-content: space-between; gap: 16px; color: var(--color-text-secondary); font-size: 13px; line-height: 20px; }
.approval-scope > span { min-width: 0; overflow-wrap: anywhere; }
