/* Settings replaces the workspace panel, with the native grouped navigation. */
.settings-view { display: grid; grid-template-columns: 288px minmax(0,1fr); min-width: 0; min-height: 0; margin: 0 4px 4px 0; }
.settings-nav { display: flex; flex-direction: column; gap: 16px; min-height: 0; width: 288px; padding: 12px 8px 16px; overflow: auto; border-radius: 12px 0 0 12px; background: var(--color-sidebar-surface); }
.settings-nav-header { display: flex; align-items: center; justify-content: space-between; flex: none; height: 26px; padding-inline: 8px; }
.settings-page-title { margin: 0; font-size: 20px; line-height: 26px; font-weight: 500; }
.settings-back { display: grid; place-items: center; width: 28px; height: 28px; padding: 6px; border: 0; border-radius: 7.5px; background: none; color: var(--muted); }
.settings-back:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
