.command-card .cmd { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; padding: 8px 32px 0 8px; white-space: pre-wrap; word-break: break-word; color: var(--color-text-secondary); font: 400 13px/20px var(--font-mono); }
.command-card .cmd::before { content: "$"; margin-inline-end: 1ch; color: var(--muted); }
.command-card .out { display: flex; flex-direction: column-reverse; max-height: 144px; min-width: 0; overflow: auto; padding: 8px; white-space: pre; color: var(--color-text-secondary); font: 500 13px/20px var(--font-mono); --top-fade: 0px; --bottom-fade: 0px; mask-image: linear-gradient(to bottom, transparent 0, var(--color-mask-solid) var(--top-fade), var(--color-mask-solid) calc(100% - var(--bottom-fade)), transparent 100%); }
.command-card .out[data-can-scroll-up="true"] { --top-fade: 2rem; }
