.command-card .out code { font: inherit; color: inherit; }
.command-card .copy-btn { position: absolute; top: 4px; right: 4px; display: grid; place-items: center; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); opacity: 0; transition: opacity .15s var(--ease-out); }
.command-card .copy-btn:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.command-card:hover .copy-btn, .command-card:focus-within .copy-btn { opacity: 1; }
.command-card > .copy-status { padding: 0 8px 4px; }
.command-no-output { margin: 0; padding: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
