  return <div className={`app-shell${compactNavigation ? " compact-navigation" : ""}${view === "chat" && !settingsOpen ? " chat-open" : ""}${settingsOpen ? " settings-open" : ""}${taskView && !settingsOpen ? " tasks-open" : ""}${sidebarCollapsed ? " sidebar-collapsed" : ""}`}>
