import { capabilityLabel } from "./presentation";

type Row = Record<string, unknown>;
const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const object = (value: unknown): Row => value && typeof value === "object" && !Array.isArray(value) ? value as Row : {};

function support(value: unknown): string {
  const entry = object(value);
  const label = entry.supported === true ? "支持" : entry.supported === false ? "不支持" : "未知";
  return entry.source ? `${label} · ${text(entry.source)}` : label;
}

function price(value: unknown, currency: unknown): string {
  return typeof value === "number" && Number.isFinite(value) ? `${value.toLocaleString()} ${text(currency, "币种未知")} / 百万 Token` : "未知";
}

function MeasurementList({ value, performance = false }: { value: unknown; performance?: boolean }) {
  const entries = Object.entries(object(value));
  if (!entries.length) return <p className="notice">{performance ? "性能测量：未知" : "能力评分：未知"}</p>;
  const performanceNames: Record<string, string> = { tokens_per_second: "输出速度（Token/s）", ttft_seconds: "首 Token 时间（秒）", latency_p50_seconds: "P50 延迟（秒）", latency_p95_seconds: "P95 延迟（秒）", reliability: "可靠率", timeout_rate: "超时率" };
  return <div className="measurement-list">{entries.map(([name, value]) => {
    const entry = object(value);
    return <div key={name}><span>{performance ? performanceNames[name] || name : capabilityLabel(name)}</span><span>{text(entry.value)} · {text(entry.source)} · {entry.n_samples == null ? entry.source === "user_override" ? "未采样（0）" : "样本未知" : `样本 ${text(entry.n_samples)}`} · 置信度 {text(entry.confidence)}<br />观测时间：{text(entry.observed_at)}{entry.benchmark_version != null && <> · 基准 {text(entry.benchmark_version)}</>}</span></div>;
  })}</div>;
}

export default function ModelProfileSummary({ model }: { model: Row }) {
  return <>
    <strong>{text(model.display_name, text(model.model_id ?? model.id))}</strong>
    <small>{text(model.provider ?? model.provider_id)} / {text(model.model_id)} · {model.enabled === true ? "已启用" : model.enabled === false ? "已禁用" : "状态未知"}</small>
    <dl><dt>档案 ID</dt><dd className="break">{text(model.id)}</dd>
      <dt>上下文窗口</dt><dd>{text(model.context_window)}</dd><dt>最大输出</dt><dd>{text(model.max_output_tokens)}</dd>
      <dt>工具调用</dt><dd>{support(model.tool_calling_support)}</dd><dt>结构化输出</dt><dd>{support(model.structured_output_support)}</dd>
      <dt>输入价格</dt><dd>{price(model.input_cost_per_million, model.currency)}</dd><dt>输出价格</dt><dd>{price(model.output_cost_per_million, model.currency)}</dd>
      <dt>能力来源</dt><dd>{text(object(model.provenance).source)}</dd>
      <dt>可用能力</dt><dd>{Object.keys(object(model.capabilities)).map((name) => capabilityLabel(name)).join("、") || "未知"}</dd>
    </dl>
    <MeasurementList value={model.capability_measurements} />
    <details><summary>性能与缓存价格</summary><dl>
      <dt>缓存输入</dt><dd>{price(model.cached_input_cost_per_million, model.currency)}</dd>
      <dt>输出速度</dt><dd>{text(model.tokens_per_second)} Token/s</dd><dt>首 Token</dt><dd>{text(model.ttft_seconds)} 秒</dd>
      <dt>健康状态</dt><dd>{text(model.health)}</dd>
    </dl><MeasurementList value={model.performance_measurements} performance /></details>
  </>;
}

import { SettingsRow } from "./SettingsView";

type BudgetRecord = Record<string, unknown>;

const finiteNonnegative = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value) && value >= 0;
const budgetText = (value: unknown) => typeof value === "string" && value.trim() ? value : "未知";

export function formatBudgetNumber(value: unknown): string {
  return finiteNonnegative(value) ? value.toLocaleString("zh-CN", { maximumFractionDigits: 6 }) : "未知";
}

export function formatBudgetCost(microunits: unknown, currency: unknown): string {
  const denomination = budgetText(currency);
  if (!finiteNonnegative(microunits)) return denomination === "未知" ? "未知" : `未知（${denomination}）`;
  const amount = (microunits / 1_000_000).toLocaleString("zh-CN", { maximumFractionDigits: 6 });
  return denomination === "未知" ? `${amount}（币种未知）` : `${amount} ${denomination}`;
}

export function formatBudgetRecoveryTime(value: unknown): string {
  if (typeof value !== "number" || !Number.isFinite(value)) return "未知";
  const date = new Date(value * 1000);
  return Number.isFinite(date.getTime()) ? date.toLocaleString() : "未知";
}

export default function BudgetOverview({ budget }: { budget: BudgetRecord }) {
  const unsettled = Array.isArray(budget.recent_unsettled) ? budget.recent_unsettled : null;

  return <>
    <section className="settings-section">
      <h2 className="settings-section-title">Token 账本</h2>
      <SettingsRow label="已确认用量" description="已经记录的确认 Token 用量。">{formatBudgetNumber(budget.known_tokens)}</SettingsRow>
      <SettingsRow label="未结算预留" description="尚未确认的输入和输出 Token 预留。">{formatBudgetNumber(budget.reserved_tokens)}</SettingsRow>
      <SettingsRow label="迁移期上界" description="历史预算迁移时计入的 Token 上界。">{formatBudgetNumber(budget.opening_tokens)}</SettingsRow>
      <SettingsRow label="保守计入 Token" description="已确认用量 + 未结算预留 + 迁移期上界；用于预算准入，不是实际消耗。">{formatBudgetNumber(budget.charged_tokens)}</SettingsRow>
      <SettingsRow label="Token 上限" description="当前工作空间模型调用的累计预算上限。">{formatBudgetNumber(budget.token_limit)}</SettingsRow>
      {budget.token_limit === 0 && <p className="notice">Token 上限为 0，当前预算未开放，模型调用受限。</p>}
    </section>

    <section className="settings-section">
      <h2 className="settings-section-title">并发与费用</h2>
      <SettingsRow label="并发占用" description="当前占用的模型调用并发槽 / 并发上限。">{formatBudgetNumber(budget.active_reservations)} / {formatBudgetNumber(budget.concurrency_limit)}</SettingsRow>
      <SettingsRow label="费用上限" description="按配置币种显示费用上限；未提供的金额或币种保持未知。">{formatBudgetCost(budget.cost_limit_microunits, budget.currency)}</SettingsRow>
      <p className="notice">费用信息缺失不表示免费；费用上限也不代表已经发生的费用。</p>
    </section>

    <section className="settings-section">
      <h2 className="settings-section-title">最近未结算请求</h2>
      <p className="notice">显示当前返回的最近记录。请求超时不表示远端已取消，也不表示预留已经释放。</p>
      {unsettled === null ? <p className="notice">未结算请求信息未知。</p> : unsettled.length === 0 ? <p className="notice">当前列表没有未结算请求。</p> : unsettled.map((value, index) => {
        const item: BudgetRecord = value && typeof value === "object" && !Array.isArray(value) ? value as BudgetRecord : {};
        return <div className="data-row budget-unsettled-record" key={index}>
          <strong>{budgetText(item.purpose)}</strong>
          <dl>
            <dt>状态</dt><dd>{budgetText(item.code)}</dd>
            <dt>输入预留</dt><dd>{formatBudgetNumber(item.input_reserved)}</dd>
            <dt>输出预留</dt><dd>{formatBudgetNumber(item.output_reserved)}</dd>
            <dt>隔离至</dt><dd>{formatBudgetRecoveryTime(item.recover_after)}</dd>
          </dl>
        </div>;
      })}
    </section>
  </>;
}

import { useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { isClosedQuest, namesLabel, needsQuestAttention, statusLabel } from "./presentation";

type Row = Record<string, unknown>;

export interface WorkspaceQuest {
  id: string;
  title: string;
  status: string;
  version: number;
  goal: string;
}

export interface QuestWorkspaceProps {
  quests: WorkspaceQuest[];
  selected: WorkspaceQuest | null;
  selectedId: string;
  connected: boolean;
  error: string;
  hasMore: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  plan: Row | null;
  planNotice: ReactNode;
  blocked: boolean;
  onApprove: () => void;
  grants: ReactNode;
}

const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const records = (value: unknown): Row[] => Array.isArray(value)
  ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];
type QuestFilter = "all" | "active" | "attention" | "closed";
const QUEST_FILTERS: { id: QuestFilter; label: string }[] = [
  { id: "all", label: "全部" }, { id: "active", label: "未结束" },
  { id: "attention", label: "需处理" }, { id: "closed", label: "已结束" },
];

const QUEST_PHASES: Record<string, string> = {
  proposed: "目标已提出，后续计划与团队仍以实际提案为准。",
  awaiting_approval: "任务正在等待批准。请核对计划、任务团队及审批中心中需要确认的内容。",
  approved: "任务已批准；执行仍需满足当前计划、团队、工具权限与预算约束。",
  queued: "任务已进入队列，等待满足资源与执行条件。",
  running: "任务处于运行阶段。运行活动中可查看已记录的成员执行情况。",
  blocked: "任务已阻塞。请结合运行活动、审批与权限记录核对原因。",
  paused: "任务已暂停，当前记录保留在此工作空间。",
  needs_input: "任务需要补充信息，请回到长期对话继续说明。",
  reviewing: "任务正在复核。请以验证与最终任务状态判断结果。",
  completed: "任务状态为已完成，可通过计划与运行活动回查执行和验证记录。",
  failed: "任务已失败。请查看运行活动，并在长期对话中讨论后续处理。",
  cancelled: "任务已取消，历史计划与执行记录仍可回查。",
  rejected: "任务已拒绝，可查看历史计划与审批记录了解处理经过。",
};

function costLimit(plan: Row): string {
  if (plan.max_cost_microunits === null) return "未设置";
  if (plan.max_cost_microunits === undefined) return "未知";
  return `${text(plan.max_cost_microunits)} 微单位 · ${text(plan.cost_currency, "币种未知")}`;
}

function criteria(value: unknown): string {
  return Array.isArray(value) ? value.map((item) => text(item)).join("；") || "未提供" : text(value, "未提供");
}

export default function QuestWorkspace({
  quests, selected, selectedId, connected, error, hasMore, onSelect, onLoadMore,
  plan, planNotice, blocked, onApprove, grants,
}: QuestWorkspaceProps) {
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<QuestFilter>("all");
  const searchInput = useRef<HTMLInputElement>(null);
  const detailRegion = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => { if (detailRegion.current) detailRegion.current.scrollTop = 0; }, [selectedId]);
  const search = query.trim().toLocaleLowerCase();
  const filtered = quests.filter((quest) => {
    const matchesSearch = !search || `${quest.title} ${quest.goal} ${quest.id}`.toLocaleLowerCase().includes(search);
    const matchesStatus = filter === "all" || (filter === "active" && !isClosedQuest(quest.status)) ||
      (filter === "attention" && needsQuestAttention(quest.status)) || (filter === "closed" && isClosedQuest(quest.status));
    return matchesSearch && matchesStatus;
  });
  const clearSearch = () => { setQuery(""); searchInput.current?.focus(); };
  const resetFilters = () => { setQuery(""); setFilter("all"); searchInput.current?.focus(); };
  const navigateList = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229 || event.altKey || event.ctrlKey || event.metaKey) return;
    if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key) || !(event.target instanceof HTMLElement)) return;
    const current = event.target.closest<HTMLButtonElement>("button.list-row");
    if (!current || !event.currentTarget.contains(current)) return;
    const buttons = [...event.currentTarget.querySelectorAll<HTMLButtonElement>("button.list-row")];
    const index = buttons.indexOf(current);
    const nextIndex = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1
      : Math.max(0, Math.min(buttons.length - 1, index + (event.key === "ArrowDown" ? 1 : -1)));
    const next = buttons[nextIndex];
    if (!next) return;
    event.preventDefault();
    next.focus();
    if (next !== current) next.click();
  };
  const nodes = records(plan?.nodes);
  return <div className="quest-workspace">
    <div className="quest-list">
      <div className="section-heading"><span>后台任务</span><span>{quests.length} 项已加载{hasMore ? " · 还有更多" : ""}</span></div>
      <div className="quest-search">
        <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg>
        <input ref={searchInput} type="search" aria-label="搜索任务" placeholder="搜索已加载的任务" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
          if (event.key === "Escape" && !event.nativeEvent.isComposing && event.nativeEvent.keyCode !== 229) { event.preventDefault(); clearSearch(); }
        }} />
        {query && <button type="button" className="icon-button" aria-label="清除任务搜索" onClick={clearSearch}>×</button>}
      </div>
      <div className="quest-filters">{QUEST_FILTERS.map((item) => <button type="button" key={item.id} className={`text-button${filter === item.id ? " active" : ""}`} aria-pressed={filter === item.id} onClick={() => setFilter(item.id)}>{item.label}</button>)}</div>
      {quests.length > 0 && <p className="notice quest-filter-count">显示 {filtered.length} / {quests.length} 项已加载任务</p>}
      {error && <p className="notice error" role="alert">任务列表加载失败：{error}</p>}
      {!quests.length ? <div className="quest-empty">
        <p>{connected ? "暂无后台任务" : "连接 Core 后显示任务"}</p>
        <p className="notice">在长期对话中提出目标，计划、团队与执行记录会归到对应任务。</p>
