  if (/\.(zip|exe|dll|db|sqlite3?|woff2?|ttf|mp4|mp3|docx?|xlsx?|pptx?|bin|ico)$/i.test(path)) return "unsupported";
  return "text";
}
export function nativeFileSource(): FileSource {
  return {
    list: (path) => invoke("workspace_files_list", { path }),
    read: (path) => invoke("workspace_file_read", { path: relativeFilePath(path) }),
    changes: () => invoke("workspace_changes"),
    diff: (path) => invoke("workspace_file_diff", { path: relativeFilePath(path) }),
  };
}
export function importedFileSource(input: File[]): FileSource {
  const files = new Map(input.map((file) => [relativeFilePath(file.webkitRelativePath || file.name), file]));
  return {
    async list(directory) {
      const prefix = directory ? `${relativeFilePath(directory)}/` : "";
      const entries = new Map<string, WorkspaceFile>();
      for (const [path, file] of files) {
        if (!path.startsWith(prefix)) continue;
        const suffix = path.slice(prefix.length), name = suffix.split("/")[0], child = prefix + name;
        if (!entries.has(child)) entries.set(child, { path: child, name, directory: suffix.includes("/"), size: file.size, modified: file.lastModified });
      }
      return [...entries.values()].sort((a, b) => Number(b.directory) - Number(a.directory) || a.name.localeCompare(b.name));
    },
    async read(value) {
      const path = relativeFilePath(value), file = files.get(path);
      if (!file) throw new Error("此文件未在选择的文件中，请选择所在目录或文件。");
      if (file.size > MAX_FILE) throw new Error("文件超过 24 MB 预览上限。");
      const kind = fileKind(path);
      if (kind === "text") {
        if (file.size > TEXT_LIMIT) throw new Error("文本超过 2 MB 预览上限。");
        const bytes = await file.arrayBuffer();
        let text: string;
        try { text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { throw new Error("此文件不是 UTF-8 文本，暂不支持预览。"); }
        if (text.includes("\0")) return { path, kind: "unsupported", size: file.size };
        return { path, kind, text, size: file.size, modified: file.lastModified };
      }
      return { path, kind, bytes: kind === "unsupported" ? undefined : [...new Uint8Array(await file.arrayBuffer())], mime: kind === "pdf" ? "application/pdf" : file.type, size: file.size, modified: file.lastModified };
    },
    async changes() { return { files: [], repository: false }; },
    async diff() { throw new Error("导入文件不包含 Git 历史，无法显示更改。"); },
  };
}
import { useEffect, useMemo, useRef, useState } from "react";

const KEYWORDS = /^(?:async|await|break|case|catch|class|const|continue|def|delete|elif|else|enum|except|export|extends|false|finally|for|from|fn|function|if|impl|import|in|interface|let|match|mod|new|None|null|pass|private|pub|raise|return|self|static|struct|super|switch|throw|trait|true|try|type|use|var|while|with|yield)$/;
function Tokens({ line }: { line: string }) {
  return <>{line.split(/(\/\/.*$|#.*$|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b[A-Za-z_$][\w$]*\b|\b\d+(?:\.\d+)?\b)/g).map((part, index) => <span key={index} className={/^(\/\/|#)/.test(part) ? "syntax-comment" : /^["'`]/.test(part) ? "syntax-string" : KEYWORDS.test(part) ? "syntax-keyword" : /^\d/.test(part) ? "syntax-number" : undefined}>{part}</span>)}</>;
}
export default function CodePreview({ text, path, diff = false }: { text: string; path: string; diff?: boolean }) {
  const lines = useMemo(() => text.split(/\r?\n/), [text]);
  const [wrap, setWrap] = useState(false), [query, setQuery] = useState(""), [match, setMatch] = useState(0), [top, setTop] = useState(0);
  const viewport = useRef<HTMLDivElement>(null);
  const positions = useRef(new Map<string, number>());
  const matches = useMemo(() => query ? lines.flatMap((line, i) => line.toLocaleLowerCase().includes(query.toLocaleLowerCase()) ? [i] : []) : [], [lines, query]);
  const start = wrap ? 0 : Math.max(0, Math.floor(top / 22) - 12), end = wrap ? lines.length : Math.min(lines.length, start + 160);
  useEffect(() => { const element = viewport.current; if (element) element.scrollTop = positions.current.get(path) || 0; setQuery(""); setMatch(0); }, [path]);
  const go = (next: number) => { const index = (next + matches.length) % matches.length; setMatch(index); if (viewport.current && matches.length) { if (wrap) viewport.current.querySelector(`[data-line="${matches[index] + 1}"]`)?.scrollIntoView({ block: "center" }); else viewport.current.scrollTop = Math.max(0, (matches[index] - 8) * 22); } };
  return <div className="code-preview">
    <div className="source-controls"><label><svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor"><circle cx="7" cy="7" r="4.5" /><path d="m10.5 10.5 3 3" /></svg><input aria-label="在文件中查找" placeholder="在文件中查找" value={query} onChange={(event) => { setQuery(event.target.value); setMatch(0); }} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); go(match + (event.shiftKey ? -1 : 1)); } if (event.key === "Escape") setQuery(""); }} /></label>{query && <><span>{matches.length ? match + 1 : 0}/{matches.length}</span><button type="button" aria-label="上一个匹配" disabled={!matches.length} onClick={() => go(match - 1)}>↑</button><button type="button" aria-label="下一个匹配" disabled={!matches.length} onClick={() => go(match + 1)}>↓</button></>}<button type="button" className={wrap ? "active" : ""} aria-pressed={wrap} onClick={() => setWrap((value) => !value)}>自动换行</button><span>{lines.length.toLocaleString()} 行</span></div>
    <div ref={viewport} className={`source-lines${wrap ? " is-wrapped" : ""}`} tabIndex={0} aria-label={`${path} ${diff ? "更改" : "源码"}`} onScroll={(event) => { const value = event.currentTarget.scrollTop; setTop(value); positions.current.set(path, value); }}>
      <div style={{ paddingTop: start * 22, paddingBottom: (lines.length - end) * 22 }}>
        {lines.slice(start, end).map((line, offset) => { const number = start + offset; return <div className={`source-line${query && line.toLocaleLowerCase().includes(query.toLocaleLowerCase()) ? " search-match" : ""}${diff && line.startsWith("+") && !line.startsWith("+++") ? " diff-added" : diff && line.startsWith("-") && !line.startsWith("---") ? " diff-removed" : ""}`} data-line={number + 1} key={number}><span className="source-line-number" aria-hidden="true">{number + 1}</span><code><Tokens line={line || " "} /></code></div>; })}
      </div>
    </div>
  </div>;
}
