function BinaryPreview({ document }: { document: WorkspaceDocument }) {
  const url = useMemo(() => document.bytes ? URL.createObjectURL(new Blob([new Uint8Array(document.bytes)], { type: document.mime || "application/octet-stream" })) : "", [document]);
