    {mode === "diff" ? diffLoading ? <p className="preview-notice" role="status">正在读取更改…</p> : diffError ? <p className="preview-notice error" role="alert">{diffError}</p> : diff && <>{diff.truncated && <p className="preview-notice">更改内容过长，仅显示部分。</p>}{diff.binary ? <p className="preview-notice">二进制文件已更改，无法显示文本差异。</p> : diff.text ? <CodePreview text={diff.text} path={`${path}:diff`} diff /> : <p className="preview-notice">没有可显示的文本差异。</p>}</> : state.loading ? <p className="preview-notice" role="status">正在读取文件…</p> : state.error ? <p className="preview-notice error" role="alert">{state.error}</p> : document && <>
