function EventLine({ event, quests, runs, memory, groupExpanded, onQuest, onOpenFile, onInspect }: { event: TimelineEvent; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; groupExpanded: boolean; onQuest: (id: string) => void; onOpenFile?: (path: string) => void; onInspect: () => void }) {
