/* Current workspace is the real project. Keep this in the single style.css. */
.workspace-selector-name { font-size: 18px; line-height: 24px; }
.sidebar-section-label { margin: 18px 8px 10px; color: var(--muted); font-size: 13px; line-height: 20px; font-weight: 400; }
.sidebar-project-toggle { display: flex; align-items: center; gap: 6px; width: 100%; height: 30px; padding: 0 8px; border: 0; border-radius: 10px; background: none; color: var(--color-text-secondary); text-align: left; font-size: 13px; line-height: 20px; }
.sidebar-project-toggle > svg { flex: none; width: 16px; height: 16px; }
.sidebar-project-toggle > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sidebar-project-toggle:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.sidebar-project-toggle .project-chevron { width: 12px; height: 12px; margin-left: -4px; color: var(--muted); }
.sidebar-project-content, .quest-group-content { height: auto; overflow: hidden; opacity: 1; transition: height .15s var(--ease-out), opacity .15s var(--ease-out); }
.sidebar-project-content .conversation-entry { padding-left: 34px; }
.sidebar-project-content .conversation-entry .nav-icon { display: none; }
.rail-compact .sidebar-project-group, .rail-compact .sidebar-project-content { display: contents; }
.rail-compact .sidebar-section-label, .rail-compact .sidebar-project-toggle { display: none; }
.rail-compact .sidebar-project-content .conversation-entry { padding: 8px; }
.rail-compact .sidebar-project-content .conversation-entry .nav-icon { display: block; }
.quest-project-list { display: flex; flex-direction: column; gap: 12px; }
.quest-project-toggle, .quest-closed-toggle { display: flex; align-items: center; gap: 6px; width: 100%; min-height: 30px; padding: 5px 6px; border: 0; border-radius: 7.5px; background: none; color: var(--color-text-secondary); text-align: left; font-size: 13px; line-height: 20px; }
.quest-project-toggle > svg, .quest-closed-toggle > svg { flex: none; }
.quest-project-toggle > span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.quest-project-toggle > small, .quest-closed-toggle > small { margin-left: auto; color: var(--muted); font-size: 11px; line-height: 16px; }
.quest-project-toggle:hover, .quest-closed-toggle:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.quest-project-tasks { padding-left: 12px; }
.quest-project-tasks .list-row { padding: 8px; }
.quest-closed-toggle { margin-top: 4px; color: var(--muted); font-size: 12px; }
.quest-closed-group .quest-group-content { padding-left: 8px; }
@media (max-width: 1000px) {
  .quest-body .quest-list > .list.quest-project-list { display: flex; }
}
@media (max-width: 760px) {
  .rail .sidebar-project-group, .rail .sidebar-project-content { display: contents; }
  .rail .sidebar-section-label, .rail .sidebar-project-toggle { display: none; }
  .rail .sidebar-project-content .conversation-entry { padding: 8px; }
  .rail .sidebar-project-content .conversation-entry .nav-icon { display: block; }
}

