.router-state-label { margin-left: 6px; font-size: 11px; }
.router-status[data-status="正在回复"] { color: var(--color-accent); }
.router-status[data-status="供应商未配置"], .router-status[data-status="未连接 Core"] { color: var(--color-status-warning); }
.conversation-files-toggle { display: grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); }
