/* One desktop composition. System fonts approximate the captured 430/510 axes with 400/500. */
:root {
  --font-weight-body: 400; --font-weight-strong: 500;
  --color-text-secondary: rgba(13,13,13,.65);
  --color-border-strong: rgba(13,13,13,.118);
  --color-background-nav-active: rgba(13,13,13,.055);
  --color-background-control-subtle: rgba(13,13,13,.03);
  --color-background-command: rgba(13,13,13,.055);
  --color-sidebar-surface: rgba(255,255,255,.65);
  --color-shell-background: var(--app-color-background-surface-under);
  --color-status-error: #a24740; --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1; --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13,13,13,.18); --color-mask-solid: #000;
  --muted: var(--app-color-text-foreground-tertiary); --line: var(--color-border); --accent: var(--color-accent);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif;
  font-size: 14px; font-weight: 400; color: var(--color-text);
  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252,252,252,.65); --color-border-strong: rgba(252,252,252,.14);
  --color-background-nav-active: rgba(252,252,252,.078); --color-background-control-subtle: rgba(252,252,252,.04);
  --color-background-command: rgba(252,252,252,.055); --color-sidebar-surface: rgba(17,17,17,.65);
  --color-status-error: #ff9c94; --color-status-warning: #e0b471;
  --color-background-warning: #2a241b; --color-border-warning: #66523c; --color-scrollbar: rgba(252,252,252,.22);
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }

