                    "event_id": row["id"],
                    "seq": None,
                    "created_at": row["created_at"],
                    "quest_id": row["quest_id"],
                    "worker_id": row["worker_id"],
                    "run_id": row["worker_run_id"],
                    "title": "Independent semantic test",
