.conversation-changes-overview:hover { background: var(--color-background-secondary-ghost-hover); }
.conversation-changes-overview > span:last-child { display: inline-flex; align-items: center; gap: 4px; color: var(--muted); font-size: 12px; }
.popover-surface { background: var(--app-color-background-surface); }
.disclosure-popover { max-height: calc(100dvh - 112px); overflow-y: auto; overscroll-behavior: contain; }
.composer-changes { display: flex; justify-content: center; margin-bottom: 8px; }
.composer-changes button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 30px; padding: 5px 12px; border: 0.8px solid var(--color-border); border-radius: 12.5px; background: var(--app-color-background-surface); color: var(--color-text-secondary); font-size: 13px; line-height: 20px; }
.composer-changes button:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.event-detail { font-size: 14px; line-height: 21px; }
.detail-summary-action { display: inline-flex; align-items: center; margin-left: 4px; }
.event-file-open { display: grid; place-items: center; flex: none; width: 21px; height: 21px; padding: 0; border: 0; border-radius: 5px; background: none; color: inherit; opacity: 0; transition: opacity .15s var(--ease-out); }
.event-line > summary:hover .event-file-open, .event-line:focus-within .event-file-open { opacity: 1; }
.event-file-open:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
