fn repository(root: &Path) -> Result<bool, String> {
    let output = git(root, &["rev-parse", "--show-toplevel"])?;
    if !output.status.success() {
        return Ok(false);
    }
    let value = String::from_utf8(output.stdout).map_err(|_| "Git 路径不是 UTF-8。")?;
    Ok(fs::canonicalize(value.trim()).map_err(|_| "Git 根目录不可用。")? == root_path(root)?)
}

pub fn changes(root: &Path) -> Result<ChangeSet, String> {
    if !repository(root)? {
        return Ok(ChangeSet {
            files: Vec::new(),
            repository: false,
            truncated: false,
        });
    }
    let output = git(
        root,
        &[
            "status",
            "--porcelain=v1",
            "-z",
            "--untracked-files=all",
            "--ignore-submodules=all",
        ],
    )?;
    if !output.status.success() {
        return Err("无法读取工作空间更改。".into());
    }
    let mut records = output
        .stdout
        .split(|byte| *byte == 0)
        .filter(|record| !record.is_empty());
    let mut files = Vec::new();
    let mut truncated = false;
    while let Some(record) = records.next() {
        if record.len() < 4 {
            return Err("Git 返回了无效的文件状态。".into());
        }
        let status = std::str::from_utf8(&record[..2])
            .map_err(|_| "Git 状态无效。")?
            .to_string();
        let path = std::str::from_utf8(&record[3..])
            .map_err(|_| "Git 文件名不是 UTF-8。")?
            .to_string();
        let previous_path = if status.contains('R') || status.contains('C') {
            Some(
                String::from_utf8(records.next().ok_or("Git 重命名记录不完整。")?.to_vec())
                    .map_err(|_| "Git 文件名不是 UTF-8。")?,
            )

