            break;
        }
        // Skip symlinks and malformed status paths rather than handing the UI an escape target.
        if resolve(root, &path, false, true).is_err() {
            continue;
        }
        files.push(FileChange {
            path,
            status: status.trim().to_string(),
            previous_path,
            added: None,
            removed: None,
        });
    }
    if let Ok(stats) = git(
        root,
        &[
            "diff",
            "--numstat",
            "-z",
            "--no-ext-diff",
            "--no-textconv",
            "HEAD",
            "--",
        ],
    ) {
        if stats.status.success() {
            let mut records = stats
                .stdout
                .split(|byte| *byte == 0)
                .filter(|record| !record.is_empty());
            while let Some(record) = records.next() {
                let mut fields = record.splitn(3, |byte| *byte == b'\t');
                let added = fields
                    .next()
                    .and_then(|value| std::str::from_utf8(value).ok())
                    .and_then(|value| value.parse::<u64>().ok());
                let removed = fields
                    .next()
                    .and_then(|value| std::str::from_utf8(value).ok())
                    .and_then(|value| value.parse::<u64>().ok());
                let path = fields.next().unwrap_or_default();
                let path = if path.is_empty() {
                    let _previous = records.next();
                    records.next().unwrap_or_default()
                } else {
                    path
                };
                if let Ok(path) = std::str::from_utf8(path) {
                    if let Some(file) = files.iter_mut().find(|file| file.path == path) {
                        file.added = added;
                        file.removed = removed;
                    }
                }
            }
        }
    }
    Ok(ChangeSet {
        files,
        repository: true,
        truncated,
    })
}

pub fn diff(root: &Path, path: &str) -> Result<FileDiff, String> {
    resolve(root, path, false, true)?;
    if !repository(root)? {
        return Err("当前工作空间不是 Git 根目录，无法显示更改。".into());
    }
    let output = git(
        root,
        &[
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--no-color",
            "HEAD",
            "--",
            path,
        ],
    )?;
    let output = if output.status.success() {
        output
    } else {
        git(
            root,
            &[
                "diff",
                "--no-ext-diff",
                "--no-textconv",
                "--no-color",
