export function PreviewDivider({ width, onResize }: { width: number; onResize: (width: number) => void }) {
  const drag = useRef<{ x: number; width: number } | null>(null);
  const clamp = (value: number) => Math.min(76, Math.max(34, value));
  const move = (event: ReactPointerEvent<HTMLDivElement>) => { if (!drag.current) return; const total = event.currentTarget.parentElement?.clientWidth || 1; onResize(clamp(drag.current.width + (drag.current.x - event.clientX) / total * 100)); };
