import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, summaryTitle, summaryAction, scrollKey, initialExpanded = false, onExpandedChange, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; summaryTitle?: string; scrollKey?: string;
  summaryAction?: ReactNode;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; children: ReactNode; onInspect: () => void;
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const [present, setPresent] = useState(initialExpanded);
  const initial = useRef(initialExpanded);
  const animatedExpanded = useRef(initialExpanded);
  const desired = useRef(initialExpanded);
  const panel = useRef<HTMLDivElement>(null);

  // Depend only on user expansion. Polling must not restart animations or move scroll positions.
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !expanded);
    // A regrouped event restores its measured-open state without replaying an animation.
    if (animatedExpanded.current === expanded) return;
    animatedExpanded.current = expanded;
    const finish = () => {
      element.style.height = desired.current ? "auto" : "0px";
      element.style.opacity = desired.current ? "1" : "0";
      if (!desired.current) setPresent(false);
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    const height = element.getBoundingClientRect().height;
    const opacity = getComputedStyle(element).opacity;
    element.style.height = `${height}px`;
    element.style.opacity = opacity;
    // Establish the current rendered height before transitioning to the measured target.
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = expanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = expanded ? "1" : "0";
      const seconds = Number.parseFloat(getComputedStyle(element).getPropertyValue("--transition-duration-basic")) || .15;
      timeout = window.setTimeout(finish, seconds * 1000 + 50);
    });
    const transitioned = (event: TransitionEvent) => {
      if (event.target === element && event.propertyName === "height") finish();
    };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [expanded]);

  return <details className={`${className}${summaryAction ? " has-summary-action" : ""}`} data-scroll-key={scrollKey} open={present}>
    <summary aria-label={summaryLabel} aria-expanded={expanded} title={summaryTitle || undefined} onClick={(event) => {
      event.preventDefault();
      onInspect();
      desired.current = !desired.current;
      onExpandedChange?.(desired.current);
      setPresent(true);
      setExpanded(desired.current);
    }}>{summary}{summaryAction && <span className="detail-summary-action" onClick={(event) => event.stopPropagation()}>{summaryAction}</span>}</summary>
    <div ref={panel} className="detail-collapsible" style={{ height: initial.current ? "auto" : "0px", opacity: initial.current ? 1 : 0 }}>{children}</div>
  </details>;
}
}

function activitySummary(events: TimelineEvent[], runs: WorkerRun[]): string {
  const successfulLiveTool = (event: TimelineEvent) => {
    const detail = event.detail as Row | undefined;
    return event.kind === "tool_receipt" && event.status === "succeeded" && event.execution_mode === "live" && !(typeof detail?.exit_code === "number" && detail.exit_code !== 0);
  };
  const edits = new Set(events.flatMap((event) => {
    const detail = event.detail as Row | undefined;
    return successfulLiveTool(event) && ["file_write", "file_revise"].includes(text(detail?.tool, "")) && typeof detail?.path === "string" ? [detail.path] : [];
  }));
  const counts = new Map<string, { event: TimelineEvent; count: number }>();
  for (const event of events) {
    const detail = event.detail as Row | undefined;
    const key = event.kind === "tool_receipt" ? `tool:${text(detail?.tool, "unknown")}:${event.status}:${event.execution_mode}:${detail?.exit_code}` : `${eventTitle(event, runs)}:${event.execution_mode}`;
    const existing = counts.get(key);
    if (existing) existing.count += 1;
    else counts.set(key, { event, count: 1 });
  }
  let edited = false;
  return [...counts.values()].map(({ event, count }) => {
    const detail = event.detail as Row | undefined;
    if (successfulLiveTool(event) && ["file_write", "file_revise"].includes(text(detail?.tool, ""))) {
      if (edited) return "";
      edited = true;
      return edits.size ? `编辑了${edits.size === 1 ? "一个" : "多个"}文件` : eventTitle(event, runs);
    }
    if (event.kind === "tool_receipt" && !successfulLiveTool(event)) {
      const result = typeof detail?.exit_code === "number" && detail.exit_code !== 0 ? `失败，退出码 ${detail.exit_code}` : statusLabel(event.status, "结果未知");
      const mode = event.execution_mode === "mock" ? "模拟" : event.execution_mode === "live" ? "" : "来源未知";
      return `${toolLabel(detail?.tool, "工具")}${count > 1 ? ` · ${count} 次调用` : ""}（${[mode, result].filter(Boolean).join(" · ")}）`;
    }
    const label = count > 1 && event.kind === "tool_receipt" ? `${toolLabel(detail?.tool, "工具")} · ${count} 次调用` : eventTitle(event, runs);
    return event.execution_mode === "mock" ? `${label}（模拟）` : label;
  }).join("");
}

function ActivityIcon({ event }: { event?: TimelineEvent }) {
  const detail = event?.detail && typeof event.detail === "object" ? event.detail as Row : {};
  const tool = text(detail.tool, "");
  const shape = event?.kind === "context_archive"
    ? <path d="M2.8 5.2h10.4M2.8 8h10.4M2.8 10.8h6.4" />
    : event?.status?.startsWith("worker.")
      ? <><circle cx="8" cy="5.4" r="2.3" /><path d="M3.2 13.2c.4-2.4 2.4-3.7 4.8-3.7s4.4 1.3 4.8 3.7" /></>
      : ["file_read", "file_write", "file_revise"].includes(tool)
        ? <><path d="M8.6 1.8H4.4A1.6 1.6 0 0 0 2.8 3.4v9.2a1.6 1.6 0 0 0 1.6 1.6h6.4a1.6 1.6 0 0 0 1.6-1.6V5.4L8.6 1.8Z" /><path d="M8.6 2v3.4h3.6" /></>
        : tool && !["shell_inspect", "python_compile", "git_status", "numeric_ast"].includes(tool)
          ? <path d="M9.6 2.6a3.4 3.4 0 0 0-4.2 4.2L2.6 9.6a1.6 1.6 0 0 0 2.2 2.2l2.8-2.8a3.4 3.4 0 0 0 4.2-4.2L10 6.6 9.4 6 8.8 5.4l1.6-1.6Z" />
          : <><rect x="1.75" y="3" width="12.5" height="10" rx="2" /><path d="m4.4 6.6 1.7 1.4-1.7 1.4m4.2.2h3" /></>;
  return <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{shape}</svg>;
}

function Chevron() {
  return <svg data-chevron viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg>;
}

