    void load(); const timer = window.setInterval(() => void load(), 6000);
    return () => { current = false; window.clearInterval(timer); };
  }, [source, open, refresh, onChanges]);
  const chooseFiles = (input: FileList | null) => { if (!input?.length) return; const files = [...input]; setImported(importedFileSource(files)); setImportName(files[0].webkitRelativePath?.split("/")[0] || "已选择的文件"); setTabs([]); setDocuments({}); setActive(""); setScope("files"); };
  const closeTab = (path: string) => { const index = tabs.indexOf(path), next = tabs.filter((tab) => tab !== path); setTabs(next); if (active === path) setActive(next[Math.min(index, next.length - 1)] || ""); readSerial.current.delete(path); setDocuments((old) => { const copy = { ...old }; delete copy[path]; return copy; }); };
  const mode = modes[active] || "preview", document = documents[active]?.document;
  const changed = changes.files.find((file) => file.path === active);
  const displayedChanges = scope === "conversation" ? paths.map((path) => changes.files.find((file) => file.path === path) || { path, status: "记录" }) : changes.files;
  return <aside ref={panel} className={`file-preview-workspace${tree ? " with-file-tree" : ""}`} hidden={!open || !visible} aria-label="工作空间文件预览" onKeyDown={(event) => { if (event.key === "Escape" && !event.defaultPrevented && !(event.target instanceof HTMLInputElement)) { event.preventDefault(); onClose(); } }}>
    <div className="preview-tabs-bar"><div className="preview-tabs" role="tablist" aria-label="打开的文件">{tabs.map((path) => <div className={`preview-tab${active === path ? " active" : ""}`} key={path}><button type="button" role="tab" id={`file-tab-${tabs.indexOf(path)}`} aria-controls={`file-pane-${tabs.indexOf(path)}`} aria-selected={active === path} tabIndex={active === path ? 0 : -1} title={path} onClick={() => setActive(path)} onKeyDown={(event) => { const index = tabs.indexOf(path), next = event.key === "ArrowRight" ? (index + 1) % tabs.length : event.key === "ArrowLeft" ? (index + tabs.length - 1) % tabs.length : event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : -1; if (next >= 0) { event.preventDefault(); setActive(tabs[next]); requestAnimationFrame(() => panel.current?.querySelector<HTMLButtonElement>(`#file-tab-${next}`)?.focus()); } if (event.key === "Delete") closeTab(path); }}><FileIcon /><span>{path.split("/").pop()}</span></button><button type="button" className="preview-tab-close" aria-label={`关闭 ${path}`} onClick={() => closeTab(path)}>×</button></div>)}</div><button type="button" className="icon-button" aria-label="切换文件树" aria-pressed={tree} title="文件树" onClick={() => setTree((value) => !value)}><svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="2.5" y="3" width="15" height="14" rx="3" /><path d="M12 3v14" /></svg></button><button type="button" className="icon-button preview-close" aria-label="关闭文件预览" title="关闭预览 · Escape" onClick={onClose}>×</button></div>
    <div className="preview-toolbar"><span className="preview-breadcrumb" title={active || workspaceName}>{source === imported ? importName : workspaceName}<span>›</span><strong>{active || "文件"}</strong></span>{active && <div className="preview-view-actions">{changed && <button type="button" aria-pressed={mode === "diff"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "diff" ? "preview" : "diff" }))}>显示更改</button>}{document?.kind === "text" && /\.md(?:own)?$/i.test(active) && <button type="button" aria-pressed={mode === "source"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "source" ? "preview" : "source" }))}>{mode === "source" ? "预览" : "查看源代码"}</button>}{document?.text !== undefined && <button type="button" aria-label="复制文件内容" title="复制内容" onClick={() => void navigator.clipboard.writeText(document.text || "").then(() => report("已复制文件内容"), () => report("无法复制，请手动选择。"))}>复制</button>}<button type="button" aria-label="重新读取文件" title="重新读取" onClick={() => { read(active, true); setRefresh((value) => value + 1); }}>↻</button></div>}</div>
