      <div className="preview-file-tree" hidden={!tree}><div className="file-tree-search"><input aria-label="筛选已加载文件" placeholder="筛选已加载文件…" value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="file-tree-scopes"><button type="button" aria-pressed={scope === "files"} onClick={() => setScope("files")}>所有文件</button><button type="button" aria-pressed={scope === "changes"} onClick={() => setScope("changes")}>已更改{changes.repository ? ` ${changes.files.length}` : ""}</button>{scope === "conversation" && <span>对话记录</span>}<button type="button" aria-label="刷新文件树" title="刷新文件树与更改" onClick={() => setRefresh((value) => value + 1)}>↻</button></div><div className="file-tree-scroll">{scope === "files" ? source ? <Directory path="" source={source} active={active} onOpen={openFile} query={query.toLocaleLowerCase().trim()} refresh={refresh} /> : <p className="tree-notice">尚未选择文件。</p> : <>{changesError && <p className="tree-notice error" role="alert">{changesError}</p>}<p className="file-tree-caption">{scope === "conversation" ? "已加载对话中记录的文件；差异来自当前 Git。" : changes.repository ? "当前工作空间 · Git 工作树与暂存区" : "当前文件来源没有 Git 变更记录。"}</p>{displayedChanges.filter((file) => file.path.toLocaleLowerCase().includes(query.toLocaleLowerCase().trim())).map((file) => <button type="button" key={file.path} className={`file-tree-row changed-file${active === file.path ? " selected" : ""}`} title={file.path} onClick={() => { openFile(file.path); if (changes.files.some((change) => change.path === file.path)) setModes((old) => ({ ...old, [file.path]: "diff" })); }}><span className="file-change-status">{file.status}</span><span>{file.path}</span>{file.added !== undefined && <small className="file-added">+{file.added}</small>}{file.removed !== undefined && <small className="file-removed">−{file.removed}</small>}</button>)}{changes.truncated && <p className="tree-notice">变更较多，仅显示已读取部分。</p>}</>}</div>{!native && <button type="button" className="file-import-button" onClick={() => d