export function PreviewDivider({ width, onResize }: { width: number; onResize: (width: number) => void }) {
  const drag = useRef<{ x: number; width: number } | null>(null);
  const clamp = (value: number) => Math.min(76, Math.max(34, value));
  const move = (event: ReactPointerEvent<HTMLDivElement>) => { if (!drag.current) return; const total = event.currentTarget.parentElement?.clientWidth || 1; onResize(clamp(drag.current.width + (drag.current.x - event.clientX) / total * 100)); };
  return <div className="preview-divider" role="separator" aria-label="调整文件预览宽度" aria-orientation="vertical" aria-valuemin={34} aria-valuemax={76} aria-valuenow={Math.round(width)} tabIndex={0} onPointerDown={(event) => { drag.current = { x: event.clientX, width }; event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={move} onPointerUp={(event) => { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); }} onPointerCancel={() => { drag.current = null; }} onKeyDown={(event) => { if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) { event.preventDefault(); onResize(event.key === "Home" ? 34 : event.key === "End" ? 76 : clamp(width + (event.key === "ArrowLeft" ? 2 : -2))); } }} />;
}

/* Transcript stays continuous; execution detail floats above it. */
.conversation-shell { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0 4px 4px 0; background: var(--app-color-background-surface); }
.chat-workspace { position: relative; display: grid; grid-template-columns: minmax(0,1fr); min-width: 0; min-height: 0; overflow: hidden; margin: 0 4px 4px 0; border: .8px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface); }
.chat-workspace > .conversation-shell { margin: 0; }
.chat-workspace.preview-open { grid-template-columns: minmax(0,1fr) 5px minmax(0,var(--preview-width)); }
.home-files-button { position: absolute; top: 14px; right: 20px; display: flex; align-items: center; gap: 6px; height: 28px; border: 0; border-radius: 7.5px; background: transparent; color: var(--muted); font-size: 12px; }
.home-files-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.preview-divider { position: relative; z-index: 2; width: 5px; margin: 0; cursor: col-resize; touch-action: none; background: var(--app-color-background-surface); }
.preview-divider::before { content: ""; position: absolute; inset: 0 2px; background: var(--color-border-subtle); transition: background-color .15s var(--ease-out); }
.preview-divider:hover::before, .preview-divider:focus-visible::before { background: var(--color-accent); }
.file-preview-workspace { position: relative; display: flex; flex-direction: column; min-height: 0; min-width: 0; overflow: hidden; background: var(--app-color-background-surface); animation: preview-enter .15s var(--ease-out); }
.preview-tabs-bar { display: flex; align-items: center; gap: 4px; min-height: 52px; padding: 6px 10px; border-bottom: 1px solid var(--color-border-subtle); }
.preview-tabs { display: flex; flex: 1; min-width: 0; overflow: auto; gap: 6px; }
.preview-tab { display: flex; align-items: center; flex: 0 0 auto; max-width: 260px; height: 32px; border: .8px solid transparent; border-radius: 10px; color: var(--muted); }
.preview-tab.active { border-color: var(--color-border); color: var(--color-text); box-shadow: var(--shadow-sm); }
.preview-tab:hover { background: var(--color-background-control-subtle); }
.preview-tab > [role="tab"] { display: flex; align-items: center; gap: 7px; min-width: 0; height: 30px; padding: 0 8px 0 10px; border: 0; border-radius: 8px; background: none; font-size: 12px; }
.preview-tab > [role="tab"] > span { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.preview-tab > [role="tab"] > svg { flex: none; }
.preview-tab-close { display: grid; place-items: center; width: 24px; height: 24px; flex: none; margin-right: 3px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); font-size: 16px; }
.preview-tab-close:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.preview-tabs-bar > .icon-button { flex: none; width: 28px; height: 28px; }
.preview-close { font-size: 20px; }
.preview-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-height: 44px; padding: 7px 12px; border-bottom: 1px solid var(--color-border-subtle); }
.syntax-comment { color: var(--muted); }
.syntax-keyword { color: var(--color-syntax-keyword); }
.syntax-string { color: var(--color-syntax-string); }
.syntax-number { color: var(--color-syntax-number); }
.source-line.diff-added { background: color-mix(in srgb,var(--color-git-added) 9%,transparent); }
.source-line.diff-removed { background: color-mix(in srgb,var(--color-git-removed) 9%,transparent); }
.source-line.search-match { background: color-mix(in srgb,var(--brand-yellow-400) 20%,transparent); }
@keyframes preview-enter { from { opacity: 0; transform: translateX(6px); } to { opacity: 1; transform: translateX(0); } }
@media (max-width: 1200px) { .preview-open .conversation-status { gap: 6px; } .preview-open .router-state-label { display: none; } .with-file-tree .preview-content { grid-template-columns: minmax(0,1fr) 160px; } .preview-open .timeline { padding-inline: 20px; } }
@media (max-width: 1000px) { .chat-workspace.preview-open { grid-template-columns: minmax(0,1fr); } .preview-open > .conversation-shell, .preview-open > .preview-divider { display: none; } .file-preview-workspace { grid-column: 1; } .with-file-tree .preview-content { grid-template-columns: minmax(0,1fr) 220px; } }
@media (max-width: 760px) { .chat-workspace { margin: 0; border-radius: 0; } .with-file-tree .preview-content { grid-template-columns: minmax(0,1fr) 160px; } .document-rendered { padding: 16px; } }
.topbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; height: 52px; flex: none; padding: 10px 24px; border-bottom: 1px solid var(--color-border-subtle); }
.topbar-title { min-width: 0; }
.topbar-title h1 { margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; line-height: 21px; font-weight: 500; }
.conversation-status { display: flex; align-items: center; gap: 16px; flex: none; color: var(--muted); font-size: 12px; line-height: 20px; }
.router-status { display: inline-flex; align-items: center; }
.worker-menu-anchor, .composer-model-anchor { position: relative; }
.worker-toggle { display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 4px 6px; border: 0; border-radius: 7.5px; background: none; color: var(--muted); font-size: 12px; line-height: 20px; }
.worker-toggle:hover, .worker-toggle[aria-expanded="true"] { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.disclosure-popover { position: absolute; z-index: 45; overflow: hidden; height: 0; opacity: 0; width: 320px; max-width: calc(100vw - 32px); border-radius: 12.5px; box-shadow: var(--shadow-lg); transition: height .15s var(--ease-out), opacity .15s var(--ease-out); }

