export interface WorkspaceFile { path: string; name: string; directory: boolean; size?: number; modified?: number }
export interface FileChange { path: string; status: string; added?: number; removed?: number; previousPath?: string }
export interface ChangeSet { files: FileChange[]; repository: boolean; truncated?: boolean }
export interface WorkspaceDocument { path: string; kind: "text" | "pdf" | "image" | "unsupported"; text?: string; bytes?: number[]; mime?: string; size: number; modified?: number }
export interface FileDiff { text: string; binary?: boolean; truncated?: boolean; scope?: "worktree" | "staged" | "new" }
export interface FileSource {
  list(path: string): Promise<WorkspaceFile[]>;
  read(path: string): Promise<WorkspaceDocument>;
  changes(): Promise<ChangeSet>;
  diff(path: string): Promise<FileDiff>;
}
const MAX_FILE = 24 * 1024 * 1024;
const TEXT_LIMIT = 2 * 1024 * 1024;
export function relativeFilePath(input: string): string {
  const path = input.replace(/\\/g, "/").replace(/^\.\//, "");
  if (!path || path.startsWith("/") || /^[A-Za-z]:/.test(path) || path.split("/").some((part) => part === ".." || part === "" || part.includes(":")) || /[\x00-\x1f]/.test(path)) throw new Error("文件路径不在当前工作空间中。");
  return path;
}
export function fileKind(path: string): WorkspaceDocument["kind"] {
  if (/\.pdf$/i.test(path)) return "pdf";
  if (/\.(png|jpg|jpeg|gif|webp|avif|bmp)$/i.test(path)) return "image";
  if (/\.(zip|exe|dll|db|sqlite3?|woff2?|ttf|mp4|mp3|docx?|xlsx?|pptx?|bin|ico)$/i.test(path)) return "unsupported";
  return "text";
}
export function nativeFileSource(): FileSource {
  return {
    list: (path) => invoke("workspace_files_list", { path }),
    read: (path) => invoke("workspace_file_read", { path: relativeFilePath(path) }),
    changes: () => invoke("workspace_changes"),
    diff: (path) => invoke("workspace_file_diff", { path: relativeFilePath(path) }),
  };
}
export function importedFileSource(input: File[]): FileSource {
  const directory = input[0]?.webkitRelativePath.split("/")[0];
  const sharedRoot = directory && input.every((file) => file.webkitRelativePath.startsWith(`${directory}/`)) ? `${directory}/` : "";
  const files = new Map(input.map((file) => [relativeFilePath(sharedRoot ? file.webkitRelativePath.slice(sharedRoot.length) : file.webkitRelativePath || file.name), file]));
  return {
    async list(directory) {
      const prefix = directory ? `${relativeFilePath(directory)}/` : "";
      const entries = new Map<string, WorkspaceFile>();
      for (const [path, file] of files) {
        if (!path.startsWith(prefix)) continue;
        const suffix = path.slice(prefix.length), name = suffix.split("/")[0], child = prefix + name;
        if (!entries.has(child)) entries.set(child, { path: child, name, directory: suffix.includes("/"), size: file.size, modified: file.lastModified });
      }
      return [...entries.values()].sort((a, b) => Number(b.directory) - Number(a.directory) || a.name.localeCompare(b.name));
    },
    async read(value) {
      const path = relativeFilePath(value), file = files.get(path);
      if (!file) throw new Error("此文件未在选择的文件中，请选择所在目录或文件。");
      if (file.size > MAX_FILE) throw new Error("文件超过 24 MB 预览上限。");
      const kind = fileKind(path);
      if (kind === "text") {
        if (file.size > TEXT_LIMIT) throw new Error("文本超过 2 MB 预览上限。");
        const bytes = await file.arrayBuffer();
        let text: string;
        try { text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { throw new Error("此文件不是 UTF-8 文本，暂不支持预览。"); }
        if (text.includes("\0")) return { path, kind: "unsupported", size: file.size };
        return { path, kind, text, size: file.size, modified: file.lastModified };
      }
      return { path, kind, bytes: kind === "unsupported" ? undefined : [...new Uint8Array(await file.arrayBuffer())], mime: kind === "pdf" ? "application/pdf" : file.type, size: file.size, modified: file.lastModified };
    },
    async changes() { return { files: [], repository: false }; },
    async diff() { throw new Error("导入文件不包含 Git 历史，无法显示更改。"); },
  };
}
"""Read-only validation of immutable, same-Worker artifact revision receipts."""

import hashlib
import json
from pathlib import Path

from .domain import DomainError
from .governance import parameter_digest


def verify_file_revision_chain(connection, run_id, receipt_id):
    """Validate every retained version; current bytes and authority are checked by callers."""
    try:
        run = connection.execute("SELECT * FROM worker_runs WHERE id=?", (run_id,)).fetchone()
        root = connection.execute("SELECT root FROM workspace WHERE singleton=1").fetchone()[0]
        if run is None:
            raise ValueError
        allowed = json.loads(run["allowed_tools_json"])
        if not isinstance(allowed, list) or any(not isinstance(name, str) for name in allowed):
            raise ValueError
        seen, scope, expected, result = [], None, None, None
        while receipt_id and len(seen) < 64:
            if receipt_id in seen:
                raise ValueError
            seen.append(receipt_id)
            row = connection.execute(
                "SELECT r.id AS receipt_id,r.execution_mode AS receipt_mode,r.result_json,"
                "r.result_digest,i.* FROM action_receipts r JOIN action_intents i ON i.id=r.intent_id "
                "WHERE r.id=?",
                (receipt_id,),
            ).fetchone()
            if row is None:
                raise ValueError
            parameters, output = json.loads(row["parameters_json"]), json.loads(row["result_json"])
            name = row["tool_name"]
            call = connection.execute(
                "SELECT * FROM worker_tool_calls WHERE run_id=? AND call_id=?",
                (run_id, row["call_id"]),
            ).fetchone()
            content = parameters["content"].encode("utf-8")
            source_path = Path(parameters["path"])
            if not source_path.is_absolute():
                source_path = Path(root) / source_path
            digest = hashlib.sha256(content).hexdigest()
            if (
                name not in {"file_write", "file_revise"}
                or name not in allowed
                or row["state"] != "succeeded"
                or row["run_id"] != run_id
                or row["worker_id"] != run["worker_id"]
                or row["quest_id"] != run["quest_id"]
                or row["plan_id"] != run["plan_id"]
                or row["plan_revision"] != run["plan_revision"]
                or row["receipt_mode"] != row["execution_mode"]
                or row["execution_mode"] != run["execution_mode"]
                or row["risk"] != "R1"
                or len(content) > 262144
                or parameter_digest(parameters) != row["parameter_digest"]
                or hashlib.sha256(row["result_json"].encode("utf-8")).hexdigest()
                != row["result_digest"]
                or str(source_path.resolve()) != row["resource_scope"]
                or output.get("path") != row["resource_scope"]
                or output.get("sha256") != digest
                or output.get("bytes") != len(content)
                or (expected is not None and expected != digest)
                or (scope is not None and scope != row["resource_scope"])
                or call is None
                or call["state"] != "succeeded"
                or call["receipt_id"] != receipt_id
                or call["tool_name"] != name
                or parameter_digest(json.loads(call["arguments_json"])) != row["parameter_digest"]
            ):
                raise ValueError
            reply = json.loads(call["result_json"])
            if (
                reply.get("call_id") != row["call_id"]
                or reply.get("intent_id") != row["id"]
                or reply.get("receipt_id") != receipt_id
                or reply.get("state") != "succeeded"
                or reply.get("output") != output
            ):
                raise ValueError
            scope = row["resource_scope"]
            if result is None:
                result = {
                    "path": scope,
                    "sha256": digest,
                    "bytes": len(content),
                    "receipt_id": receipt_id,
                    "tool_name": name,
                    "prior_receipt_id": parameters.get("prior_receipt_id"),
                }
            if name == "file_write":
                if set(parameters) != {"path", "content"}:
                    raise ValueError
                return {**result, "revision_receipt_ids": seen}
            if (
                set(parameters) != {"path", "content", "prior_receipt_id", "expected_sha256"}
                or output.get("prior_receipt_id") != parameters["prior_receipt_id"]
                or output.get("prior_sha256") != parameters["expected_sha256"]
                or not isinstance(parameters["prior_receipt_id"], str)
            ):
                raise ValueError
            expected = parameters["expected_sha256"]
            receipt_id = parameters["prior_receipt_id"]
        raise ValueError
    except (ValueError, TypeError, KeyError, IndexError, AttributeError, OSError):
        raise DomainError("Artifact revision receipt chain is invalid") from None

## node_repl + @oai/sky

- Use `node_repl` JavaScript for all Computer Use actions.
- The `node_repl` state persists across calls. Store cross-cell values on `globalThis`; top-level `const` and `let` names cannot be redeclared by later retries.
- For text output, call `nodeRepl.write(...)` with a string. Use `JSON.stringify(...)` for objects.

## Workflow

### Initialize target selection

Run the Initialize setup cell from `SKILL.md` first. Then list apps and choose the target from returned app and window objects:

```js
globalThis.apps = await sky.list_apps();
nodeRepl.write(JSON.stringify(apps, null, 2));
```

Never reconstruct an app or window from guessed fields. Do not call `get_window`, `activate_window`, or any input method until selection has produced exactly one returned window.

```js
{
  function escapeRegExp(value) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function returnedWindowSummary(window) {
    return {
      id: window.id,
      app: window.app,
      title: window.title,
    };
  }

  function requireUniqueWindow(windows, label) {
    if (windows.length !== 1) {
      nodeRepl.write(
        `Returned candidate windows:\n${JSON.stringify(windows.map(returnedWindowSummary), null, 2)}`,
      );
      throw new Error(`Expected exactly one target window for ${label}; found ${windows.length}`);
    }
    return windows[0];
  }

  globalThis.apps = await sky.list_apps();
  globalThis.targetApp = apps.find((app) => app.id === "<app id>");
  if (!targetApp) throw new Error("Target app was not returned by list_apps");
  const targetAppId = targetApp.id;

  if (targetApp.windows.length === 0) {
    await sky.launch_app({ app: targetApp.id });
    globalThis.apps = await sky.list_apps();
    globalThis.targetApp = apps.find((app) => app.id === targetAppId);
  }
  if (!targetApp?.windows.length) {
    throw new Error("Target app did not expose a window after launch");
  }

  const windowTitleHint = "<optional exact window title>";
  const candidateWindows =
    windowTitleHint === "<optional exact window title>"
      ? targetApp.windows
      : targetApp.windows.filter((window) =>
          new RegExp(`^${escapeRegExp(windowTitleHint)}$`, "i").test(window.title ?? ""),
        );
  const returnedWindow = requireUniqueWindow(candidateWindows, targetApp.id);

  globalThis.targetWindow = await sky.get_window({
    id: returnedWindow.id,
    app: returnedWindow.app,
  });
  await sky.activate_window({ window: targetWindow });
  globalThis.state = await sky.get_window_state({ window: targetWindow });
  globalThis.targetWindow = state.window;
}
```

Use `list_windows()` when inspecting currently open windows or recovering a known running app. If the intended app is absent from `list_apps`, launch it with an explicit `.exe` path or `.exe` process identifier, refresh `list_apps()` or `list_windows()`, filter to the intended returned windows, and stop unless the filtered list has exactly one window. Escape Windows path backslashes in JavaScript strings, for example `await sky.launch_app({ app: "C:\\Users\\me\\build\\MyApp.exe" });`.

### Act and refresh

Use a two-cell loop for state-derived inputs: observe and stop, inspect the result, then perform exactly one action and refresh immediately. Element indexes, screenshot IDs, and coordinates are valid only for the observation that produced them. Interleaving or retry requires re-observation.

Accessibility path, cell 1: observe and inspect.

```js
