import { useEffect, useRef, useState } from "react";
import AnimatedDetails from "./AnimatedDetails";
import { request, type Connection } from "./api";
import { errorMessage } from "./logic";
import { statusLabel } from "./presentation";

export interface WorkerRun {
  run_id: string;
  worker_id?: string;
  quest_id?: string;
  role?: string;
  state?: string;
  provider_id?: string;
  model_id?: string;
  steps?: number;
  tool_spent?: number;
  created_at?: string;
  output_contract?: string;
}

export interface ActivityState {
  items: WorkerRun[];
  loading: boolean;
  error: string;
  hasMore: boolean;
  connected: boolean;
}

interface ActivityPage { items: WorkerRun[]; has_more?: boolean }
interface ActivitySnapshot { identity: string; state: ActivityState }

const emptyActivity = (connected: boolean): ActivityState => ({
  items: [], loading: connected, error: "", hasMore: false, connected,
});
const connectionIdentity = (connection: Connection | null) => connection
  ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";

/** This read-only feed runs independently so a slow activity request cannot delay chat. */
export function useWorkerActivity(connection: Connection | null): ActivityState {
  const identity = connectionIdentity(connection);
  const currentIdentity = useRef(identity);
  currentIdentity.current = identity;
  const [snapshot, setSnapshot] = useState<ActivitySnapshot>(() => ({ identity, state: emptyActivity(!!connection) }));

  useEffect(() => {
    if (!connection) {
      setSnapshot({ identity, state: emptyActivity(false) });
      return;
    }
    let active = true;
    let inFlight = false;
    let controller: AbortController | null = null;
    setSnapshot({ identity, state: emptyActivity(true) });
    const accepts = () => active && currentIdentity.current === identity;
    const poll = async () => {
      if (!accepts() || inFlight) return;
      inFlight = true;
      const pending = new AbortController();
      controller = pending;
      const timeout = window.setTimeout(() => pending.abort(), 120000);
      try {
        const page = await request<ActivityPage>(connection, "/api/activity?limit=100", { signal: pending.signal });
        if (!Array.isArray(page.items)) throw new Error("Core 返回了无效执行记录。");
        const items = [...new Map(page.items.filter((item) => item && typeof item === "object" && typeof item.run_id === "string" && item.run_id)
          .map((item) => [item.run_id, item])).values()];
        if (accepts()) setSnapshot({ identity, state: { items, loading: false, error: "", hasMore: page.has_more === true, connected: true } });
      } catch (error) {
        // Old running states must never be presented as the current state after a failed read.
        if (accepts()) setSnapshot({ identity, state: { items: [], loading: false, error: errorMessage(error), hasMore: false, connected: true } });
      } finally {
        window.clearTimeout(timeout);
        if (controller === pending) controller = null;
        inFlight = false;
      }
    };
    void poll();
    const timer = window.setInterval(() => void poll(), 6000);
    return () => { active = false; window.clearInterval(timer); controller?.abort(); };
  }, [identity, connection?.bearer]);

  // Hide a previous workspace synchronously, before the effect starts its next request.
  return snapshot.identity === identity ? snapshot.state : emptyActivity(!!connection);
}

const field = (value: unknown, fallback: string) => typeof value === "string" && value ? value : fallback;
const RUN_PRIORITY: Record<string, number> = { running: 0, blocked: 1, queued: 2, review_pending: 3, paused: 4 };
const priority = (run: WorkerRun) => RUN_PRIORITY[field(run.state, "")] ?? 5;

const count = (value: unknown) => typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value.toLocaleString() : "未知";

/** Match callers by run_id; a Worker's newer run cannot replace a historical run. */
export function WorkerRunDetails({ run, runId, workerId, historicalEvent, historicalTime, initialExpanded = false, onExpandedChange, onInspect = () => {}, scrollKey }: {
  run?: WorkerRun; runId?: string | null; workerId?: string | null; historicalEvent?: string; historicalTime?: string;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; onInspect?: () => void; scrollKey?: string;
}) {
  const matched = run && typeof runId === "string" && run.run_id === runId ? run : undefined;
  return <AnimatedDetails className="worker-run-details" summaryLabel={`查看 Worker 执行详情${runId ? ` ${runId}` : ""}`} scrollKey={scrollKey}
    initialExpanded={initialExpanded} onExpandedChange={onExpandedChange} onInspect={onInspect}
    summary={<><span>执行详情</span><svg data-chevron viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></>}>
    <div className="worker-run-details-body">
      {historicalEvent && <dl className="worker-history-facts"><dt>历史事件</dt><dd>{historicalEvent}</dd><dt>记录时间</dt><dd>{historicalTime || "时间未记录"}</dd></dl>}
      {!matched && <p className="worker-details-notice">执行详情暂未加载。</p>}
      {matched && <><dl className="worker-current-facts">
        <dt>角色</dt><dd>{field(matched.role, "未记录")}</dd>
        <dt>供应商</dt><dd>{field(matched.provider_id, "未记录")}</dd>
        <dt>模型</dt><dd>{field(matched.model_id, "模型未记录")}</dd>
        <dt>当前执行状态</dt><dd>{statusLabel(matched.state)}</dd>
        <dt>已记录步数</dt><dd>{count(matched.steps)}</dd>
        <dt>工具调用次数</dt><dd>{count(matched.tool_spent)}</dd>
      </dl>{historicalEvent && <p className="worker-details-notice">当前执行状态来自最近读取的运行记录，历史事件保留当时的记录。</p>}</>}
      <dl className="worker-identity-facts"><dt>Worker</dt><dd>{field(matched?.worker_id || workerId, "未记录")}</dd><dt>Run</dt><dd>{field(runId, "未记录")}</dd></dl>
    </div>
  </AnimatedDetails>;
}

export default function WorkerActivity({ state, quests, onQuest, onActivity }: {
  state: ActivityState;
  quests: { id: string; title: string }[];
  onQuest: (id: string) => void;
  onActivity: () => void;
}) {
  const visible = state.connected && !state.error ? [...state.items].sort((left, right) => priority(left) - priority(right)).slice(0, 3) : [];
  const notice = !state.connected ? "连接 Core 后查看执行记录" : state.loading ? "正在读取执行记录…"
    : state.error ? "执行状态暂不可用" : !state.items.length ? "暂无执行记录" : "";
  const summary = `最近执行${state.connected && !state.loading && !state.error ? ` · 已加载 ${state.items.length} 条${state.hasMore ? " · 还有更早记录" : ""}` : ""}`;
  return <section className="worker-activity" aria-label="Worker 执行记录" aria-busy={state.loading}>
    <div className="worker-activity-header"><div className="worker-activity-heading"><strong>Worker</strong><small title={summary}>{summary}</small></div>
      <button type="button" className="text-button worker-activity-open" disabled={!state.connected} onClick={onActivity}>查看运行活动</button>
    </div>
    {notice && <p className="worker-activity-notice" title={state.error || undefined}>{notice}</p>}
    {visible.length > 0 && <div className="worker-activity-list">{visible.map((run) => {
      const quest = quests.find((item) => item.id === run.quest_id);
      const model = field(run.model_id, "模型未记录");
      const title = `角色：${field(run.role, "未记录")}\n供应商：${field(run.provider_id, "未记录")}\n模型：${model}\nWorker：${field(run.worker_id, "未记录")}\nRun：${run.run_id}\n任务：${quest?.title || field(run.quest_id, "未记录")}`;
      const content = <><span className="worker-run-content"><span className="worker-run-heading"><strong>{field(run.role, "Worker")}</strong><span className="worker-run-model">{model}</span></span><span className="worker-run-quest">{quest?.title || "关联任务未加载"}</span></span>
        <span className="worker-run-state" data-state={field(run.state, "unknown")}>{statusLabel(run.state)}</span></>;
      return <div className="worker-run-entry" key={run.run_id}>
        {quest ? <button type="button" className="worker-run" title={title} onClick={() => onQuest(quest.id)}>{content}</button>
          : <div className="worker-run" title={title}>{content}</div>}
        <WorkerRunDetails run={run} runId={run.run_id} />
      </div>;
    })}</div>}
  </section>;
}

type HistoryProps = { onOpenHistory?: (receiptId: string, path: string) => void; historyStats?: Record<string, { added: number; removed: number }> };
function EventLine({ event, quests, runs, memory, groupExpanded, onQuest, onOpenFile, onInspect, onOpenHistory, historyStats }: { event: TimelineEvent; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; groupExpanded: boolean; onQuest: (id: string) => void; onOpenFile?: (path: string) => void; onInspect: () => void } & HistoryProps) {
  const view = eventView(memory, event), key = eventKey(event);
  const [expanded, setExpanded] = useState(view.expanded || false);
  const [commandExpanded, setCommandExpanded] = useState(view.commandExpanded || false);
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const relatedQuest = quests.find((quest) => quest.id === event.quest_id);
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const filePath = typeof detail.path === "string" ? detail.path : "";
  const fileParts = filePath.replace(/\\/g, "/").split("/");
  const fileName = fileParts.pop() || filePath;
  const fileDirectory = fileParts.length ? `${fileParts.join("/")}/` : "";
  const openFile = () => { if (filePath && onOpenFile) { onInspect(); onOpenFile(filePath); } };
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  const canReadHistory = !!onOpenHistory && event.kind === "tool_receipt" && event.status === "succeeded" && ["live", "mock"].includes(event.execution_mode || "") && ["file_write", "file_revise"].includes(text(detail.tool, "")) && !!filePath && !failed;
  const historyCount = historyStats?.[event.event_id];
  const record = <>
    {workerIdentity(event, runs) && <p className="event-origin" title={workerIdentity(event, runs)}>{workerIdentity(event, runs)}</p>}
    {(event.worker_id || event.run_id) && <WorkerRunDetails run={event.run_id ? runs.find((run) => run.run_id === event.run_id) : undefined} runId={event.run_id} workerId={event.worker_id}
      historicalEvent={eventTitle(event, runs)} historicalTime={event.created_at} initialExpanded={view.workerExpanded || false}
      onExpandedChange={(value) => { view.workerExpanded = value; }} onInspect={onInspect} scrollKey={`event-worker:${key}`} />}
    <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>
    {event.quest_id && <button className="text-button" aria-label="查看关联任务" onClick={() => onQuest(event.quest_id!)}>查看关联任务{relatedQuest ? ` · ${relatedQuest.title}` : ""}</button>}
    <dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数", status: "状态", risk: "风险" } as Record<string, string>)[key] || key}</dt><dd>{key === "tool" ? toolLabel(value) : key === "status" ? statusLabel(value) : key === "risk" ? riskLabel(value) : text(value)}</dd></div>)}</dl>
    <small>记录 ID：{event.event_id}</small>
  </>;
  return <AnimatedDetails onInspect={onInspect} scrollKey={`event:${key}`} initialExpanded={expanded} onExpandedChange={(value) => { view.expanded = value; setExpanded(value); }} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`} summaryTitle={[workerIdentity(event, runs), target].filter(Boolean).join("\n")} summaryAction={filePath && onOpenFile ? <button type="button" className="event-file-open" aria-label={`预览文件 ${filePath}`} title={`预览 ${filePath}`} onClick={openFile}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="2" y="2.5" width="12" height="11" rx="2" /><path d="M9 3v10" /></svg></button> : undefined} summary={<><ActivityIcon event={event} /><span className="event-label">{target || eventTitle(event, runs)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></>}>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} visible={groupExpanded && expanded} expanded={commandExpanded} onExpandedChange={(value) => { view.commandExpanded = value; setCommandExpanded(value); }} savedScrollTop={memory.commandScroll.get(key) || 0} onScroll={(scrollTop) => memory.commandScroll.set(key, scrollTop)} onInspect={onInspect} />}
      {filePath && <button type="button" className="activity-file-row" title={filePath} disabled={!onOpenFile} onClick={openFile}><ActivityIcon event={event} /><span className="activity-file-copy"><span className="activity-file-directory">{fileDirectory}</span><span className="activity-file-name">{fileName}</span></span><span className="activity-file-action">预览</span></button>}
      {canReadHistory && <button type="button" className="text-button activity-history-open" aria-label={`查看文件历史 ${filePath}`} onClick={() => { onInspect(); onOpenHistory?.(event.event_id, filePath); }}>记录的更改{historyCount && <><span className="file-added">+{historyCount.added}</span><span className="file-removed">−{historyCount.removed}</span></>}</button>}
      {typeof detail.command === "string"
        ? <AnimatedDetails className="event-record" initialExpanded={view.recordExpanded || false} onExpandedChange={(value) => { view.recordExpanded = value; }} onInspect={onInspect} summary={<><span>记录详情</span><Chevron /></>}><div className="event-record-content">{record}</div></AnimatedDetails>
        : record}
    </div></AnimatedDetails>;
}

function EventGroup({ item, quests, runs, memory, onQuest, onOpenFile, onInspect, onOpenHistory, historyStats }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; onQuest: (id: string) => void; onOpenFile?: (path: string) => void; onInspect: () => void } & HistoryProps) {
  const [expanded, setExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupExpanded));
  const [filesExpanded, setFilesExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupFilesExpanded));
  // Members inherit the current group state, so splits and prepended group roots restore it.
  useLayoutEffect(() => {
    for (const event of item.events) {
      eventView(memory, event).groupExpanded = expanded;
      eventView(memory, event).groupFilesExpanded = filesExpanded;
    }
  }, [item.events, memory, expanded, filesExpanded]);
  const summary = activitySummary(item.events, runs);
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  const hasMock = item.events.some((event) => event.execution_mode === "mock");
  const recordedFiles = new Map<string, TimelineEvent>();
  for (const event of item.events) {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
    if (event.kind !== "tool_receipt" || event.status !== "succeeded" || event.execution_mode !== "live" || typeof detail.exit_code === "number" && detail.exit_code !== 0 || !["file_write", "file_revise"].includes(text(detail.tool, "")) || typeof detail.path !== "string") continue;
    try { const path = relativeFilePath(detail.path); if (!recordedFiles.has(path)) recordedFiles.set(path, event); } catch { /* An invalid path is not an openable file reference. */ }
  }
  const files = [...recordedFiles.entries()];
  const fileRow = ([path, event]: [string, TimelineEvent]) => {
    const parts = path.split("/"), name = parts.pop() || path, directory = parts.length ? `${parts.join("/")}/` : "";
    return <button type="button" className="activity-file-row" key={path} data-scroll-key={`file:${eventKey(event)}`} title={path} disabled={!onOpenFile} onClick={() => { onInspect(); onOpenFile?.(path); }}><ActivityIcon event={event} /><span className="activity-file-copy"><span className="activity-file-directory">{directory}</span><span className="activity-file-name">{name}</span></span><span className="activity-file-action">预览</span></button>;
  };
  return <AnimatedDetails className="event-group" scrollKey={`group:${eventKey(item.events[0])}`} initialExpanded={expanded} onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupExpanded = value; setExpanded(value); }} onInspect={onInspect} summaryTitle={origins.join("\n")} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon event={item.events[0]} /><span className="event-label">{summary}</span>{hasMock && <small className="event-mode"> · {item.events.every((event) => event.execution_mode === "mock") ? "模拟" : "含模拟记录"}</small>}<Chevron /></>}>
    <div className="event-detail">{files.length > 1 && <div className="activity-group-files"><p className="activity-group-files-label">本组记录的文件</p>{files.slice(0, 3).map(fileRow)}
      {files.length > 3 && <AnimatedDetails className="activity-more-files" scrollKey={`group-files:${eventKey(item.events[0])}`} initialExpanded={filesExpanded}
        onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupFilesExpanded = value; setFilesExpanded(value); }} onInspect={onInspect}
        summary={<><span>再显示 {files.length - 3} 个文件</span><Chevron /></>}><div className="activity-more-files-body">{files.slice(3).map(fileRow)}</div></AnimatedDetails>}
    </div>}{item.events.map((event) => <EventLine key={eventKey(event)} event={event} quests={quests} runs={runs} memory={memory} groupExpanded={expanded} onQuest={onQuest} onOpenFile={onOpenFile} onOpenHistory={onOpenHistory} historyStats={historyStats} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
    if (last?.type === "group" && last.questId === questId) last.events.push(item.value);
    else grouped.push({ type: "group", questId, events: [item.value] });
  }
  return grouped;
}

export default function ChatTimeline({ messages, events, outgoing, quests, workerRuns, approvals, native,
  connected, historyMore, historyBusy, timelineError, conversationError, approvalError,
  canRetry, scrollRef, onScroll, onInspect, onLoadOlder, onRetry, onQuest, onOpenFile, onOpenHistory, historyStats, onApproval, approvalsBlocked, onApprovalDecision }: {
  messages: ChatMessage[]; events: TimelineEvent[]; outgoing: Outgoing[]; quests: Quest[]; workerRuns: WorkerRun[]; approvals: Row[];
  native: boolean; connected: boolean; historyMore: boolean; historyBusy: boolean; timelineError: string;
  conversationError: string; approvalError: string; canRetry: boolean; scrollRef: RefObject<HTMLDivElement>;
  onScroll: () => void; onInspect: () => void; onLoadOlder: () => void; onRetry: (item: Outgoing) => void;
  onQuest: (id: string) => void; onApproval: (id: string) => void;
  onOpenFile?: (path: string) => void;
  approvalsBlocked: boolean; onApprovalDecision: (item: Row, decision: "APPROVED" | "REJECTED") => void;
} & HistoryProps) {
  const memory = useRef<EventViewMemory>({ expansion: new Map(), commandScroll: new Map() }).current;
  const items = groupEvents(mergeTimeline(messages, events, outgoing));
  const active = quests.filter((quest) => !isClosedQuest(quest.status)).sort((left, right) => Number(needsQuestAttention(right.status)) - Number(needsQuestAttention(left.status)));
  return <div className="timeline" ref={scrollRef} onScroll={onScroll} onMouseUp={() => { if (window.getSelection()?.toString()) onInspect(); }} aria-label="对话历史">
    {historyMore && <button className="text-button history" disabled={historyBusy} onClick={onLoadOlder}>{historyBusy ? "正在加载…" : "加载更早的消息与记录"}</button>}
    {conversationError && <p className="notice error" role="alert">{conversationError}</p>}
    {timelineError && <p className="notice error" role="alert">过程记录暂不可用：{timelineError}</p>}
    {!items.length && <div className="empty-conversation"><h2>有什么可以帮你？</h2><p>直接说目标，也可以继续之前的任务。</p></div>}
    {items.map((item) => {
      if (item.type === "group") return <EventGroup key={eventKey(item.events[0])} item={item} quests={quests} runs={workerRuns} memory={memory} onQuest={onQuest} onOpenFile={onOpenFile} onOpenHistory={onOpenHistory} historyStats={historyStats} onInspect={onInspect} />;
      if (item.type === "outgoing") return <article key={`outgoing:${item.value.requestId}`} data-scroll-key={`message:outgoing:${item.value.requestId}`} className="message from-user"><div className="message-meta"><span className="message-avatar">你</span><strong>你</strong><span>{item.value.status === "sending" ? "发送中" : "发送失败"}</span></div><div className="message-body"><MarkdownMessage content={item.value.content} native={native} onInspect={onInspect} />{item.value.status === "failed" && <div className="outgoing-error" role="alert">{item.value.error || "请求未完成"} · 请求 ID：<code>{item.value.requestId}</code><button className="text-button" disabled={!canRetry} onClick={() => onRetry(item.value)}>使用原请求重试</button></div>}</div></article>;
      const message = item.value, meta = messageMetadata(message.metadata);
      return <article key={message.id} data-scroll-key={`message:${message.id}`} className={`message ${message.role === "user" ? "from-user" : "from-agent"}`}><div className="message-meta"><span className="message-avatar">{message.role === "user" ? "你" : "F"}</span><strong>{message.role === "user" ? "你" : "Router"}</strong>{message.role !== "user" && <span className="reply-model" title={[meta.provider_id, meta.model_id].filter(Boolean).join(" / ")}>{meta.source === "router_notice" ? "任务通知" : text(meta.model_id, "模型未记录")}</span>}{meta.execution_mode === "mock" && <span>模拟</span>}{meta.execution_mode === "live" && <span>真实执行</span>}{message.role !== "user" && meta.execution_mode !== "live" && meta.execution_mode !== "mock" && <span>来源未知</span>}<time>{message.created_at ? new Date(message.created_at).toLocaleString() : ""}</time></div><div className="message-body"><MarkdownMessage content={message.content} native={native} onInspect={onInspect} /></div>{message.role !== "user" && <CopyReply content={message.content} onInspect={onInspect} />}</article>;
    })}
    {connected && (active.length > 0 || approvals.length > 0) && <section className="timeline-updates" aria-label="任务与审批更新">
      <div className="timeline-updates-label">已加载的任务与审批</div>
      {approvals.slice(0, 3).map((item) => {
        const quest = quests.find((candidate) => candidate.id === item.quest_id);
        return <div className="timeline-update approval-card" key={text(item.id)}>
          <button className="approval-summary" aria-label={`需要审批 · ${text(item.action_type)} 风险 ${text(item.risk)} · ${text(item.resource_scope)}`} onClick={() => onApproval(text(item.quest_id, ""))}>
            <span><strong>{quest?.title || "关联任务暂未加载"}</strong><small>{statusLabel(item.status, "待审批")} · {toolLabel(item.action_type)} · {riskLabel(item.risk)}</small></span><span aria-hidden="true">›</span>
          </button>
          <div className="approval-scope"><span>{text(item.resource_scope)}</span><small>计划版本 {text(item.plan_revision)}</small></div>
          <AnimatedDetails className="approval-details" onInspect={onInspect} summary={<><span>操作详情</span><Chevron /></>}><dl><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl></AnimatedDetails>
          <div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={approvalsBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => onApprovalDecision(item, decision)}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div>
        </div>;
      })}
      {approvals.length > 3 && <p className="notice">已加载的审批中另有 {approvals.length - 3} 项待处理，审批页按任务筛选 · <button className="text-button" onClick={() => onApproval(text(approvals[0]?.quest_id, ""))}>按任务查看审批</button></p>}
      {active.slice(0, 3).map((quest) => <button className="timeline-update" key={quest.id} aria-label={`${quest.title} 状态：${quest.status} · 版本 ${quest.version}`} onClick={() => onQuest(quest.id)}><span><strong>{quest.title}</strong><small>{statusLabel(quest.status)} · 版本 {quest.version}</small></span><span aria-hidden="true">›</span></button>)}
      {active.length > 3 && <p className="notice">已加载的任务中另有 {active.length - 3} 项未结束 · <button className="text-button" onClick={() => onQuest("")}>查看全部任务</button></p>}
    </section>}
    {connected && approvalError && <p className="notice error" role="alert">审批状态暂不可用：{approvalError}</p>}
  </div>;
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationToolbar({ home, visible, status, sessionTitle, onOpenFiles, onOpenChanges, changesCount, children }: {
  home: boolean; visible: boolean; status: string; sessionTitle?: string; children: ReactNode;
  onOpenFiles?: () => void; onOpenChanges?: () => void; changesCount?: number;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  return <header className="topbar conversation-topbar" hidden={home}>
    <div className="topbar-title" title={sessionTitle}><h1>长期对话</h1></div>
    <div className="conversation-status">
      <span className="router-status" title={status} data-status={status}><span className="status-dot" />Router<span className="router-state-label">{status}</span></span>
      {onOpenFiles && <button type="button" className="conversation-files-toggle" aria-label="查看工作空间文件" title="工作空间文件" onClick={onOpenFiles}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M2 5h5l1.5 1.5H14v6H2V5Zm0 0V3h5l1.5 2" /></svg></button>}
      <div className="worker-menu-anchor">
        <button ref={trigger} type="button" className="worker-toggle" aria-label="查看 Worker 执行" aria-expanded={open} aria-controls="conversation-workers" onClick={() => setOpen((value) => !value)}>Worker<svg data-chevron viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button>
        <DisclosurePopover open={open && visible} onClose={close} trigger={trigger} id="conversation-workers" label="Worker 执行详情" className="worker-drawer">
          {onOpenChanges && <button type="button" className="conversation-changes-overview" onClick={() => { setOpen(false); onOpenChanges(); }}><span>文件变更</span><span>{typeof changesCount === "number" ? `${changesCount} 个文件` : "查看"}<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></span></button>}
          {children}
        </DisclosurePopover>
      </div>
    </div>
  </header>;
}
import { useCallback, useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationComposer({ inputRef, value, onChange, onKeyDown, onSend, onConfigure, disabled, sending, workspace, workspaceName, native, model, provider, status, visible, error, requestId, fileChanges, onOpenChanges }: {
  inputRef: RefObject<HTMLTextAreaElement>; value: string; onChange: (value: string) => void;
  onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void; onSend: () => void;
  onConfigure: (setting: "environment" | "models") => void;
  disabled: boolean; sending: boolean; workspace: string; workspaceName: string; native: boolean;
  model: string; provider: string; status: string; visible: boolean; error: string; requestId?: string;
  fileChanges?: number; onOpenChanges?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  const configure = (setting: "environment" | "models") => { setOpen(false); onConfigure(setting); };
  return <footer className="composer-wrap"><div className="composer-stack">
    {onOpenChanges && typeof fileChanges === "number" && fileChanges > 0 && <div className="composer-changes"><button type="button" title="已加载对话中成功写入的真实文件记录；不代表当前 Git 变更总数。" onClick={onOpenChanges}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2.5h5l3 3v8H4v-11Zm5 0v3h3M6 9h4M8 7v4" /></svg>{fileChanges} 个文件已更改</button></div>}
    <div className="composer-context">
      <span title={workspace}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 7h7l2 2h9v10H3V7Zm0 0V5h7l2 2" /></svg><span className="composer-workspace-name">{workspaceName}</span></span>
      <span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="12" rx="1.5" /><path d="M2 20h20M9 16v4m6-4v4" /></svg>{native ? "本地" : "开发连接"}</span>
    </div>
    <div className="composer">
      <textarea ref={inputRef} value={value} onChange={(event) => onChange(event.target.value)} onKeyDown={onKeyDown} placeholder="给 Router 发送消息…" aria-label="消息内容" />
      <div className="composer-bottom">
        <span className="composer-router" title={status}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m12 3 7.5 4.5v9L12 21l-7.5-4.5v-9L12 3Z" /><path d="m4.5 7.5 7.5 5 7.5-5M12 12.5V21" /></svg>Router</span>
        <span className="composer-keyboard sr-only">Enter 发送 · Shift + Enter 换行</span>
        <div className="composer-model-anchor">
          <button ref={trigger} type="button" className="composer-model" aria-label="查看 Router 配置" aria-expanded={open} aria-controls="router-model-configuration" title={[provider, model].filter(Boolean).join(" / ")} onClick={() => setOpen((value) => !value)}><span>{model}</span><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m5 6 3 3 3-3" /></svg></button>
          <DisclosurePopover open={open && visible} onClose={close} trigger={trigger} id="router-model-configuration" label="Router 模型配置" className="composer-model-menu">
            <div className="model-menu-current"><span className="model-menu-label">当前 Router</span><strong className="router-model">{model}</strong><span className="router-provider">{provider || "供应商未记录"}</span></div>
            <div className="model-menu-actions"><button type="button" aria-label="环境" onClick={() => configure("environment")}>运行配置<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button><button type="button" onClick={() => configure("models")}>模型库<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></button></div>
          </DisclosurePopover>
        </div>
        <button className="send-button" aria-label="发送消息" disabled={disabled} onClick={onSend}>{sending ? <span className="loading-spinner" aria-hidden="true" /> : <svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M10 16V4m-5 5 5-5 5 5" /></svg>}</button>
      </div>
    </div>
  </div>{error && <p className="send-error" role="alert">{error} 草稿已保留。请求 ID：<code>{requestId}</code></p>}</footer>;
}
import { useEffect, useRef, useState } from "react";
import AnimatedDetails from "./AnimatedDetails";
import { request, type Connection } from "./api";
import { errorMessage } from "./logic";
import { statusLabel } from "./presentation";

export interface WorkerRun {
  run_id: string;
  worker_id?: string;
  quest_id?: string;
  role?: string;
  state?: string;
  provider_id?: string;
  model_id?: string;
  steps?: number;
  tool_spent?: number;
  created_at?: string;
  output_contract?: string;
}

export interface ActivityState {
  items: WorkerRun[];
  loading: boolean;
  error: string;
  hasMore: boolean;
  connected: boolean;
}

interface ActivityPage { items: WorkerRun[]; has_more?: boolean }
interface ActivitySnapshot { identity: string; state: ActivityState }

const emptyActivity = (connected: boolean): ActivityState => ({
  items: [], loading: connected, error: "", hasMore: false, connected,
});
const connectionIdentity = (connection: Connection | null) => connection
  ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";

/** This read-only feed runs independently so a slow activity request cannot delay chat. */
export function useWorkerActivity(connection: Connection | null): ActivityState {
  const identity = connectionIdentity(connection);
  const currentIdentity = useRef(identity);
  currentIdentity.current = identity;
  const [snapshot, setSnapshot] = useState<ActivitySnapshot>(() => ({ identity, state: emptyActivity(!!connection) }));

  useEffect(() => {
    if (!connection) {
      setSnapshot({ identity, state: emptyActivity(false) });
      return;
    }
    let active = true;
    let inFlight = false;
    let controller: AbortController | null = null;
    setSnapshot({ identity, state: emptyActivity(true) });
    const accepts = () => active && currentIdentity.current === identity;
    const poll = async () => {
      if (!accepts() || inFlight) return;
      inFlight = true;
      const pending = new AbortController();
      controller = pending;
      const timeout = window.setTimeout(() => pending.abort(), 120000);
      try {
        const page = await request<ActivityPage>(connection, "/api/activity?limit=100", { signal: pending.signal });
        if (!Array.isArray(page.items)) throw new Error("Core 返回了无效执行记录。");
        const items = [...new Map(page.items.filter((item) => item && typeof item === "object" && typeof item.run_id === "string" && item.run_id)
          .map((item) => [item.run_id, item])).values()];
        if (accepts()) setSnapshot({ identity, state: { items, loading: false, error: "", hasMore: page.has_more === true, connected: true } });
      } catch (error) {
        // Old running states must never be presented as the current state after a failed read.
        if (accepts()) setSnapshot({ identity, state: { items: [], loading: false, error: errorMessage(error), hasMore: false, connected: true } });
      } finally {
        window.clearTimeout(timeout);
        if (controller === pending) controller = null;
        inFlight = false;
      }
    };
    void poll();
    const timer = window.setInterval(() => void poll(), 6000);
    return () => { active = false; window.clearInterval(timer); controller?.abort(); };
  }, [identity, connection?.bearer]);

  // Hide a previous workspace synchronously, before the effect starts its next request.
  return snapshot.identity === identity ? snapshot.state : emptyActivity(!!connection);
}

const field = (value: unknown, fallback: string) => typeof value === "string" && value ? value : fallback;
const RUN_PRIORITY: Record<string, number> = { running: 0, blocked: 1, queued: 2, review_pending: 3, paused: 4 };
const priority = (run: WorkerRun) => RUN_PRIORITY[field(run.state, "")] ?? 5;

const count = (value: unknown) => typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value.toLocaleString() : "未知";

/** Match callers by run_id; a Worker's newer run cannot replace a historical run. */
export function WorkerRunDetails({ run, runId, workerId, historicalEvent, historicalTime, initialExpanded = false, onExpandedChange, onInspect = () => {}, scrollKey }: {
  run?: WorkerRun; runId?: string | null; workerId?: string | null; historicalEvent?: string; historicalTime?: string;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; onInspect?: () => void; scrollKey?: string;
}) {
  const matched = run && typeof runId === "string" && run.run_id === runId ? run : undefined;
  return <AnimatedDetails className="worker-run-details" summaryLabel={`查看 Worker 执行详情${runId ? ` ${runId}` : ""}`} scrollKey={scrollKey}
    initialExpanded={initialExpanded} onExpandedChange={onExpandedChange} onInspect={onInspect}
    summary={<><span>执行详情</span><svg data-chevron viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg></>}>
    <div className="worker-run-details-body">
      {historicalEvent && <dl className="worker-history-facts"><dt>历史事件</dt><dd>{historicalEvent}</dd><dt>记录时间</dt><dd>{historicalTime || "时间未记录"}</dd></dl>}
      {!matched && <p className="worker-details-notice">执行详情暂未加载。</p>}
      {matched && <><dl className="worker-current-facts">
        <dt>角色</dt><dd>{field(matched.role, "未记录")}</dd>
        <dt>供应商</dt><dd>{field(matched.provider_id, "未记录")}</dd>
        <dt>模型</dt><dd>{field(matched.model_id, "模型未记录")}</dd>
        <dt>当前执行状态</dt><dd>{statusLabel(matched.state)}</dd>
        <dt>已记录步数</dt><dd>{count(matched.steps)}</dd>
        <dt>工具调用次数</dt><dd>{count(matched.tool_spent)}</dd>
      </dl>{historicalEvent && <p className="worker-details-notice">当前执行状态来自最近读取的运行记录，历史事件保留当时的记录。</p>}</>}
      <dl className="worker-identity-facts"><dt>Worker</dt><dd>{field(matched?.worker_id || workerId, "未记录")}</dd><dt>Run</dt><dd>{field(runId, "未记录")}</dd></dl>
    </div>
  </AnimatedDetails>;
}

export default function WorkerActivity({ state, quests, onQuest, onActivity }: {
  state: ActivityState;
  quests: { id: string; title: string }[];
  onQuest: (id: string) => void;
  onActivity: () => void;
}) {
  const visible = state.connected && !state.error ? [...state.items].sort((left, right) => priority(left) - priority(right)).slice(0, 3) : [];
  const notice = !state.connected ? "连接 Core 后查看执行记录" : state.loading ? "正在读取执行记录…"
    : state.error ? "执行状态暂不可用" : !state.items.length ? "暂无执行记录" : "";
  const summary = `最近执行${state.connected && !state.loading && !state.error ? ` · 已加载 ${state.items.length} 条${state.hasMore ? " · 还有更早记录" : ""}` : ""}`;
  return <section className="worker-activity" aria-label="Worker 执行记录" aria-busy={state.loading}>
    <div className="worker-activity-header"><div className="worker-activity-heading"><strong>Worker</strong><small title={summary}>{summary}</small></div>
      <button type="button" className="text-button worker-activity-open" disabled={!state.connected} onClick={onActivity}>查看运行活动</button>
    </div>
    {notice && <p className="worker-activity-notice" title={state.error || undefined}>{notice}</p>}
    {visible.length > 0 && <div className="worker-activity-list">{visible.map((run) => {
      const quest = quests.find((item) => item.id === run.quest_id);
      const model = field(run.model_id, "模型未记录");
      const title = `角色：${field(run.role, "未记录")}\n供应商：${field(run.provider_id, "未记录")}\n模型：${model}\nWorker：${field(run.worker_id, "未记录")}\nRun：${run.run_id}\n任务：${quest?.title || field(run.quest_id, "未记录")}`;
      const content = <><span className="worker-run-content"><span className="worker-run-heading"><strong>{field(run.role, "Worker")}</strong><span className="worker-run-model">{model}</span></span><span className="worker-run-quest">{quest?.title || "关联任务未加载"}</span></span>
        <span className="worker-run-state" data-state={field(run.state, "unknown")}>{statusLabel(run.state)}</span></>;
      return <div className="worker-run-entry" key={run.run_id}>
        {quest ? <button type="button" className="worker-run" title={title} onClick={() => onQuest(quest.id)}>{content}</button>
          : <div className="worker-run" title={title}>{content}</div>}
        <WorkerRunDetails run={run} runId={run.run_id} />
      </div>;
    })}</div>}
  </section>;
}
