.conversation-status { display: flex; align-items: center; gap: 16px; flex: none; color: var(--muted); font-size: 12px; line-height: 20px; }
.router-status { display: inline-flex; align-items: center; }
.worker-menu-anchor, .composer-model-anchor { position: relative; }
.worker-toggle { display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 4px 6px; border: 0; border-radius: 7.5px; background: none; color: var(--muted); font-size: 12px; line-height: 20px; }
