.worker-run-details > summary > svg { flex: none; width: 16px; height: 16px; }
.worker-run-entry > .worker-run-details { margin: 0 8px 4px; }
.worker-run-details-body { min-width: 0; padding: 8px 0 8px 16px; }
.worker-run-details-body dl { display: grid; grid-template-columns: minmax(64px,auto) minmax(0,1fr); gap: 4px 12px; margin: 0; font-size: 12px; line-height: 18px; }
