.timeline > * { width: 100%; max-width: 736px; min-width: 0; margin-inline: auto; }
.home-state .timeline { display: grid; place-items: center; padding-block: 0; }
.empty-conversation { display: flex; flex-direction: column; align-items: center; gap: 12px; transform: translateY(-24px); text-align: center; }
.empty-conversation h2 { margin: 0; color: var(--color-text); font-size: 28px; line-height: 36px; font-weight: 500; }
