.message.from-agent .message-body { padding: 0; border-radius: 0; background: none; }
.message-meta { position: absolute; bottom: -22px; inset-inline-start: 0; display: flex; align-items: center; gap: 8px; max-width: calc(100% - 40px); height: 20px; color: var(--muted); font-size: 12px; line-height: 16px; opacity: 0; transition: opacity .15s var(--ease-out); }
.message.from-user .message-meta { inset-inline-start: auto; inset-inline-end: 0; max-width: 100%; }
.message-meta strong { font-size: 12px; font-weight: 400; }
.message-meta time { flex: none; font-size: 11px; }
.message-avatar { display: none; }
.reply-model { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.message-actions { position: absolute; right: 0; bottom: -24px; display: flex; align-items: center; gap: 8px; opacity: 0; transition: opacity .15s var(--ease-out); }
