.message:hover .message-meta, .message:focus-within .message-meta, .message:hover .message-actions, .message:focus-within .message-actions { opacity: 1; }
.copy-feedback { position: absolute; right: 34px; white-space: nowrap; color: var(--muted); font-size: 12px; }
.history { display: block; margin: 0 auto 24px; }
.outgoing-error { margin-top: 8px; color: var(--color-status-error); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
.outgoing-error button { margin-left: 8px; }
.send-error, .action-error { max-width: 736px; margin: 8px auto 0; color: var(--color-status-error); font-size: 12px; line-height: 18px; overflow-wrap: anywhere; }
