def _cursor(value):
    if value is None:
        return None
    try:
        decoded = base64.urlsafe_b64decode(value + "=" * (-len(value) % 4)).decode("ascii")
        if (
            not decoded.isascii()
            or not decoded.isdecimal()
            or len(decoded) > 18
            or int(decoded) < 1
        ):
            raise ValueError
        return int(decoded)
    except (ValueError, UnicodeError):
        raise HTTPException(status_code=422, detail="Invalid cursor") from None

