}

export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control settings-row-value">{children}</div>
  </div>;
}

/** A shared section keeps every settings page on the same title and row grid. */
export function SettingsSection({ title, description, children, className = "" }: {
  title: ReactNode; description?: ReactNode; children: ReactNode; className?: string;
}) {
  return <section className={`settings-block ${className}`}>
    <h2 className="settings-block-heading">{title}</h2>
    {description && <p className="settings-block-description">{description}</p>}
    <div className="settings-group">{children}</div>
  </section>;
}

export default function SettingsView({ selected, onSelect, onClose, children }: { selected: SettingId; onSelect: (id: SettingId) => void; onClose: () => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const searchInput = useRef<HTMLInputElement>(null);
  const itemButtons = useRef<Partial<Record<SettingId, HTMLButtonElement | null>>>({});
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.description} ${item.accessibleLabel || ""} ${item.keywords || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const visibleItems = groups.flatMap((group) => group.items);
  const current = settingMetadata[selected];
  const clearSearch = () => { setQuery(""); searchInput.current?.focus(); };
  const activate = (item: SettingItem) => { onSelect(item.id); itemButtons.current[item.id]?.focus(); };
  const navigate = (event: KeyboardEvent<HTMLButtonElement>, id: SettingId) => {
    if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229 || event.altKey || event.ctrlKey || event.metaKey) return;
    const index = visibleItems.findIndex((item) => item.id === id);
    const next = event.key === "ArrowDown" ? (index + 1) % visibleItems.length
      : event.key === "ArrowUp" ? (index - 1 + visibleItems.length) % visibleItems.length
      : event.key === "Home" ? 0 : event.key === "End" ? visibleItems.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    activate(visibleItems[next]);
  };
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-nav-header"><h1 className="settings-page-title">设置</h1><button type="button" className="settings-back" aria-label="返回对话" title="返回对话" onClick={onClose}><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m10 5-7 7 7 7M3 12h18" /></svg></button></div><div className="settings-search"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg><input ref={searchInput} type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
        if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229) return;
        if (event.key === "Escape") { event.preventDefault(); clearSearch(); }
        else if (event.key === "Enter" && visibleItems.length) { event.preventDefault(); activate(visibleItems[0]); }
      }} />{query && <button type="button" className="settings-search-clear" aria-label="清除设置搜索" title="清除设置搜索" onClick={clearSearch}><svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true"><path d="m4 4 8 8m0-8-8 8" /></svg></button>}</div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} ref={(button) => { itemButtons.current[item.id] = button; }} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onKeyDown={(event) => navigate(event, item.id)} onClick={() => onSelect(item.id)}><SettingsIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <div className="settings-search-empty"><p className="notice">未找到匹配的设置</p><button type="button" className="text-button" onClick={clearSearch}>显示全部设置</button></div>}
    </nav>
    <div className="settings-content"><div className="settings-content-inner" data-setting={selected}><header className="settings-content-header"><h1 className="settings-title">{current.label}</h1><p className="sr-only">{current.description}</p></header>{children}</div></div>
  </section>;
}

import { capabilityLabel } from "./presentation";

type Row = Record<string, unknown>;
const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const object = (value: unknown): Row => value && typeof value === "object" && !Array.isArray(value) ? value as Row : {};

function support(value: unknown): string {
  const entry = object(value);
  const label = entry.supported === true ? "支持" : entry.supported === false ? "不支持" : "未知";
  return entry.source ? `${label} · ${text(entry.source)}` : label;
}

function price(value: unknown, currency: unknown): string {
  return typeof value === "number" && Number.isFinite(value) ? `${value.toLocaleString()} ${text(currency, "币种未知")} / 百万 Token` : "未知";
}

function MeasurementList({ value, performance = false }: { value: unknown; performance?: boolean }) {
  const entries = Object.entries(object(value));
  if (!entries.length) return <p className="notice">{performance ? "性能测量：未知" : "能力评分：未知"}</p>;
  const performanceNames: Record<string, string> = { tokens_per_second: "输出速度（Token/s）", ttft_seconds: "首 Token 时间（秒）", latency_p50_seconds: "P50 延迟（秒）", latency_p95_seconds: "P95 延迟（秒）", reliability: "可靠率", timeout_rate: "超时率" };
  return <div className="measurement-list">{entries.map(([name, value]) => {
    const entry = object(value);
    return <div key={name}><span>{performance ? performanceNames[name] || name : capabilityLabel(name)}</span><span>{text(entry.value)} · {text(entry.source)} · {entry.n_samples == null ? entry.source === "user_override" ? "未采样（0）" : "样本未知" : `样本 ${text(entry.n_samples)}`} · 置信度 {text(entry.confidence)}<br />观测时间：{text(entry.observed_at)}{entry.benchmark_version != null && <> · 基准 {text(entry.benchmark_version)}</>}</span></div>;
  })}</div>;
}

export default function ModelProfileSummary({ model }: { model: Row }) {
  const state = model.enabled === true ? "已启用" : model.enabled === false ? "已禁用" : "状态未知";
  const tools = object(model.tool_calling_support).supported;
  const schema = object(model.structured_output_support).supported;
  return <div className="model-profile-summary">
    <div className="model-profile-heading">
      <span className="model-profile-name"><strong>{text(model.display_name, text(model.model_id ?? model.id))}</strong><small>{text(model.provider ?? model.provider_id)} / {text(model.model_id)}</small></span>
      <span className="model-profile-state" data-enabled={String(model.enabled)}>{state}</span>
    </div>
    <details className="settings-disclosure model-profile-details"><summary>档案与能力详情</summary><div className="settings-disclosure-body">
      <div className="model-profile-capabilities">
        <span>上下文窗口 <b>{text(model.context_window)}</b></span>
        <span>工具调用 <b>{tools === true ? "支持" : tools === false ? "不支持" : "未知"}</b></span>
        <span>结构化输出 <b>{schema === true ? "支持" : schema === false ? "不支持" : "未知"}</b></span>
      </div>
      <dl><dt>档案 ID</dt><dd className="break">{text(model.id)}</dd>
        <dt>上下文窗口</dt><dd>{text(model.context_window)}</dd><dt>最大输出</dt><dd>{text(model.max_output_tokens)}</dd>
        <dt>工具调用</dt><dd>{support(model.tool_calling_support)}</dd><dt>结构化输出</dt><dd>{support(model.structured_output_support)}</dd>
        <dt>输入价格</dt><dd>{price(model.input_cost_per_million, model.currency)}</dd><dt>输出价格</dt><dd>{price(model.output_cost_per_million, model.currency)}</dd>
        <dt>能力来源</dt><dd>{text(object(model.provenance).source)}</dd>
        <dt>可用能力</dt><dd>{Object.keys(object(model.capabilities)).map((name) => capabilityLabel(name)).join("、") || "未知"}</dd>
      </dl>
      <MeasurementList value={model.capability_measurements} />
      <details className="settings-disclosure"><summary>性能与缓存价格</summary><div className="settings-disclosure-body"><dl>
        <dt>缓存输入</dt><dd>{price(model.cached_input_cost_per_million, model.currency)}</dd>
        <dt>输出速度</dt><dd>{text(model.tokens_per_second)} Token/s</dd><dt>首 Token</dt><dd>{text(model.ttft_seconds)} 秒</dd>
        <dt>健康状态</dt><dd>{text(model.health)}</dd>
      </dl><MeasurementList value={model.performance_measurements} performance />
      </div></details>
    </div></details>
  </div>;
}

