  return <div className="preview-divider" role="separator" aria-label="调整文件预览宽度" aria-orientation="vertical" aria-valuemin={34} aria-valuemax={76} aria-valuenow={Math.round(width)} tabIndex={0} onPointerDown={(event) => { drag.current = { x: event.clientX, width }; event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={move} onPointerUp={(event) => { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); }} onPointerCancel={() => { drag.current = null; }} onKeyDown={(event) => { if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) { event.preventDefault(); onResize(event.key === "Home" ? 34 : event.key === "End" ? 76 : clamp(width + (event.key === "ArrowLeft" ? 2 : -2))); } }} />;
}

import { useLayoutEffect, useRef, useState, type RefObject } from "react";

type ReadingAnchor = { key: string; offset: number; top: number };

// The same cubic-bezier(0,0,.2,1) used by disclosures, evaluated for measured layout.
function easeOut(progress: number) {
  let low = 0, high = 1;
  for (let step = 0; step < 12; step += 1) {
    const time = (low + high) / 2;
    if (.6 * time * time + .4 * time * time * time < progress) low = time;
    else high = time;
  }
  const time = (low + high) / 2;
  return 3 * time * time - 2 * time * time * time;
}

