function ChangeDirectory({ files, active, onOpen, root = "", depth = 0 }: { files: ChangeSet["files"]; active: string; onOpen: (path: string) => void; root?: string; depth?: number }) {
  const [closed, setClosed] = useState(new Set<string>());
