    <div hidden={closed.has(name)}><ChangeDirectory files={children} root={`${root}${name}/`} depth={depth + 1} active={active} onOpen={onOpen} /></div>
  </div>)}{leaves.map((file) => <button type="button" key={file.path} className={`file-tree-row changed-file${active === file.path ? " selected" : ""}`} data-status={file.status.trim()} style={{ paddingInlineStart: 22 + depth * 14 }} title={file.path} onClick={() => onOpen(file.path)}><FileIcon /><span>{file.path.slice(root.length)}</span>{file.added !== undefined && <small className="file-added">+{file.added}</small>}{file.removed !== undefined && <small className="file-removed">−{file.removed}</small>}<span className="file-change-status">{file.status}</span></button>)}</>;
}

