.artifact-history-heading > div:first-child { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.artifact-history-heading strong { font-size: 13px; line-height: 20px; font-weight: 500; }
.artifact-history-heading span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); font-size: 12px; line-height: 18px; }
.artifact-history-actions { display: flex; gap: 4px; flex: none; }
.artifact-history-record { flex: none; max-height: 38%; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 12px 16px 8px; }
